export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/deployments.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e2d5e041c7b23808fe2507b9305fa889b414d4df349f6a1a6c1c39514ccd16af\",\"content\":\"from __future__ import annotations\\n\\nimport time\\nfrom collections.abc import AsyncIterator\\nfrom dataclasses import dataclass\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Path, Query, Response, status\\nfrom fastapi_pagination import Params\\nfrom lfx.log.logger import logger\\nfrom lfx.services.adapters.deployment.schema import (\\n    DeploymentGetResult,\\n    DeploymentListTypesResult,\\n    DeploymentType,\\n    DeploymentUpdateResult,\\n)\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession, DbSessionReadOnly\\nfrom langflow.api.v1.mappers.deployments import get_deployment_mapper\\nfrom langflow.api.v1.mappers.deployments.helpers import (\\n    apply_flow_version_patch_attachments,\\n    attach_flow_versions,\\n    deployment_pagination_params,\\n    ensure_flow_deploy_for_version_ids,\\n    flow_version_ids_for_flows,\\n    get_deployment_row_or_404,\\n    get_deployment_synced,\\n    get_owned_provider_account_or_404,\\n    get_shared_listing_provider_account_or_404,\\n    handle_adapter_errors,\\n    list_deployment_flow_versions_synced,\\n    list_deployments_synced,\\n    page_offset,\\n    raise_http_for_value_error,\\n    resolve_adapter_from_deployment,\\n    resolve_adapter_mapper_from_deployment,\\n    resolve_added_snapshot_bindings_for_update,\\n    resolve_deployment_adapter,\\n    resolve_flow_version_patch_for_update,\\n    resolve_project_id_for_deployment_create,\\n    resolve_snapshot_map_for_create,\\n    rollback_provider_create,\\n    rollback_provider_update,\\n    validate_project_scoped_flow_version_ids,\\n)\\nfrom langflow.api.v1.schemas.deployments import (\\n    DeploymentConfigListResponse,\\n    DeploymentCreateRequest,\\n    DeploymentCreateResponse,\\n    DeploymentFlowVersionListResponse,\\n    DeploymentGetResponse,\\n    DeploymentListResponse,\\n    DeploymentLlmListResponse,\\n    DeploymentProviderAccountCreateRequest,\\n    DeploymentProviderAccountGetResponse,\\n    DeploymentProviderAccountListResponse,\\n    DeploymentProviderAccountUpdateRequest,\\n    DeploymentSnapshotListResponse,\\n    DeploymentTypeListResponse,\\n    DeploymentUpdateRequest,\\n    DeploymentUpdateResponse,\\n    FlowIdsQuery,\\n    FlowVersionIdsQuery,\\n    RunCreateRequest,\\n    RunCreateResponse,\\n    RunStatusResponse,\\n    SnapshotUpdateRequest,\\n    SnapshotUpdateResponse,\\n)\\nfrom langflow.services.adapters.deployment.context import deployment_provider_scope\\nfrom langflow.services.authorization import (\\n    DeploymentAction,\\n    ProviderAccountAction,\\n    ensure_deployment_permission,\\n    ensure_provider_account_permission,\\n    filter_visible_resources,\\n    visible_scope_prefilter,\\n)\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.authorization.utils import _resolve_authz_domain\\nfrom langflow.services.database.models.deployment.crud import (\\n    UNCONFIRMED_DELETE_ROWCOUNT,\\n    count_deployments_by_provider,\\n    delete_deployment_by_id,\\n    get_deployment_by_resource_key,\\n    has_visible_deployment_for_provider,\\n)\\nfrom langflow.services.database.models.deployment.crud import (\\n    create_deployment_from_model as create_deployment_db,\\n)\\nfrom langflow.services.database.models.deployment.crud import (\\n    update_deployment as update_deployment_db,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    count_provider_accounts as count_provider_account_rows,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    create_provider_account_from_model as create_provider_account_row,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    delete_provider_account as delete_provider_account_row,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    get_provider_account_by_id as get_provider_account_row_by_id,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    list_provider_accounts as list_provider_account_rows,\\n)\\nfrom langflow.services.database.models.deployment_provider_account.crud import (\\n    update_provider_account as update_provider_account_row,\\n)\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.flow_version_deployment_attachment.crud import (\\n    AttachmentConflictError,\\n    list_attachments_by_provider_snapshot_id,\\n    list_deployment_attachments_for_flow_version_ids,\\n    update_flow_version_by_provider_snapshot_id,\\n)\\nfrom langflow.services.deps import get_authorization_service, get_telemetry_service\\nfrom langflow.services.telemetry.schema import DeploymentPayload\\n\\n\\n@dataclass\\nclass DeploymentTelemetryCtx:\\n    \\\"\\\"\\\"Mutable context that routes write into; passed via Depends.\\\"\\\"\\\"\\n\\n    provider: str = \\\"unknown\\\"\\n    wxo_tenant_id: str | None = None\\n\\n\\ndef _make_telemetry_dep(action: str, log_method_name: str):\\n    async def _dep() -> AsyncIterator[DeploymentTelemetryCtx]:\\n        ctx = DeploymentTelemetryCtx()\\n        started_at = time.perf_counter()\\n        success: bool = True\\n        error_message: str = \\\"\\\"\\n        try:\\n            yield ctx\\n        except Exception as exc:\\n            success = False\\n            error_message = str(exc)\\n            raise\\n        finally:\\n            try:\\n                ts = get_telemetry_service()\\n                payload = DeploymentPayload(\\n                    deployment_action=action,\\n                    deployment_provider=ctx.provider,\\n                    deployment_seconds=time.perf_counter() - started_at,\\n                    deployment_success=success,\\n                    deployment_error_message=error_message,\\n                    wxo_tenant_id=ctx.wxo_tenant_id,\\n                )\\n                await getattr(ts, log_method_name)(payload)\\n            except Exception:  # noqa: BLE001\\n                logger.debug(\\\"deployment telemetry emit failed\\\", exc_info=True)\\n\\n    return _dep\\n\\n\\ndeployment_create_telemetry = _make_telemetry_dep(\\\"deployment.create\\\", \\\"log_package_deployment\\\")\\ndeployment_update_telemetry = _make_telemetry_dep(\\\"deployment.update\\\", \\\"log_package_deployment\\\")\\ndeployment_delete_telemetry = _make_telemetry_dep(\\\"deployment.delete\\\", \\\"log_package_deployment\\\")\\ndeployment_run_telemetry = _make_telemetry_dep(\\\"deployment.run\\\", \\\"log_package_deployment_run\\\")\\nprovider_create_telemetry = _make_telemetry_dep(\\\"provider.create\\\", \\\"log_package_deployment_provider\\\")\\nprovider_update_telemetry = _make_telemetry_dep(\\\"provider.update\\\", \\\"log_package_deployment_provider\\\")\\nprovider_delete_telemetry = _make_telemetry_dep(\\\"provider.delete\\\", \\\"log_package_deployment_provider\\\")\\nsnapshot_update_telemetry = _make_telemetry_dep(\\\"snapshot.update\\\", \\\"log_package_deployment\\\")\\n\\n\\nrouter = APIRouter(prefix=\\\"/deployments\\\", tags=[\\\"Deployments\\\"], include_in_schema=False)\\n\\nDeploymentProviderAccountIdQuery = Annotated[\\n    UUID,\\n    Query(description=\\\"Langflow DB provider-account UUID (`deployment_provider_account.id`).\\\"),\\n]\\nDeploymentProviderAccountIdPath = Annotated[\\n    UUID,\\n    Path(description=\\\"Langflow DB provider-account UUID (`deployment_provider_account.id`).\\\"),\\n]\\nDeploymentIdPath = Annotated[\\n    UUID,\\n    Path(description=\\\"Langflow DB deployment UUID (`deployment.id`).\\\"),\\n]\\nProjectIdQuery = Annotated[\\n    UUID | None,\\n    Query(description=\\\"Optional project (folder) id. Filters deployments to this project.\\\"),\\n]\\nDeploymentIdQuery = Annotated[\\n    UUID,\\n    Query(description=\\\"Langflow DB deployment UUID (`deployment.id`).\\\"),\\n]\\nIncludeProviderDeleteQuery = Annotated[\\n    bool,\\n    Query(\\n        description=(\\n            \\\"When true (default), deletes the deployment resource (e.g., agent) on the provider, \\\"\\n            \\\"then removes the local DB row. Other provider-managed resources \\\"\\n            \\\"(for example, tools and connections) are NOT deleted. \\\"\\n            \\\"When false, only the local Langflow DB row is removed; \\\"\\n            \\\"nothing is changed on the provider.\\\"\\n        ),\\n    ),\\n]\\n\\n\\ndef _field_was_explicitly_set(model: object, field_name: str) -> bool:\\n    \\\"\\\"\\\"Return True when a Pydantic-style model explicitly received *field_name*.\\n\\n    Falls back to False for mocks and non-Pydantic objects so route handler unit\\n    tests that use ``MagicMock`` payloads keep their previous behavior.\\n    \\\"\\\"\\\"\\n    fields_set = getattr(model, \\\"model_fields_set\\\", None)\\n    return isinstance(fields_set, set) and field_name in fields_set\\n\\n\\ndef _raise_http_for_provider_account_value_error(exc: ValueError) -> None:\\n    message = str(exc).lower()\\n    if \\\"already exists\\\" in message or \\\"conflicts with an existing record\\\" in message:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Provider account is already tracked by user.\\\",\\n        ) from exc\\n    raise_http_for_value_error(exc)\\n\\n\\nasync def _count_provider_deployments_after_reconciliation(\\n    *,\\n    session: DbSession,\\n    provider_account,\\n    user_id: UUID,\\n) -> int:\\n    \\\"\\\"\\\"Return remaining deployments after best-effort stale-row reconciliation.\\\"\\\"\\\"\\n    deployment_count = await count_deployments_by_provider(\\n        session,\\n        user_id=user_id,\\n        row_owner_id=user_id,\\n        deployment_provider_account_id=provider_account.id,\\n    )\\n    if deployment_count <= 0:\\n        return 0\\n\\n    try:\\n        deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n        deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n        with deployment_provider_scope(provider_account.id):\\n            _, deployment_count, _ = await list_deployments_synced(\\n                deployment_adapter=deployment_adapter,\\n                deployment_mapper=deployment_mapper,\\n                user_id=user_id,\\n                row_owner_id=user_id,\\n                provider_id=provider_account.id,\\n                db=session,\\n                page=1,\\n                size=deployment_count,\\n                deployment_type=None,\\n            )\\n    except Exception:  # noqa: BLE001\\n        logger.warning(\\n            \\\"Failed to reconcile deployments before deleting provider account %s; falling back to local count.\\\",\\n            provider_account.id,\\n            exc_info=True,\\n        )\\n\\n    return deployment_count\\n\\n\\nasync def _delete_deployment_strictly_or_raise(\\n    *,\\n    session: DbSession,\\n    deployment_id: UUID,\\n    user_id: UUID,\\n) -> None:\\n    \\\"\\\"\\\"Delete exactly one deployment row by PK + owner scope, or raise.\\n\\n    Raises:\\n        HTTPException: 404 when the driver confirmed zero rows matched; 500 when\\n            the affected-row count could not be confirmed\\n            (:data:`UNCONFIRMED_DELETE_ROWCOUNT`).\\n    \\\"\\\"\\\"\\n    deleted = await delete_deployment_by_id(session, user_id=user_id, deployment_id=deployment_id)\\n    if deleted is UNCONFIRMED_DELETE_ROWCOUNT:\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail=\\\"Deployment delete could not be confirmed.\\\",\\n        )\\n    if deleted == 0:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Deployment not found.\\\")\\n\\n\\nasync def _delete_local_deployment_row(\\n    *,\\n    session: DbSession,\\n    deployment_id: UUID,\\n    user_id: UUID,\\n    resource_key: str,\\n) -> None:\\n    \\\"\\\"\\\"Delete the local deployment row, retrying once if the commit fails.\\n\\n    When ``include_provider`` was true on the route, the provider resource is\\n    already gone (or was already missing) before this helper runs. Either way,\\n    if the first DB commit fails, retry the local delete once after a rollback\\n    so we do not strand a stale Langflow row.\\n\\n    Requires exactly one row deleted (PK + owner scope). A zero-row delete\\n    means the local row was already gone or the owner scope was wrong \u2014 raise\\n    404 rather than returning success.\\n    \\\"\\\"\\\"\\n    try:\\n        await _delete_deployment_strictly_or_raise(session=session, user_id=user_id, deployment_id=deployment_id)\\n        await session.commit()\\n    except HTTPException:\\n        raise\\n    except Exception:  # noqa: BLE001\\n        await session.rollback()\\n        logger.warning(\\n            \\\"Local deployment cleanup failed for deployment %s (resource_key=%s); retrying.\\\",\\n            deployment_id,\\n            resource_key,\\n            exc_info=True,\\n        )\\n        try:\\n            await _delete_deployment_strictly_or_raise(session=session, user_id=user_id, deployment_id=deployment_id)\\n            await session.commit()\\n        except HTTPException:\\n            raise\\n        except Exception as exc:\\n            await session.rollback()\\n            logger.exception(\\n                \\\"Retrying local deployment cleanup failed for deployment %s (resource_key=%s).\\\",\\n                deployment_id,\\n                resource_key,\\n            )\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=(\\n                    \\\"Failed to delete the tracked deployment in Langflow. \\\"\\n                    \\\"It may already have been deleted from the provider. \\\"\\n                    \\\"Retry the delete request.\\\"\\n                ),\\n            ) from exc\\n\\n\\n@router.post(\\n    \\\"/providers\\\",\\n    response_model=DeploymentProviderAccountGetResponse,\\n    status_code=status.HTTP_201_CREATED,\\n    tags=[\\\"Deployment Providers\\\"],\\n)\\nasync def create_provider_account(\\n    session: DbSession,\\n    payload: DeploymentProviderAccountCreateRequest,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(provider_create_telemetry)],\\n):\\n    await ensure_provider_account_permission(\\n        current_user,\\n        ProviderAccountAction.CREATE,\\n        provider_account_user_id=current_user.id,\\n    )\\n    telemetry.provider = payload.provider_key\\n    deployment_mapper = get_deployment_mapper(payload.provider_key)\\n    deployment_adapter = resolve_deployment_adapter(payload.provider_key)\\n\\n    with handle_adapter_errors(mapper=deployment_mapper):\\n        verify_input = deployment_mapper.resolve_verify_credentials_for_create(payload=payload)\\n        await deployment_adapter.verify_credentials(\\n            user_id=current_user.id,\\n            payload=verify_input,\\n        )\\n\\n    try:\\n        provider_account_to_create = deployment_mapper.resolve_provider_account_create(\\n            payload=payload,\\n            user_id=current_user.id,\\n        )\\n        provider_account = await create_provider_account_row(\\n            session,\\n            provider_account=provider_account_to_create,\\n        )\\n    except ValueError as exc:\\n        _raise_http_for_provider_account_value_error(exc)\\n    telemetry.wxo_tenant_id = provider_account.provider_tenant_id\\n    return deployment_mapper.resolve_provider_account_response(provider_account)\\n\\n\\n@router.get(\\\"/providers\\\", response_model=DeploymentProviderAccountListResponse, tags=[\\\"Deployment Providers\\\"])\\nasync def list_provider_accounts(\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n    page: Annotated[int, Query(ge=1)] = 1,\\n    size: Annotated[int, Query(ge=1, le=50)] = 20,\\n):\\n    await ensure_provider_account_permission(\\n        current_user,\\n        ProviderAccountAction.READ,\\n        provider_account_user_id=current_user.id,\\n    )\\n    offset = page_offset(page, size)\\n    provider_accounts = await list_provider_account_rows(session, user_id=current_user.id, offset=offset, limit=size)\\n    total = await count_provider_account_rows(session, user_id=current_user.id)\\n    return DeploymentProviderAccountListResponse(\\n        provider_accounts=[\\n            get_deployment_mapper(item.provider_key).resolve_provider_account_response(item)\\n            for item in provider_accounts\\n        ],\\n        page=page,\\n        size=size,\\n        total=total,\\n    )\\n\\n\\n@router.get(\\n    \\\"/providers/{provider_id}\\\",\\n    response_model=DeploymentProviderAccountGetResponse,\\n    tags=[\\\"Deployment Providers\\\"],\\n)\\nasync def get_provider_account(\\n    provider_id: DeploymentProviderAccountIdPath,\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n):\\n    provider_account = await get_provider_account_row_by_id(session, provider_id=provider_id, user_id=current_user.id)\\n    if provider_account is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Deployment provider account not found.\\\")\\n    try:\\n        await ensure_provider_account_permission(\\n            current_user,\\n            ProviderAccountAction.READ,\\n            provider_account_id=provider_account.id,\\n            provider_account_user_id=provider_account.user_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment provider account not found.\\\") from exc\\n    return get_deployment_mapper(provider_account.provider_key).resolve_provider_account_response(provider_account)\\n\\n\\n@router.delete(\\n    \\\"/providers/{provider_id}\\\",\\n    status_code=status.HTTP_204_NO_CONTENT,\\n    tags=[\\\"Deployment Providers\\\"],\\n)\\nasync def delete_provider_account(\\n    provider_id: DeploymentProviderAccountIdPath,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(provider_delete_telemetry)],\\n):\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_provider_account_permission(\\n            current_user,\\n            ProviderAccountAction.DELETE,\\n            provider_account_id=provider_account.id,\\n            provider_account_user_id=provider_account.user_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment provider account not found.\\\") from exc\\n    telemetry.provider = provider_account.provider_key\\n    telemetry.wxo_tenant_id = provider_account.provider_tenant_id\\n    deployment_count = await _count_provider_deployments_after_reconciliation(\\n        session=session,\\n        provider_account=provider_account,\\n        user_id=current_user.id,\\n    )\\n    if deployment_count > 0:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=\\\"Cannot delete provider account while deployments still exist.\\\",\\n        )\\n    try:\\n        await delete_provider_account_row(session, provider_account=provider_account)\\n    except ValueError as exc:\\n        _raise_http_for_provider_account_value_error(exc)\\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\\n\\n\\n@router.patch(\\n    \\\"/providers/{provider_id}\\\",\\n    response_model=DeploymentProviderAccountGetResponse,\\n    tags=[\\\"Deployment Providers\\\"],\\n)\\nasync def update_provider_account(\\n    provider_id: DeploymentProviderAccountIdPath,\\n    session: DbSession,\\n    payload: DeploymentProviderAccountUpdateRequest,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(provider_update_telemetry)],\\n):\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_provider_account_permission(\\n            current_user,\\n            ProviderAccountAction.WRITE,\\n            provider_account_id=provider_account.id,\\n            provider_account_user_id=provider_account.user_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment provider account not found.\\\") from exc\\n    telemetry.provider = provider_account.provider_key\\n    telemetry.wxo_tenant_id = provider_account.provider_tenant_id\\n\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n    verify_input = None\\n    if _field_was_explicitly_set(payload, \\\"provider_data\\\"):\\n        deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n        try:\\n            verify_input = deployment_mapper.resolve_verify_credentials_for_update(\\n                payload=payload,\\n                existing_account=provider_account,\\n            )\\n        except ValueError as exc:\\n            _raise_http_for_provider_account_value_error(exc)\\n        except NotImplementedError as exc:\\n            raise HTTPException(\\n                status_code=status.HTTP_501_NOT_IMPLEMENTED,\\n                detail=\\\"This operation is not supported by the deployment provider.\\\",\\n            ) from exc\\n        if verify_input is not None:\\n            with handle_adapter_errors(mapper=deployment_mapper):\\n                await deployment_adapter.verify_credentials(\\n                    user_id=current_user.id,\\n                    payload=verify_input,\\n                )\\n\\n    try:\\n        update_kwargs = deployment_mapper.resolve_provider_account_update(\\n            payload=payload,\\n            existing_account=provider_account,\\n        )\\n        updated = await update_provider_account_row(\\n            session,\\n            provider_account=provider_account,\\n            **update_kwargs,\\n        )\\n    except ValueError as exc:\\n        _raise_http_for_provider_account_value_error(exc)\\n    return deployment_mapper.resolve_provider_account_response(updated)\\n\\n\\n@router.post(\\\"\\\", response_model=DeploymentCreateResponse, status_code=status.HTTP_201_CREATED)\\nasync def create_deployment(\\n    session: DbSession,\\n    payload: DeploymentCreateRequest,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(deployment_create_telemetry)],\\n):\\n    provider_id = payload.provider_id\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    telemetry.provider = provider_account.provider_key\\n    telemetry.wxo_tenant_id = provider_account.provider_tenant_id\\n\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n\\n    # Authorize create (and flow:deploy) before any provider get/create so a\\n    # denied caller cannot trigger provider reads, rate limits, or provider-side\\n    # audit events via the existing-resource onboarding probe.\\n    project_id = await resolve_project_id_for_deployment_create(payload=payload, user_id=current_user.id, db=session)\\n    await ensure_deployment_permission(current_user, DeploymentAction.CREATE, project_id=project_id)\\n    flow_version_ids = deployment_mapper.util_create_flow_version_ids(payload)\\n    await validate_project_scoped_flow_version_ids(\\n        flow_version_ids=flow_version_ids,\\n        user_id=current_user.id,\\n        project_id=project_id,\\n        db=session,\\n    )\\n    await ensure_flow_deploy_for_version_ids(\\n        user=current_user,\\n        flow_version_ids=flow_version_ids,\\n        owner_id=current_user.id,\\n        db=session,\\n        project_id=project_id,\\n    )\\n\\n    existing_resource_key = deployment_mapper.util_existing_deployment_resource_key_for_create(payload)\\n    existing_provider_resource: DeploymentGetResult | None = None\\n    if existing_resource_key is not None:\\n        existing_deployment = await get_deployment_by_resource_key(\\n            session,\\n            user_id=current_user.id,\\n            deployment_provider_account_id=provider_id,\\n            resource_key=str(existing_resource_key),\\n        )\\n        if existing_deployment is not None:\\n            raise HTTPException(\\n                status_code=status.HTTP_409_CONFLICT,\\n                detail=f\\\"The agent '{existing_resource_key}' is already managed by Langflow. \\\"\\n                \\\"Update it to make changes, or delete the existing deployment first.\\\",\\n            )\\n        with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_id):\\n            existing_provider_resource = await deployment_adapter.get(\\n                deployment_id=existing_resource_key,\\n                deployment_type=payload.type,\\n                user_id=current_user.id,\\n                db=session,\\n            )\\n    should_create_provider_resource = existing_resource_key is None\\n    if should_create_provider_resource:\\n        adapter_payload = await deployment_mapper.resolve_deployment_create(\\n            user_id=current_user.id,\\n            project_id=project_id,\\n            db=session,\\n            payload=payload,\\n        )\\n        with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_id):\\n            provider_create_result = await deployment_adapter.create(\\n                user_id=current_user.id,\\n                payload=adapter_payload,\\n                db=session,\\n            )\\n    else:\\n        # Existing-resource create starts as DB-only onboarding: no provider\\n        # mutation is performed and created_* response fields stay empty.\\n        provider_create_result = deployment_mapper.util_create_result_from_existing_resource(\\n            existing_resource=existing_provider_resource,\\n        )\\n    # if we get here, the deployment was created successfully in the provider\\n    # so we need to create the deployment row and attach the flow versions\\n    # in the DB\\n    try:\\n        if should_create_provider_resource:\\n            deployment_to_create = deployment_mapper.resolve_deployment_model_for_create(\\n                result=provider_create_result,\\n                user_id=current_user.id,\\n                project_id=project_id,\\n                deployment_provider_account_id=provider_id,\\n            )\\n        else:\\n            deployment_to_create = deployment_mapper.resolve_deployment_model_from_existing_resource_for_create(\\n                payload=payload,\\n                existing_provider_resource=existing_provider_resource,\\n                user_id=current_user.id,\\n                project_id=project_id,\\n                deployment_provider_account_id=provider_id,\\n            )\\n        deployment_row = await create_deployment_db(\\n            session,\\n            deployment=deployment_to_create,\\n        )\\n\\n        snapshot_id_by_flow_version_id: dict[UUID, str] = {}\\n        if flow_version_ids:\\n            snapshot_id_by_flow_version_id = resolve_snapshot_map_for_create(\\n                deployment_mapper=deployment_mapper,\\n                result=provider_create_result,\\n                flow_version_ids=flow_version_ids,\\n            )\\n        await attach_flow_versions(\\n            flow_version_ids=flow_version_ids,\\n            user_id=current_user.id,\\n            deployment_row_id=deployment_row.id,\\n            snapshot_id_by_flow_version_id=snapshot_id_by_flow_version_id,\\n            db=session,\\n        )\\n\\n        await session.commit()\\n    except Exception as exc:\\n        # Compensate: delete the provider resource so it doesn't become orphaned.\\n        # Only the deployment resource itself is deleted (e.g. the WXO agent).\\n        # Secondary resources (snapshots/tools, configs) may remain orphaned --\\n        # this is intentional because snapshots/configs may be shared across deployments,\\n        # making cascade-delete unsafe.\\n        await session.rollback()\\n        if should_create_provider_resource:\\n            await rollback_provider_create(\\n                deployment_adapter=deployment_adapter,\\n                provider_id=provider_id,\\n                resource_id=provider_create_result.id,\\n                provider_result=provider_create_result.provider_result,\\n                user_id=current_user.id,\\n                db=session,\\n            )\\n        if isinstance(exc, AttachmentConflictError):\\n            raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=str(exc)) from exc\\n        raise\\n    return deployment_mapper.shape_deployment_create_result(\\n        provider_create_result, deployment_row, provider_key=provider_account.provider_key\\n    )\\n\\n\\n# exclude none as its associated with\\n# irrelevant fields. If in the future\\n# we want to include nulls, we can always\\n# transisiton to that.\\n@router.get(\\n    \\\"\\\",\\n    response_model=DeploymentListResponse,\\n    response_model_exclude_none=True,\\n)\\nasync def list_deployments(\\n    provider_id: DeploymentProviderAccountIdQuery,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    params: Annotated[Params, Depends(deployment_pagination_params)],\\n    deployment_type: Annotated[DeploymentType | None, Query()] = None,\\n    *,\\n    load_from_provider: Annotated[\\n        bool,\\n        Query(\\n            description=(\\n                \\\"When true, list deployments directly from the provider (bypassing Langflow-tracked deployments).\\\"\\n            )\\n        ),\\n    ] = False,\\n    flow_version_ids: Annotated[\\n        FlowVersionIdsQuery,\\n        Query(\\n            description=(\\n                \\\"Optional Langflow flow version ids (pass as repeated query params, \\\"\\n                \\\"e.g. ?flow_version_ids=id1&flow_version_ids=id2). When provided, \\\"\\n                \\\"deployments are filtered to those with at least one matching \\\"\\n                \\\"attachment (OR semantics across ids). \\\"\\n                \\\"Mutually exclusive with flow_ids.\\\"\\n            )\\n        ),\\n    ] = None,\\n    flow_ids: Annotated[\\n        FlowIdsQuery,\\n        Query(\\n            description=(\\n                \\\"Optional flow ids (pass as repeated query params, \\\"\\n                \\\"e.g. ?flow_ids=id1). Currently limited to 1 value. \\\"\\n                \\\"When provided, deployments are filtered to those attached \\\"\\n                \\\"to versions of the specified flow(s). \\\"\\n                \\\"Mutually exclusive with flow_version_ids.\\\"\\n            )\\n        ),\\n    ] = None,\\n    project_id: ProjectIdQuery = None,\\n):\\n    if flow_ids and flow_version_ids:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"flow_ids and flow_version_ids are mutually exclusive.\\\",\\n        )\\n    if load_from_provider and flow_version_ids:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"flow_version_ids filtering is not supported when loading deployments directly from the provider.\\\",\\n        )\\n    if load_from_provider and flow_ids:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"flow_ids filtering is not supported when loading deployments directly from the provider.\\\",\\n        )\\n    if load_from_provider and project_id is not None:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"project_id filtering is not supported when loading deployments directly from the provider.\\\",\\n        )\\n    effective_flow_version_ids = flow_version_ids\\n    if flow_ids:\\n        resolved = await flow_version_ids_for_flows(session, flow_ids=flow_ids, user_id=current_user.id)\\n        if not resolved:\\n            return DeploymentListResponse(deployments=[], page=params.page, size=params.size, total=0)\\n        effective_flow_version_ids = resolved\\n\\n    # DB-layer authz prefilter: a registered authorization plugin can return the\\n    # concrete set of deployment ids the caller may read, which we thread into\\n    # ``list_deployments_synced`` so the page query and its total are constrained\\n    # to (owner \u2295 visible) in SQL \u2014 skipping the per-row in-memory filter below\\n    # and the N+1 it implies. OSS pass-through returns None \u2192 owner-scoped query\\n    # plus ``filter_visible_resources`` unchanged.\\n    #\\n    # Computed up front (not after the provider-account gate) so a concrete list\\n    # can also relax that gate: a shared deployment lives under its *owner's*\\n    # provider account, so the strict owner gate would 404 a cross-user reader\\n    # before the prefilter could widen anything. ``load_from_provider`` lists via\\n    # the owner's live provider connection, so it always requires an owned account\\n    # and never consults the prefilter.\\n    visibility_scope = (\\n        None\\n        if load_from_provider\\n        else await visible_scope_prefilter(\\n            current_user,\\n            resource_type=\\\"deployment\\\",\\n            domain=_resolve_authz_domain(None, project_id),\\n            act=DeploymentAction.READ,\\n        )\\n    )\\n\\n    # OSS / no-plugin path keeps the strict owner gate. A structured prefilter\\n    # may relax it only after the same SQL visibility predicate used by the page\\n    # proves that this specific provider owns at least one row visible to the\\n    # caller. A coarse workspace/project/global grant alone is not enough:\\n    # loading arbitrary foreign provider UUIDs would expose an existence oracle.\\n    use_shared_provider_lookup = bool(\\n        visibility_scope is not None\\n        and visibility_scope.has_cross_user_access\\n        and await has_visible_deployment_for_provider(\\n            session,\\n            user_id=current_user.id,\\n            deployment_provider_account_id=provider_id,\\n            visibility_scope=visibility_scope,\\n        )\\n    )\\n    if use_shared_provider_lookup:\\n        provider_account = await get_shared_listing_provider_account_or_404(provider_id=provider_id, db=session)\\n    else:\\n        provider_account = await get_owned_provider_account_or_404(\\n            provider_id=provider_id, user_id=current_user.id, db=session\\n        )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.READ,\\n            project_id=project_id,\\n        )\\n    except HTTPException as exc:\\n        if use_shared_provider_lookup:\\n            # The relaxed provider-account lookup above loads by UUID alone so\\n            # shared deployments can be listed. Once that path is active, mask\\n            # a policy deny exactly like a missing account; otherwise callers\\n            # could distinguish an existing foreign provider UUID (403) from a\\n            # nonexistent UUID (404).\\n            raise deny_to_404(exc, detail=\\\"Deployment provider account not found.\\\") from exc\\n        raise\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n    if load_from_provider:\\n        provider_list_params = deployment_mapper.resolve_load_from_provider_deployment_list_params()\\n        with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_id):\\n            adapter_params = await deployment_mapper.resolve_deployment_list_adapter_params(\\n                deployment_type=deployment_type,\\n                provider_params=provider_list_params,\\n            )\\n            provider_view = await deployment_adapter.list(\\n                user_id=current_user.id,\\n                db=session,\\n                params=adapter_params,\\n            )\\n        return deployment_mapper.shape_deployment_list_result(provider_view)\\n\\n    with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_id):\\n        rows_with_counts, total, provider_data_by_resource_key = await list_deployments_synced(\\n            deployment_adapter=deployment_adapter,\\n            deployment_mapper=deployment_mapper,\\n            user_id=current_user.id,\\n            row_owner_id=provider_account.user_id,\\n            provider_id=provider_id,\\n            db=session,\\n            page=params.page,\\n            size=params.size,\\n            deployment_type=deployment_type,\\n            flow_version_ids=effective_flow_version_ids,\\n            project_id=project_id,\\n            visibility_scope=visibility_scope,\\n        )\\n    # Per-deployment authorization filter. Mirrors GET /flows/ and GET /projects/:\\n    # the coarse READ check above gates whether the caller can list deployments\\n    # at all; this call drops individual rows the authorization plugin denies.\\n    # Runs only as the OSS in-memory fallback \u2014 when a concrete prefilter is\\n    # available the SQL union already constrained the page (and ``total``), so we\\n    # skip the per-row enforce. ``total`` may overcount denied items only on this\\n    # fallback path. ``rows_with_counts`` is ``list[tuple[Deployment, int,\\n    # list[...]]]`` so the key/domain extractors operate on the first element.\\n    if visibility_scope is None:\\n        rows_with_counts = await filter_visible_resources(\\n            current_user,\\n            resource_type=\\\"deployment\\\",\\n            candidates=list(rows_with_counts),\\n            key=lambda row: row[0].id,\\n            domain_extractor=lambda row: _resolve_authz_domain(row[0].workspace_id, row[0].project_id),\\n            owner_extractor=lambda row: row[0].user_id,\\n            act=DeploymentAction.READ,\\n        )\\n    deployments = deployment_mapper.shape_deployment_list_items(\\n        rows_with_counts=rows_with_counts,\\n        # include flow_version_ids in list items only when\\n        # flow_version_ids or flow_ids filtering is active.\\n        # (empty lists are rejected by validation)\\n        has_flow_filter=bool(flow_version_ids or flow_ids),\\n        provider_key=provider_account.provider_key,\\n        provider_data_by_resource_key=provider_data_by_resource_key,\\n    )\\n    return DeploymentListResponse(\\n        deployments=deployments,\\n        page=params.page,\\n        size=params.size,\\n        total=total,\\n        # if we reach here, then load_from_provider is False,\\n        # therefore, top-level provider_data must be excluded from the response.\\n        # for this, we set it to None, and set response_model_exclude_none to True.\\n        provider_data=None,\\n    )\\n\\n\\n@router.get(\\\"/types\\\", response_model=DeploymentTypeListResponse)\\nasync def list_deployment_types(\\n    provider_id: DeploymentProviderAccountIdQuery,\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n):\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id, user_id=current_user.id, db=session\\n    )\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    with handle_adapter_errors(), deployment_provider_scope(provider_id):\\n        deployment_types_result: DeploymentListTypesResult = await deployment_adapter.list_types(\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n    return DeploymentTypeListResponse(deployment_types=deployment_types_result.deployment_types)\\n\\n\\n@router.get(\\\"/llms\\\", response_model=DeploymentLlmListResponse)\\nasync def list_deployment_llms(\\n    provider_id: DeploymentProviderAccountIdQuery,\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n):\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n    with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_id):\\n        llm_list_result = await deployment_adapter.list_llms(\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n    return deployment_mapper.shape_llm_list_result(llm_list_result)\\n\\n\\n@router.post(\\n    \\\"/{deployment_id}/runs\\\",\\n    response_model=RunCreateResponse,\\n    status_code=status.HTTP_201_CREATED,\\n)\\nasync def create_deployment_run(\\n    deployment_id: DeploymentIdPath,\\n    session: DbSession,\\n    payload: RunCreateRequest,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(deployment_run_telemetry)],\\n):\\n    (\\n        deployment_row,\\n        deployment_adapter,\\n        deployment_mapper,\\n        _provider_key,\\n        provider_tenant_id,\\n    ) = await resolve_adapter_mapper_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.EXECUTE,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n    telemetry.provider = _provider_key\\n    telemetry.wxo_tenant_id = provider_tenant_id\\n    adapter_execution_payload = await deployment_mapper.resolve_execution_create(\\n        deployment_resource_key=deployment_row.resource_key,\\n        db=session,\\n        payload=payload,\\n    )\\n    with (\\n        handle_adapter_errors(mapper=deployment_mapper),\\n        deployment_provider_scope(deployment_row.deployment_provider_account_id),\\n    ):\\n        # Adapter calls operate in the deployment owner's provider namespace\\n        # (credentials, resource keys, etc.). For shared deployments the actor\\n        # may not have a provider account of their own. ``current_user`` is\\n        # still used above for authorization/audit.\\n        execution_result = await deployment_adapter.create_execution(\\n            payload=adapter_execution_payload,\\n            user_id=deployment_row.user_id,\\n            db=session,\\n        )\\n\\n    return deployment_mapper.shape_execution_create_result(\\n        execution_result,\\n        deployment_id=deployment_row.id,\\n    )\\n\\n\\n@router.get(\\\"/{deployment_id}/runs/{run_id}\\\", response_model=RunStatusResponse)\\nasync def get_deployment_run(\\n    deployment_id: DeploymentIdPath,\\n    run_id: Annotated[str, Path(min_length=1, description=\\\"Provider-owned opaque run identifier.\\\")],\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n):\\n    (\\n        deployment_row,\\n        deployment_adapter,\\n        deployment_mapper,\\n        _provider_key,\\n        _provider_tenant_id,\\n    ) = await resolve_adapter_mapper_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.READ,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n    execution_lookup_id = run_id.strip()\\n    with (\\n        handle_adapter_errors(mapper=deployment_mapper),\\n        deployment_provider_scope(deployment_row.deployment_provider_account_id),\\n    ):\\n        # Provider-namespaced call uses the deployment owner; see\\n        # ``create_deployment_run``.\\n        execution_result = await deployment_adapter.get_execution(\\n            execution_id=execution_lookup_id,\\n            user_id=deployment_row.user_id,\\n            db=session,\\n        )\\n\\n    return deployment_mapper.shape_execution_status_result(\\n        execution_result,\\n        deployment_id=deployment_row.id,\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Routes: Configs\\n# ---------------------------------------------------------------------------\\n\\n\\n@router.get(\\\"/configs\\\", response_model=DeploymentConfigListResponse, response_model_exclude_none=True)\\nasync def list_deployment_configs(\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n    deployment_id: DeploymentIdQuery | None = None,\\n    provider_id: DeploymentProviderAccountIdQuery | None = None,\\n    page: Annotated[int, Query(ge=1)] = 1,\\n    size: Annotated[int, Query(ge=1, le=10000)] = 20,  # TODO: Paginate if performance is an issue\\n):\\n    \\\"\\\"\\\"List deployment configs.\\n\\n    Provider account resolution priority:\\n    1. Both provider_id and deployment_id given \u2192 use provider_id, validate\\n       the deployment belongs to it (404 if mismatched).\\n    2. Only deployment_id given \u2192 infer provider from the deployment row.\\n    3. Only provider_id given \u2192 tenant-scoped listing (no deployment filter).\\n    4. Neither given \u2192 422.\\n    \\\"\\\"\\\"\\n    deployment_row = None\\n    provider_account = (\\n        await get_owned_provider_account_or_404(\\n            provider_id=provider_id,\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n        if provider_id is not None\\n        else None\\n    )\\n\\n    if deployment_id is not None:\\n        deployment_row = await get_deployment_row_or_404(\\n            deployment_id=deployment_id,\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n        try:\\n            await ensure_deployment_permission(\\n                current_user,\\n                DeploymentAction.READ,\\n                deployment_id=deployment_row.id,\\n                deployment_user_id=deployment_row.user_id,\\n                workspace_id=deployment_row.workspace_id,\\n                project_id=deployment_row.project_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n        if provider_account is None:\\n            # Provider account is owner-scoped to the deployment owner.\\n            provider_account = await get_owned_provider_account_or_404(\\n                provider_id=deployment_row.deployment_provider_account_id,\\n                user_id=deployment_row.user_id,\\n                db=session,\\n            )\\n        elif deployment_row.deployment_provider_account_id != provider_account.id:\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Deployment not found for provider.\\\")\\n\\n    if provider_account is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=\\\"Either provider_id or deployment_id must be provided.\\\",\\n        )\\n\\n    if deployment_row is None:\\n        await ensure_deployment_permission(current_user, DeploymentAction.READ)\\n\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n    adapter_params = await deployment_mapper.resolve_config_list_adapter_params(\\n        deployment_resource_key=deployment_row.resource_key if deployment_row is not None else None,\\n        provider_params=None,\\n    )\\n    # Provider-namespaced \u2014 prefer the deployment owner when a shared\\n    # deployment_id pinned the scope, otherwise fall back to the provider\\n    # account owner (which equals the actor for the no-deployment-id branch).\\n    adapter_user_id = deployment_row.user_id if deployment_row is not None else provider_account.user_id\\n    with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_account.id):\\n        config_result = await deployment_adapter.list_configs(\\n            user_id=adapter_user_id,\\n            params=adapter_params,\\n            db=session,\\n        )\\n    return deployment_mapper.shape_config_list_result(\\n        config_result,\\n        page=page,\\n        size=size,\\n    )\\n\\n\\n@router.get(\\\"/snapshots\\\", response_model=DeploymentSnapshotListResponse, response_model_exclude_none=True)\\nasync def list_deployment_snapshots(\\n    provider_id: DeploymentProviderAccountIdQuery,\\n    session: DbSessionReadOnly,\\n    current_user: CurrentActiveUser,\\n    deployment_id: DeploymentIdQuery | None = None,\\n    page: Annotated[int, Query(ge=1)] = 1,\\n    size: Annotated[int, Query(ge=1, le=50)] = 20,\\n):\\n    \\\"\\\"\\\"List deployment snapshots/tools.\\\"\\\"\\\"\\n    deployment_row = None\\n    if deployment_id is not None:\\n        deployment_row = await get_deployment_row_or_404(\\n            deployment_id=deployment_id,\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n        try:\\n            await ensure_deployment_permission(\\n                current_user,\\n                DeploymentAction.READ,\\n                deployment_id=deployment_row.id,\\n                deployment_user_id=deployment_row.user_id,\\n                workspace_id=deployment_row.workspace_id,\\n                project_id=deployment_row.project_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n\\n    provider_owner_id = deployment_row.user_id if deployment_row is not None else current_user.id\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=provider_id,\\n        user_id=provider_owner_id,\\n        db=session,\\n    )\\n\\n    if deployment_row is not None and deployment_row.deployment_provider_account_id != provider_account.id:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Deployment not found for provider.\\\")\\n\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n    adapter_params = await deployment_mapper.resolve_snapshot_list_adapter_params(\\n        deployment_resource_key=deployment_row.resource_key if deployment_row is not None else None,\\n        provider_params=None,\\n    )\\n    with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(provider_account.id):\\n        snapshot_result = await deployment_adapter.list_snapshots(\\n            user_id=provider_owner_id,\\n            params=adapter_params,\\n            db=session,\\n        )\\n    return deployment_mapper.shape_snapshot_list_result(\\n        snapshot_result,\\n        page=page,\\n        size=size,\\n    )\\n\\n\\n@router.patch(\\n    \\\"/snapshots/{provider_snapshot_id}\\\",\\n    response_model=SnapshotUpdateResponse,\\n)\\nasync def update_snapshot(\\n    provider_snapshot_id: Annotated[\\n        str,\\n        Path(min_length=1, description=\\\"Provider-owned snapshot identifier (e.g. WXO tool_id).\\\"),\\n    ],\\n    *,\\n    body: SnapshotUpdateRequest,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(snapshot_update_telemetry)],\\n):\\n    \\\"\\\"\\\"Replace an existing provider snapshot's content with a new flow version.\\n\\n    Resolves the deployment context from the attachment record linked to\\n    ``provider_snapshot_id``.  Only Langflow-tracked snapshots (those with\\n    a ``flow_version_deployment_attachment`` row) can be updated.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.deployment.crud import get_deployment as get_deployment_row\\n    from langflow.services.database.models.flow_version.crud import get_flow_version_entry\\n\\n    snapshot_id = provider_snapshot_id.strip()\\n\\n    # ``provider_snapshot_id`` is indexed but NOT unique \u2014 a single provider\\n    # snapshot can be attached to multiple deployments. The provider-side\\n    # ``update_snapshot`` mutates the snapshot once, and the DB-side\\n    # ``update_flow_version_by_provider_snapshot_id`` rewrites **every**\\n    # attachment row matching ``(owner_id, snapshot_id)``. So authorizing a\\n    # single deployment is not enough \u2014 the actor must hold WRITE on every\\n    # deployment touched by the mutation. Anything less lets a partial-write\\n    # share grant silently rebind snapshots on deployments the actor cannot\\n    # otherwise modify.\\n    authz = get_authorization_service()\\n    share_aware = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n\\n    all_candidates = await list_attachments_by_provider_snapshot_id(\\n        session,\\n        provider_snapshot_id=snapshot_id,\\n    )\\n    if not all_candidates:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail=f\\\"No attachment found for provider_snapshot_id '{snapshot_id}'.\\\",\\n        )\\n\\n    if not share_aware:\\n        # OSS pass-through cannot widen visibility \u2014 only the actor's own\\n        # rows are reachable. The owner-group walk below will see at most\\n        # one group (the actor's), which keeps OSS behaviour unchanged.\\n        all_candidates = [c for c in all_candidates if c.user_id == current_user.id]\\n        if not all_candidates:\\n            raise HTTPException(\\n                status_code=status.HTTP_404_NOT_FOUND,\\n                detail=f\\\"No attachment found for provider_snapshot_id '{snapshot_id}'.\\\",\\n            )\\n\\n    # ``update_flow_version_by_provider_snapshot_id`` is per-owner: each\\n    # owner's rows are mutated independently, so the multi-owner case is\\n    # NOT inherently unsafe. Authorize every deployment in each owner\\n    # group and keep only the groups that fully authorize. Then:\\n    #\\n    #   * zero authorized groups \u2192 404 (preserves UUID privacy; an\\n    #     authenticated caller learns nothing about who else owns a\\n    #     snapshot with the same id),\\n    #   * one authorized group \u2192 proceed with that group,\\n    #   * multiple authorized groups \u2192 409 (the actor has WRITE on\\n    #     multiple unrelated snapshot installations and the PATCH route\\n    #     has no discriminator to pick one).\\n    candidates_by_owner: dict = {}\\n    for candidate in all_candidates:\\n        candidates_by_owner.setdefault(candidate.user_id, []).append(candidate)\\n\\n    authorized_groups: list[tuple] = []  # (owner_id, list[Deployment])\\n    for owner_id, owner_candidates in candidates_by_owner.items():\\n        owner_deployments: list = []\\n        group_allowed = True\\n        for candidate in owner_candidates:\\n            candidate_deployment = await get_deployment_row(\\n                session,\\n                user_id=owner_id,\\n                deployment_id=candidate.deployment_id,\\n            )\\n            if candidate_deployment is None:\\n                # A dangling attachment whose deployment has been deleted\\n                # \u2014 skip. The mutation can't affect a deployment that\\n                # doesn't exist.\\n                continue\\n            try:\\n                await ensure_deployment_permission(\\n                    current_user,\\n                    DeploymentAction.WRITE,\\n                    deployment_id=candidate_deployment.id,\\n                    deployment_user_id=candidate_deployment.user_id,\\n                    workspace_id=candidate_deployment.workspace_id,\\n                    project_id=candidate_deployment.project_id,\\n                )\\n            except HTTPException as exc:\\n                if exc.status_code in {status.HTTP_403_FORBIDDEN, status.HTTP_404_NOT_FOUND}:\\n                    # All-or-nothing per group: any denied deployment in\\n                    # this owner's set disqualifies the entire group.\\n                    # Drop the group silently so other authorized groups\\n                    # can still surface, and so unauthorized callers learn\\n                    # nothing about the existence of owner groups they\\n                    # can't reach.\\n                    group_allowed = False\\n                    break\\n                raise\\n            owner_deployments.append(candidate_deployment)\\n\\n        if group_allowed and owner_deployments:\\n            authorized_groups.append((owner_id, owner_deployments))\\n\\n    if not authorized_groups:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail=f\\\"No attachment found for provider_snapshot_id '{snapshot_id}'.\\\",\\n        )\\n    if len(authorized_groups) > 1:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=(\\n                f\\\"Provider snapshot '{snapshot_id}' is attached to multiple owners' \\\"\\n                \\\"deployments you can write. The PATCH route cannot resolve this \\\"\\n                \\\"without a discriminator.\\\"\\n            ),\\n        )\\n\\n    owner_id, resolved_deployments = authorized_groups[0]\\n    # Restrict the candidate set used downstream to the chosen owner's\\n    # rows so ``update_flow_version_by_provider_snapshot_id`` (which is\\n    # itself owner-scoped) and the attachment lookup below operate on a\\n    # consistent set.\\n    all_candidates = candidates_by_owner[owner_id]\\n\\n    # The downstream provider call is scoped to ONE provider account (the\\n    # one we resolve ``deployment_adapter`` against), but\\n    # ``update_flow_version_by_provider_snapshot_id`` rewrites every owner\\n    # row matching ``(owner_id, snapshot_id)`` regardless of which provider\\n    # account the deployment belongs to. If the same provider_snapshot_id\\n    # exists across multiple provider accounts in the owner's namespace,\\n    # mutating one provider account while rewriting attachments tied to a\\n    # different account would corrupt their pointer state. Refuse the\\n    # ambiguous case so the caller has to disambiguate (typically by\\n    # cleaning up snapshot id collisions).\\n    provider_account_ids = {d.deployment_provider_account_id for d in resolved_deployments}\\n    if len(provider_account_ids) > 1:\\n        raise HTTPException(\\n            status_code=status.HTTP_409_CONFLICT,\\n            detail=(\\n                f\\\"Provider snapshot '{snapshot_id}' is attached to deployments across \\\"\\n                f\\\"{len(provider_account_ids)} provider accounts. The PATCH route cannot \\\"\\n                \\\"safely update them in one operation.\\\"\\n            ),\\n        )\\n\\n    # Pick any authorized attachment + deployment for the downstream provider\\n    # call \u2014 they all share the same owner, snapshot, and provider account by\\n    # the check above. The mutation operates on the full set via\\n    # ``update_flow_version_by_provider_snapshot_id``.\\n    deployment = resolved_deployments[0]\\n    attachment = next(c for c in all_candidates if c.deployment_id == deployment.id)\\n\\n    # Owner-scoped lookups from here on. Flow versions attached to a\\n    # deployment belong to the deployment owner; the provider account does\\n    # too. ``current_user`` stays the actor for audit but the data plane is\\n    # entirely in the owner's namespace.\\n    owner_id = deployment.user_id\\n    flow_version = await get_flow_version_entry(\\n        session,\\n        version_id=body.flow_version_id,\\n        user_id=owner_id,\\n    )\\n    if flow_version is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail=f\\\"Flow version '{body.flow_version_id}' not found.\\\",\\n        )\\n    if flow_version.data is None:\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail=f\\\"Flow version '{body.flow_version_id}' has no data.\\\",\\n        )\\n    await validate_project_scoped_flow_version_ids(\\n        flow_version_ids=[body.flow_version_id],\\n        user_id=owner_id,\\n        project_id=deployment.project_id,\\n        db=session,\\n    )\\n    await ensure_flow_deploy_for_version_ids(\\n        user=current_user,\\n        flow_version_ids=[body.flow_version_id],\\n        owner_id=owner_id,\\n        db=session,\\n        project_id=deployment.project_id,\\n        workspace_id=deployment.workspace_id,\\n    )\\n\\n    provider_account = await get_owned_provider_account_or_404(\\n        provider_id=deployment.deployment_provider_account_id,\\n        user_id=owner_id,\\n        db=session,\\n    )\\n    telemetry.provider = provider_account.provider_key\\n    telemetry.wxo_tenant_id = provider_account.provider_tenant_id\\n    deployment_adapter = resolve_deployment_adapter(provider_account.provider_key)\\n    deployment_mapper = get_deployment_mapper(provider_account.provider_key)\\n\\n    flow_row = await session.get(Flow, flow_version.flow_id)\\n\\n    flow_artifact = deployment_mapper.resolve_snapshot_update_artifact(\\n        flow_version=flow_version,\\n        flow_row=flow_row,\\n        deployment=deployment,\\n    )\\n\\n    with (\\n        handle_adapter_errors(mapper=deployment_mapper),\\n        deployment_provider_scope(deployment.deployment_provider_account_id),\\n    ):\\n        await deployment_adapter.update_snapshot(\\n            user_id=owner_id,\\n            db=session,\\n            snapshot_id=snapshot_id,\\n            flow_artifact=flow_artifact,\\n        )\\n\\n    # Provider mutation succeeded \u2014 update all local attachment rows that share\\n    # this provider snapshot id.\\n    # If the DB flush fails, attempt a best-effort compensating re-upload\\n    # of the previous flow version's artifact.\\n    # Concurrency note: rollback uses a single previously-read flow_version_id.\\n    # This assumes the snapshot->flow_version invariant held before this call.\\n    # Because the invariant is enforced in app logic (not a DB constraint),\\n    # concurrent writers can still race and violate that assumption.\\n    previous_flow_version_id = attachment.flow_version_id\\n    try:\\n        # Owner-scoped \u2014 the attachment row belongs to the deployment owner,\\n        # not the actor. Audit log still credits ``current_user`` upstream.\\n        updated_rows = await update_flow_version_by_provider_snapshot_id(\\n            session,\\n            user_id=owner_id,\\n            provider_snapshot_id=snapshot_id,\\n            flow_version_id=body.flow_version_id,\\n        )\\n        if updated_rows == 0:\\n            logger.warning(\\n                \\\"Snapshot '%s' update changed zero attachment rows after provider mutation \\\"\\n                \\\"(owner_id=%s, actor_id=%s, requested_flow_version_id=%s). \\\"\\n                \\\"Possible concurrent modification.\\\",\\n                snapshot_id,\\n                owner_id,\\n                current_user.id,\\n                body.flow_version_id,\\n            )\\n        await session.commit()\\n    except Exception:\\n        await session.rollback()\\n        logger.warning(\\n            \\\"DB update/commit failed after provider snapshot update for snapshot '%s' \\\"\\n            \\\"(requested_flow_version_id=%s). Attempting compensating provider rollback.\\\",\\n            snapshot_id,\\n            body.flow_version_id,\\n            exc_info=True,\\n        )\\n        try:\\n            # Rollback resolves the previous flow version from the owner's\\n            # namespace too \u2014 shared-deployment writes never touched the\\n            # actor's flow versions.\\n            prev_version = await get_flow_version_entry(\\n                session,\\n                version_id=previous_flow_version_id,\\n                user_id=owner_id,\\n            )\\n            if prev_version and prev_version.data:\\n                prev_artifact = deployment_mapper.resolve_snapshot_update_artifact(\\n                    flow_version=prev_version,\\n                    flow_row=flow_row,\\n                    deployment=deployment,\\n                )\\n                with deployment_provider_scope(deployment.deployment_provider_account_id):\\n                    await deployment_adapter.update_snapshot(\\n                        user_id=owner_id,\\n                        db=session,\\n                        snapshot_id=snapshot_id,\\n                        flow_artifact=prev_artifact,\\n                    )\\n                logger.info(\\n                    \\\"Restored provider snapshot '%s' to previous flow_version_id=%s after DB commit failure.\\\",\\n                    snapshot_id,\\n                    previous_flow_version_id,\\n                )\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\n                \\\"Best-effort rollback failed for snapshot '%s'. \\\"\\n                \\\"Provider content reflects flow_version_id=%s but attachment \\\"\\n                \\\"records point to flow_version_id=%s. Manual reconciliation may be needed.\\\",\\n                snapshot_id,\\n                body.flow_version_id,\\n                previous_flow_version_id,\\n                exc_info=True,\\n            )\\n        raise\\n\\n    return SnapshotUpdateResponse(\\n        flow_version_id=body.flow_version_id,\\n        provider_snapshot_id=snapshot_id,\\n    )\\n\\n\\n# Internal note: keep exclude-none for lean responses; use explicit nulls only for intentional tri-state fields.\\n@router.get(\\n    \\\"/{deployment_id}\\\",\\n    response_model=DeploymentGetResponse,\\n    response_model_exclude_none=True,\\n)\\nasync def get_deployment(\\n    deployment_id: DeploymentIdPath,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n):\\n    (\\n        deployment_row,\\n        deployment_adapter,\\n        deployment_mapper,\\n        provider_key,\\n        _provider_tenant_id,\\n    ) = await resolve_adapter_mapper_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.READ,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n\\n    # All provider/owner-scoped DB operations below use the deployment owner.\\n    # The actor (current_user) only governs authorization/audit \u2014 the data\\n    # plane (stale rows, attachments) lives in the owner's namespace.\\n    owner_id = deployment_row.user_id\\n    with deployment_provider_scope(deployment_row.deployment_provider_account_id):\\n        deployment_row, deployment, attached_count = await get_deployment_synced(\\n            deployment_adapter=deployment_adapter,\\n            deployment_mapper=deployment_mapper,\\n            deployment=deployment_row,\\n            provider_key=provider_key,\\n            user_id=owner_id,\\n            db=session,\\n        )\\n\\n    payload = deployment.model_dump(exclude_unset=True)\\n    raw_provider_data = payload.get(\\\"provider_data\\\")\\n    provider_data = deployment_mapper.shape_deployment_get_data(raw_provider_data, name=payload.get(\\\"name\\\"))\\n    return DeploymentGetResponse(\\n        id=deployment_row.id,\\n        provider_id=deployment_row.deployment_provider_account_id,\\n        provider_key=provider_key,\\n        description=deployment_row.description,\\n        type=deployment_row.deployment_type,\\n        # Timestamps are local DB audit fields, not provider payload fields.\\n        created_at=deployment_row.created_at,\\n        updated_at=deployment_row.updated_at,\\n        provider_data=provider_data,\\n        resource_key=deployment_row.resource_key,\\n        attached_count=attached_count,\\n    )\\n\\n\\n@router.patch(\\n    \\\"/{deployment_id}\\\",\\n    response_model=DeploymentUpdateResponse,\\n)\\nasync def update_deployment(\\n    deployment_id: DeploymentIdPath,\\n    session: DbSession,\\n    payload: DeploymentUpdateRequest,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(deployment_update_telemetry)],\\n):\\n    (\\n        deployment_row,\\n        deployment_adapter,\\n        deployment_mapper,\\n        provider_key,\\n        provider_tenant_id,\\n    ) = await resolve_adapter_mapper_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.WRITE,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n    telemetry.provider = provider_key\\n    telemetry.wxo_tenant_id = provider_tenant_id\\n    deployment_row_id = deployment_row.id\\n    deployment_resource_key = deployment_row.resource_key\\n    deployment_provider_account_id = deployment_row.deployment_provider_account_id\\n    # Owner-namespaced operations use ``deployment_row.user_id`` \u2014 the\\n    # deployment, its flow versions, and its attachments all live in the\\n    # owner's scope. ``current_user`` is still the actor for authorization\\n    # and audit, but the data plane operates in the owner's namespace.\\n    owner_id = deployment_row.user_id\\n    added_flow_version_ids, remove_flow_version_ids = resolve_flow_version_patch_for_update(\\n        deployment_mapper=deployment_mapper,\\n        payload=payload,\\n    )\\n    await validate_project_scoped_flow_version_ids(\\n        flow_version_ids=list(dict.fromkeys([*added_flow_version_ids, *remove_flow_version_ids])),\\n        user_id=owner_id,\\n        project_id=deployment_row.project_id,\\n        db=session,\\n    )\\n    # Only newly published versions need flow:deploy; removals are gated by\\n    # deployment:write alone today. There is no flow:undeploy (or similar) in\\n    # FlowAction yet \u2014 consider adding one if detaching a version from a\\n    # deployment should require its own grant. Authorize before\\n    # resolve_deployment_update reads flow data.\\n    await ensure_flow_deploy_for_version_ids(\\n        user=current_user,\\n        flow_version_ids=added_flow_version_ids,\\n        owner_id=owner_id,\\n        db=session,\\n        project_id=deployment_row.project_id,\\n        workspace_id=deployment_row.workspace_id,\\n    )\\n    adapter_payload = await deployment_mapper.resolve_deployment_update(\\n        user_id=owner_id,\\n        deployment_db_id=deployment_row_id,\\n        db=session,\\n        payload=payload,\\n    )\\n    with handle_adapter_errors(mapper=deployment_mapper), deployment_provider_scope(deployment_provider_account_id):\\n        update_result: DeploymentUpdateResult = await deployment_adapter.update(\\n            deployment_id=deployment_resource_key,\\n            payload=adapter_payload,\\n            user_id=owner_id,\\n            db=session,\\n        )\\n    try:\\n        existing_attachments = await list_deployment_attachments_for_flow_version_ids(\\n            session,\\n            user_id=owner_id,\\n            deployment_id=deployment_row_id,\\n            flow_version_ids=added_flow_version_ids,\\n        )\\n        already_attached = {a.flow_version_id for a in existing_attachments}\\n        newly_added_flow_version_ids = [fv for fv in added_flow_version_ids if fv not in already_attached]\\n        added_snapshot_bindings = resolve_added_snapshot_bindings_for_update(\\n            deployment_mapper=deployment_mapper,\\n            added_flow_version_ids=newly_added_flow_version_ids,\\n            result=update_result,\\n        )\\n        await apply_flow_version_patch_attachments(\\n            user_id=owner_id,\\n            deployment_row_id=deployment_row_id,\\n            added_snapshot_bindings=added_snapshot_bindings,\\n            remove_flow_version_ids=remove_flow_version_ids,\\n            db=session,\\n        )\\n\\n        update_kwargs = deployment_mapper.resolve_kwargs_for_metadata_update(update_result)\\n        if update_kwargs:\\n            deployment_row = await update_deployment_db(\\n                session,\\n                deployment=deployment_row,\\n                **update_kwargs,\\n            )\\n\\n        await session.commit()\\n    except Exception as exc:\\n        # Provider was already mutated by deployment_adapter.update above.\\n        # Roll back the session to discard any pending DB changes (or reset\\n        # it from the \\\"inactive\\\" state after a failed commit) so the mapper\\n        # can query the original attachment rows and build a compensating\\n        # payload. Compensating update must stay in the owner's namespace.\\n        await session.rollback()\\n        await rollback_provider_update(\\n            deployment_adapter=deployment_adapter,\\n            deployment_mapper=deployment_mapper,\\n            deployment_db_id=deployment_row_id,\\n            deployment_resource_key=deployment_resource_key,\\n            deployment_provider_account_id=deployment_provider_account_id,\\n            user_id=owner_id,\\n            db=session,\\n        )\\n        if isinstance(exc, AttachmentConflictError):\\n            raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=str(exc)) from exc\\n        raise\\n\\n    return deployment_mapper.shape_deployment_update_result(\\n        update_result,\\n        deployment_row,\\n        provider_key=provider_key,\\n    )\\n\\n\\n@router.delete(\\\"/{deployment_id}\\\", status_code=status.HTTP_204_NO_CONTENT)\\nasync def delete_deployment(\\n    deployment_id: DeploymentIdPath,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    telemetry: Annotated[DeploymentTelemetryCtx, Depends(deployment_delete_telemetry)],\\n    *,\\n    include_provider: IncludeProviderDeleteQuery = True,\\n):\\n    deployment_row, deployment_adapter, _provider_key, provider_tenant_id = await resolve_adapter_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.DELETE,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n    telemetry.provider = _provider_key\\n    telemetry.wxo_tenant_id = provider_tenant_id\\n    if include_provider:\\n        try:\\n            with handle_adapter_errors(), deployment_provider_scope(deployment_row.deployment_provider_account_id):\\n                # Provider-namespaced call uses the deployment owner; see\\n                # ``create_deployment_run``.\\n                await deployment_adapter.delete(\\n                    deployment_id=deployment_row.resource_key,\\n                    user_id=deployment_row.user_id,\\n                    db=session,\\n                )\\n        except HTTPException as exc:\\n            if exc.status_code != status.HTTP_404_NOT_FOUND:\\n                raise\\n            logger.warning(\\n                \\\"Deployment %s (resource_key=%s) already missing on provider %s during delete; deleting stale row.\\\",\\n                deployment_row.id,\\n                deployment_row.resource_key,\\n                deployment_row.deployment_provider_account_id,\\n            )\\n    await _delete_local_deployment_row(\\n        session=session,\\n        deployment_id=deployment_row.id,\\n        user_id=deployment_row.user_id,\\n        resource_key=deployment_row.resource_key,\\n    )\\n    return Response(status_code=status.HTTP_204_NO_CONTENT)\\n\\n\\n@router.get(\\n    \\\"/{deployment_id}/flows\\\",\\n    response_model=DeploymentFlowVersionListResponse,\\n)\\nasync def list_deployment_flow_versions(\\n    deployment_id: DeploymentIdPath,\\n    session: DbSession,\\n    current_user: CurrentActiveUser,\\n    page: Annotated[int, Query(ge=1)] = 1,\\n    size: Annotated[int, Query(ge=1, le=50)] = 20,\\n    flow_ids: Annotated[\\n        FlowIdsQuery,\\n        Query(\\n            description=(\\n                \\\"Optional flow ids (pass as repeated query params, \\\"\\n                \\\"e.g. ?flow_ids=id1). Currently limited to 1 value. \\\"\\n                \\\"When provided, only attached flow versions belonging to the specified flow(s) are returned.\\\"\\n            )\\n        ),\\n    ] = None,\\n):\\n    (\\n        deployment_row,\\n        deployment_adapter,\\n        deployment_mapper,\\n        _provider_key,\\n        _provider_tenant_id,\\n    ) = await resolve_adapter_mapper_from_deployment(\\n        deployment_id=deployment_id,\\n        user_id=current_user.id,\\n        db=session,\\n    )\\n    try:\\n        await ensure_deployment_permission(\\n            current_user,\\n            DeploymentAction.READ,\\n            deployment_id=deployment_row.id,\\n            deployment_user_id=deployment_row.user_id,\\n            workspace_id=deployment_row.workspace_id,\\n            project_id=deployment_row.project_id,\\n        )\\n    except HTTPException as exc:\\n        raise deny_to_404(exc, detail=\\\"Deployment not found.\\\") from exc\\n    with (\\n        handle_adapter_errors(mapper=deployment_mapper),\\n        deployment_provider_scope(deployment_row.deployment_provider_account_id),\\n    ):\\n        # Provider-namespaced flow-version list uses the deployment owner so\\n        # shared deployments resolve under the right credentials.\\n        rows, total, snapshot_result = await list_deployment_flow_versions_synced(\\n            deployment_adapter=deployment_adapter,\\n            user_id=deployment_row.user_id,\\n            provider_id=deployment_row.deployment_provider_account_id,\\n            deployment_id=deployment_row.id,\\n            db=session,\\n            page=page,\\n            size=size,\\n            flow_ids=flow_ids,\\n        )\\n    return deployment_mapper.shape_flow_version_list_result(\\n        rows=rows,\\n        snapshot_result=snapshot_result,\\n        page=page,\\n        size=size,\\n        total=total,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/endpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b948cdd4424075790dcc6918e39606818a35a0a8a39e18b02802dacb9e97e1fe\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport time\\nfrom collections.abc import AsyncGenerator, Collection, Mapping\\nfrom copy import deepcopy\\nfrom http import HTTPStatus\\nfrom typing import TYPE_CHECKING, Annotated, Any\\nfrom uuid import UUID, uuid4\\n\\nimport orjson\\nimport sqlalchemy as sa\\nfrom fastapi import APIRouter, BackgroundTasks, Body, Depends, HTTPException, Request, UploadFile, status\\nfrom fastapi.encoders import jsonable_encoder\\nfrom fastapi.responses import JSONResponse, StreamingResponse\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.custom.utils import (\\n    add_code_field_to_build_config,\\n    build_custom_component_template,\\n    get_instance_name,\\n    update_component_build_config,\\n)\\nfrom lfx.exceptions.tweaks import TweakRefusedError\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.schema import RunOutputs\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.schema.legacy_render import project_payload_to_v1\\nfrom lfx.schema.schema import InputValueRequest\\nfrom lfx.services.model_provider_policy import (\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    aresolve_model_provider_policy,\\n    reset_current_model_provider_policy_context,\\n    set_current_model_provider_policy_context,\\n)\\nfrom lfx.services.settings.service import SettingsService\\nfrom lfx.utils.component_aliases import ComponentIdentityIndex, build_component_identity_index\\nfrom lfx.utils.flow_validation import (\\n    CustomComponentValidationError,\\n    admin_only_build_required,\\n    prepare_flow_build_for_user,\\n)\\nfrom lfx.workflow.end_user_identity import (\\n    EndUserIdentityRequiredError,\\n    end_user_required_detail,\\n    resolve_serving_scope,\\n)\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    extract_global_variables_from_headers,\\n    parse_value,\\n    release_db_transaction,\\n)\\nfrom langflow.api.utils.execution_errors import caller_owns_flow as _caller_owns_flow\\nfrom langflow.api.utils.execution_errors import error_for_client\\nfrom langflow.api.v1.custom_component_policy import (\\n    CatalogPolicyHTTPException,\\n    enforce_catalog_policy_for_component_type,\\n    resolve_component_code_for_action,\\n)\\nfrom langflow.api.v1.files import get_flow\\nfrom langflow.api.v1.global_variable_defaults import apply_global_variable_defaults\\nfrom langflow.api.v1.model_provider_policy_scope import (\\n    ProviderPolicyAttributesDependency,\\n    provider_policy_attributes_for_flow,\\n    scoped_model_provider_policy_for_flow,\\n)\\nfrom langflow.api.v1.run_validation import raise_if_hitl_unsupported\\nfrom langflow.api.v1.schemas import (\\n    ConfigResponse,\\n    CustomComponentRequest,\\n    CustomComponentResponse,\\n    PublicConfigResponse,\\n    RunResponse,\\n    SimplifiedAPIRequest,\\n    TaskStatusResponse,\\n    UpdateCustomComponentRequest,\\n    UploadFileResponse,\\n)\\nfrom langflow.api.warm_graph import try_warm_run_graph\\nfrom langflow.events.event_manager import create_stream_tokens_event_manager\\nfrom langflow.exceptions.api import APIException, InvalidChatInputError\\nfrom langflow.exceptions.serialization import SerializationError\\nfrom langflow.helpers.flow import get_flow_by_id_or_endpoint_name\\nfrom langflow.interface.initialize.loading import update_params_with_load_from_db_fields\\nfrom langflow.processing.process import process_tweaks, run_graph_internal\\nfrom langflow.schema.graph import Tweaks\\nfrom langflow.services.auth.utils import (\\n    api_key_security,\\n    get_current_user_for_sse,\\n    get_optional_user,\\n)\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.authorization.access_ceiling import (\\n    external_access_allows,\\n    get_current_external_access_context,\\n)\\nfrom langflow.services.cache.utils import save_uploaded_file\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.database.models.flow.utils import get_all_webhook_components_in_flow\\nfrom langflow.services.database.models.jobs.model import JobType\\nfrom langflow.services.database.models.user.model import User, UserRead\\nfrom langflow.services.deps import (\\n    get_auth_service,\\n    get_catalog_policy_service,\\n    get_job_service,\\n    get_memory_base_service,\\n    get_session_service,\\n    get_settings_service,\\n    get_task_service,\\n    get_telemetry_service,\\n)\\nfrom langflow.services.event_manager import create_webhook_event_manager, webhook_event_manager\\nfrom langflow.services.telemetry.schema import RunPayload\\nfrom langflow.utils.compression import compress_response\\nfrom langflow.utils.version import get_version_info\\n\\nif TYPE_CHECKING:\\n    from langflow.events.event_manager import EventManager\\n\\nrouter = APIRouter(tags=[\\\"Base\\\"])\\n\\n# SSE Constants\\nSSE_HEARTBEAT_TIMEOUT_SECONDS = 30.0\\n\\n\\ndef _has_nonempty_tweaks(tweaks: Tweaks | dict | None) -> bool:\\n    \\\"\\\"\\\"Handle both the Tweaks RootModel and ordinary mappings.\\\"\\\"\\\"\\n    return bool(getattr(tweaks, \\\"root\\\", tweaks))\\n\\n\\ndef _enforce_owner_only_tweaks(\\n    flow: Flow | FlowRead,\\n    user: User | UserRead,\\n    tweaks: Tweaks | dict | None,\\n) -> None:\\n    \\\"\\\"\\\"Reject caller-controlled graph mutation without revealing a shared flow.\\\"\\\"\\\"\\n    if _has_nonempty_tweaks(tweaks) and not _caller_owns_flow(flow, user):\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Flow not found\\\")\\n\\n\\ndef _graph_executes_as_actor(\\n    graph: Graph,\\n    user: User | UserRead,\\n    *,\\n    flow_id: UUID | str,\\n) -> bool:\\n    \\\"\\\"\\\"Reject cached graphs whose instantiated components retain another principal.\\\"\\\"\\\"\\n    actor_id = str(user.id)\\n    if str(getattr(graph, \\\"flow_id\\\", None)) != str(flow_id):\\n        return False\\n    if str(getattr(graph, \\\"user_id\\\", None)) != actor_id:\\n        return False\\n    for vertex in getattr(graph, \\\"vertices\\\", []):\\n        component = getattr(vertex, \\\"custom_component\\\", None)\\n        component_user_id = getattr(component, \\\"_user_id\\\", None)\\n        if component_user_id is not None and str(component_user_id) != actor_id:\\n            return False\\n    return True\\n\\n\\n_SIMPLIFIED_API_FORM_FIELDS = (\\n    \\\"input_value\\\",\\n    \\\"input_type\\\",\\n    \\\"output_type\\\",\\n    \\\"output_component\\\",\\n    \\\"session_id\\\",\\n    \\\"user_id\\\",\\n)\\n\\n\\nasync def _parse_multipart_form_data(http_request: Request) -> SimplifiedAPIRequest:\\n    \\\"\\\"\\\"Parse SimplifiedAPIRequest fields from a multipart/form-data request.\\n\\n    Reads the form via ``http_request.form()`` so uploaded file streams are not\\n    consumed by an upstream JSON parse attempt. Only string-valued fields that\\n    map to ``SimplifiedAPIRequest`` are extracted; any ``UploadFile`` entries\\n    (e.g. inline file uploads) are intentionally ignored here and remain\\n    available to downstream handlers.\\n    \\\"\\\"\\\"\\n    form = await http_request.form()\\n    data: dict = {}\\n\\n    for field in _SIMPLIFIED_API_FORM_FIELDS:\\n        value = form.get(field)\\n        if isinstance(value, str):\\n            data[field] = value\\n\\n    raw_tweaks = form.get(\\\"tweaks\\\")\\n    if isinstance(raw_tweaks, (str, bytes)) and raw_tweaks:\\n        try:\\n            data[\\\"tweaks\\\"] = orjson.loads(raw_tweaks)\\n        except orjson.JSONDecodeError as exc:\\n            logger.warning(f\\\"Failed to parse 'tweaks' form field as JSON: {exc}\\\")\\n\\n    return SimplifiedAPIRequest(**data)\\n\\n\\nasync def parse_input_request_from_body(http_request: Request) -> SimplifiedAPIRequest:\\n    \\\"\\\"\\\"Parse SimplifiedAPIRequest from HTTP request body.\\n\\n    This function handles the case where FastAPI can't automatically parse the request body\\n    due to the presence of a Request parameter in the endpoint signature.\\n\\n    Supports both ``application/json`` and ``multipart/form-data`` bodies. For\\n    multipart requests, form fields matching ``SimplifiedAPIRequest`` (including\\n    ``session_id``) are extracted via ``request.form()`` rather than being lost\\n    to a failing JSON parse.\\n\\n    Args:\\n        http_request: The FastAPI Request object\\n\\n    Returns:\\n        SimplifiedAPIRequest: Parsed request or default instance if parsing fails\\n    \\\"\\\"\\\"\\n    content_type = (http_request.headers.get(\\\"content-type\\\") or \\\"\\\").lower()\\n\\n    try:\\n        if content_type.startswith(\\\"multipart/form-data\\\"):\\n            return await _parse_multipart_form_data(http_request)\\n\\n        body = await http_request.body()\\n        if body:\\n            body_data = orjson.loads(body)\\n            return SimplifiedAPIRequest(**body_data)\\n        return SimplifiedAPIRequest()\\n    except Exception as exc:  # noqa: BLE001\\n        logger.warning(f\\\"Failed to parse request body: {exc}\\\")\\n        return SimplifiedAPIRequest()\\n\\n\\n@router.get(\\\"/all\\\")\\nasync def get_all(\\n    request: Request,\\n    current_user: CurrentActiveUser,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n    *,\\n    include_blocked: bool = False,\\n):\\n    \\\"\\\"\\\"Retrieve all component types with compression for better performance.\\n\\n    Returns a compressed response containing all available component types,\\n    with display_names translated to the locale indicated by Accept-Language.\\n    \\\"\\\"\\\"\\n    if include_blocked and not current_user.is_superuser:\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"Only superusers can include blocked catalog components.\\\",\\n        )\\n\\n    from langflow.interface.components import get_and_cache_all_types_dict, get_component_identity_index\\n    from langflow.utils.i18n import build_component_display_names, translate_component_dict\\n\\n    try:\\n        catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n        all_types_en = await get_and_cache_all_types_dict(settings_service=get_settings_service())\\n        component_identity_index = get_component_identity_index(all_types_en)\\n        visible_types_en = await _filter_component_palette_by_provider_policy(\\n            all_types_en,\\n            user_id=current_user.id,\\n            attributes=provider_policy_attributes,\\n        )\\n        if not include_blocked:\\n            visible_types_en = _filter_component_palette_by_catalog_policy(\\n                visible_types_en,\\n                blocked_component_keys=catalog_policy_snapshot.blocked_component_keys,\\n                component_identity_index=component_identity_index,\\n            )\\n\\n        locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n        all_types = translate_component_dict(visible_types_en, locale) if locale != \\\"en\\\" else visible_types_en\\n\\n        component_display_names = build_component_display_names(visible_types_en)\\n        return compress_response({**all_types, \\\"component_display_names\\\": component_display_names})\\n\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\nasync def _filter_component_palette_by_provider_policy(\\n    all_types: dict[str, dict[str, dict]],\\n    *,\\n    user_id: UUID | str | None,\\n    attributes: dict[str, Any] | None = None,\\n) -> dict[str, dict[str, dict]]:\\n    \\\"\\\"\\\"Return a request-local palette with denied model providers removed.\\n\\n    The component registry is a process-wide cache. Copy category mappings and\\n    never delete from the cached object, otherwise one user's policy decision\\n    would leak into every later request. Unrelated components in mixed bundles\\n    have no ``model_provider_id`` and always remain present.\\n    \\\"\\\"\\\"\\n    provider_ids = {\\n        provider_id\\n        for components in all_types.values()\\n        for component in components.values()\\n        if isinstance(component, dict)\\n        and isinstance((metadata := component.get(\\\"metadata\\\")), dict)\\n        and isinstance((provider_id := metadata.get(\\\"model_provider_id\\\")), str)\\n        and provider_id\\n    }\\n    policy = await aresolve_model_provider_policy(\\n        user_id=user_id,\\n        providers=provider_ids,\\n        purpose=ModelProviderPolicyPurpose.DISCOVER,\\n        attributes=attributes,\\n    )\\n    return {\\n        category: {\\n            name: component\\n            for name, component in components.items()\\n            if not isinstance(component, dict)\\n            or not isinstance(component.get(\\\"metadata\\\"), dict)\\n            or not (provider_id := component[\\\"metadata\\\"].get(\\\"model_provider_id\\\"))\\n            or policy.allows(provider_id)\\n        }\\n        for category, components in all_types.items()\\n    }\\n\\n\\ndef _filter_component_palette_by_catalog_policy(\\n    all_types: dict[str, dict[str, dict]],\\n    *,\\n    blocked_component_keys: Collection[str],\\n    component_identity_index: ComponentIdentityIndex | None = None,\\n) -> dict[str, dict[str, dict]]:\\n    \\\"\\\"\\\"Return shallow category copies with canonically blocked components removed.\\n\\n    Policy keys and component-registry keys use the same collision-aware\\n    identity resolver as flow/runtime validation. Category order, component\\n    order, and empty categories are preserved. Component payloads remain\\n    shared with the process-wide cache and are never mutated or deep-copied.\\n    \\\"\\\"\\\"\\n    identity_index = component_identity_index or build_component_identity_index(all_types)\\n    blocked_identities = identity_index.resolve_many(blocked_component_keys)\\n    return {\\n        category: {\\n            component_key: component\\n            for component_key, component in components.items()\\n            if identity_index.resolve(component_key).isdisjoint(blocked_identities)\\n        }\\n        for category, components in all_types.items()\\n    }\\n\\n\\ndef validate_input_and_tweaks(input_request: SimplifiedAPIRequest) -> None:\\n    # If the input_value is not None and the input_type is \\\"chat\\\"\\n    # then we need to check the tweaks if the ChatInput component is present\\n    # and if its input_value is not None\\n    # if so, we raise an error\\n    if not input_request.tweaks:\\n        return\\n\\n    for key, value in input_request.tweaks.items():\\n        if not isinstance(value, dict):\\n            continue\\n\\n        input_value = value.get(\\\"input_value\\\")\\n        if input_value is None:\\n            continue\\n\\n        request_has_input = input_request.input_value is not None\\n\\n        if any(chat_key in key for chat_key in (\\\"ChatInput\\\", \\\"Chat Input\\\")):\\n            if request_has_input and input_request.input_type == \\\"chat\\\":\\n                msg = \\\"If you pass an input_value to the chat input, you cannot pass a tweak with the same name.\\\"\\n                raise InvalidChatInputError(msg)\\n\\n        elif (\\n            any(text_key in key for text_key in (\\\"TextInput\\\", \\\"Text Input\\\"))\\n            and request_has_input\\n            and input_request.input_type == \\\"text\\\"\\n        ):\\n            msg = \\\"If you pass an input_value to the text input, you cannot pass a tweak with the same name.\\\"\\n            raise InvalidChatInputError(msg)\\n\\n\\nasync def simple_run_flow(\\n    flow: Flow,\\n    input_request: SimplifiedAPIRequest,\\n    *,\\n    stream: bool = False,\\n    api_key_user: User | None = None,\\n    event_manager: EventManager | None = None,\\n    context: dict | None = None,\\n    run_id: str | None = None,\\n    expose_error_details: bool = False,\\n    http_request: Request | None = None,\\n):\\n    validate_input_and_tweaks(input_request)\\n    policy_context_token = set_current_model_provider_policy_context(\\n        user_id=getattr(api_key_user, \\\"id\\\", None),\\n        attributes=provider_policy_attributes_for_flow(\\n            flow,\\n            is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False)),\\n            required=True,\\n        ),\\n    )\\n    try:\\n        task_result: list[RunOutputs] = []\\n        user_id = api_key_user.id if api_key_user else None\\n        flow_id_str = str(flow.id)\\n        if flow.data is None:\\n            msg = f\\\"Flow {flow_id_str} has no data\\\"\\n            raise ValueError(msg)\\n        # The stored graph is caller-controlled: a regular user can persist component source\\n        # through the flow-write API and then execute it here. Apply the caller-aware\\n        # component policy to a detached copy so ``custom_component_admin_only`` is enforced\\n        # on stored bytes, not only on inline build payloads. Returns ``None`` when no\\n        # caller-specific restriction applies, leaving the existing fast paths untouched.\\n        sanitized_flow_data = await prepare_flow_build_for_user(\\n            flow.data,\\n            is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False)),\\n        )\\n        # Opt-in warm fast-path: serve a deepcopy of the pre-built\\n        # template + apply this run's identity, skipping from_payload and the flow-row\\n        # rebuild. Returns None (-> cold rebuild below) for tweaks / context / auto-bind\\n        # flows / HITL / disabled registry / cache-miss. See ``try_warm_run_graph``.\\n        # Skipped entirely once the policy sanitized the graph: the warm template is built\\n        # from the unsanitized stored row and would reintroduce the untrusted source.\\n        graph = (\\n            None\\n            if sanitized_flow_data is not None\\n            else await try_warm_run_graph(flow, input_request, user_id=user_id, context=context, stream=stream)\\n        )\\n        if graph is None:\\n            graph_data = (sanitized_flow_data if sanitized_flow_data is not None else flow.data).copy()\\n            graph_data = process_tweaks(graph_data, input_request.tweaks or {}, stream=stream)\\n            raise_if_hitl_unsupported(graph_data)\\n            # Mirror the Playground's one-time fix in-memory: bind empty fields whose\\n            # display_name matches a user global variable's default_fields. Without\\n            # this, API-only workflows never trigger the frontend hook that persists\\n            # load_from_db=true, so variables with \\\"Apply to Fields\\\" silently fail.\\n            # See: https://github.com/langflow-ai/langflow/issues/11781\\n            if user_id is not None:\\n                graph_data = await apply_global_variable_defaults(graph_data, user_id)\\n            graph = Graph.from_payload(\\n                graph_data, flow_id=flow_id_str, user_id=str(user_id), flow_name=flow.name, context=context\\n            )\\n        # Forward the caller-supplied identifier to tracing providers without\\n        # affecting authn/authz. The API-key owner remains the effective user\\n        # for permissions, global variables, and job ownership.\\n        if input_request.user_id:\\n            graph.tracing_user_id = input_request.user_id\\n        run_id_uuid = uuid4() if run_id is None else UUID(run_id)\\n        run_id = str(run_id_uuid)\\n        graph.set_run_id(run_id)\\n\\n        # Serving-plane end-user session scoping (shared with the v2 workflow router):\\n        # merge an identified end-user into the effective session_id so per-user memory\\n        # is isolated, and mark an anonymous run non-persisting. resolve_serving_scope\\n        # returns None under the default settings (feature off), so v1 /run, webhook and\\n        # every editor-plane caller are byte-for-byte unchanged. Callers that cannot\\n        # supply the request (no header available) pass http_request=None and skip it.\\n        effective_session_id = input_request.session_id\\n        if http_request is not None:\\n            try:\\n                scoped = resolve_serving_scope(\\n                    http_request=http_request,\\n                    requested_session_id=input_request.session_id,\\n                    # run_graph_internal falls back to the flow id when no session id is\\n                    # supplied; mirror that here so an identified run with no session id\\n                    # scopes to ``<end-user>::<flow_id>`` rather than a bare flow id.\\n                    default_session_id=flow_id_str,\\n                )\\n            except EndUserIdentityRequiredError as exc:\\n                raise HTTPException(\\n                    status_code=status.HTTP_401_UNAUTHORIZED,\\n                    detail=end_user_required_detail(exc),\\n                ) from exc\\n            if scoped is not None:\\n                effective_session_id = scoped.session_id\\n                graph.persist_messages = scoped.persist\\n                # Carry the end-user identity onto the graph so services (chat memory,\\n                # and later telemetry / agent file writes) scope per-user state to the\\n                # end user. None for an anonymous run.\\n                graph.end_user_id = scoped.end_user_id\\n\\n        inputs = None\\n        if input_request.input_value is not None:\\n            inputs = [\\n                InputValueRequest(\\n                    components=[],\\n                    input_value=input_request.input_value,\\n                    type=input_request.input_type,\\n                )\\n            ]\\n        if input_request.output_component:\\n            outputs = [input_request.output_component]\\n        else:\\n            outputs = [\\n                vertex.id\\n                for vertex in graph.vertices\\n                if input_request.output_type == \\\"debug\\\"\\n                or (\\n                    vertex.is_output\\n                    and (input_request.output_type == \\\"any\\\" or input_request.output_type in vertex.id.lower())  # type: ignore[operator]\\n                )\\n            ]\\n\\n        # Create a WORKFLOW job record so memory-base on_flow_output can track this run.\\n        if user_id is None:\\n            raise HTTPException(\\n                status_code=status.HTTP_401_UNAUTHORIZED,\\n                detail=\\\"Authentication required to run flows.\\\",\\n            )\\n\\n        try:\\n            _job_svc = get_job_service()\\n            await _job_svc.create_job(\\n                job_id=run_id_uuid,\\n                flow_id=flow.id,\\n                user_id=user_id,\\n                job_type=JobType.WORKFLOW,\\n                # Record the serving end user (set on the graph by resolve_serving_scope) so\\n                # status/stop isolate to it; user_id stays the executing SID. See F8. Defensive\\n                # getattr: the warm-run path may hand back a lightweight graph stand-in without\\n                # this attribute, matching every other end_user_id read in the codebase.\\n                end_user_id=getattr(graph, \\\"end_user_id\\\", None),\\n            )\\n            # The funnel default. Binding is outermost-wins, so a caller that already named its\\n            # surface (webhook, mcp, openai_responses) keeps it and only the bare v1 route lands\\n            # here; a new surface that reuses simple_run_flow is labelled \\\"v1\\\" rather than nothing.\\n            with execution_protocol(\\\"v1\\\"):\\n                task_result, session_id = await _job_svc.execute_with_status(\\n                    run_id_uuid,\\n                    run_graph_internal,\\n                    graph=graph,\\n                    flow_id=flow_id_str,\\n                    session_id=effective_session_id,\\n                    inputs=inputs,\\n                    outputs=outputs,\\n                    stream=stream,\\n                    event_manager=event_manager,\\n                )\\n        except Exception as exc:\\n            if isinstance(exc, HTTPException):\\n                if expose_error_details:\\n                    raise\\n                raise error_for_client(exc, expose_details=expose_error_details) from exc\\n            await logger.aerror(\\n                \\\"Workflow job execution failed for flow %s: %s\\\",\\n                flow.id,\\n                str(exc),\\n                exc_info=True,\\n            )\\n            client_error = error_for_client(exc, expose_details=expose_error_details)\\n            raise APIException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                exception=client_error,\\n                flow=flow if expose_error_details else None,\\n            ) from exc\\n\\n        # Memory-base auto-capture resolves the flow owner's private credentials.\\n        # Delegated/public executions must never trigger that owner-scoped side effect.\\n        if flow.user_id is not None and str(flow.user_id) == str(user_id):\\n            try:\\n                _run_id_uuid = UUID(graph.run_id) if graph.run_id else None  # type-cast only\\n                await get_task_service().fire_and_forget_task(\\n                    get_memory_base_service().on_flow_output,\\n                    flow_id=flow.id,\\n                    session_id=session_id,\\n                    job_id=_run_id_uuid,\\n                )\\n            except (RuntimeError, ValueError, OSError):\\n                await logger.awarning(\\\"Memory base hook scheduling failed for flow %s\\\", flow.id, exc_info=True)\\n\\n        return RunResponse(outputs=task_result, session_id=session_id)\\n\\n    except sa.exc.StatementError as exc:\\n        raise ValueError(str(exc)) from exc\\n    finally:\\n        reset_current_model_provider_policy_context(policy_context_token)\\n\\n\\ndef _get_vertex_ids_from_flow(flow: Flow) -> list[str]:\\n    \\\"\\\"\\\"Extract vertex IDs from flow data.\\\"\\\"\\\"\\n    if not flow.data or not flow.data.get(\\\"nodes\\\"):\\n        return []\\n    return [node.get(\\\"id\\\") for node in flow.data.get(\\\"nodes\\\", []) if node.get(\\\"id\\\")]\\n\\n\\nasync def simple_run_flow_task(\\n    flow: Flow,\\n    input_request: SimplifiedAPIRequest,\\n    *,\\n    stream: bool = False,\\n    api_key_user: User | None = None,\\n    event_manager: EventManager | None = None,\\n    telemetry_service=None,\\n    start_time: float | None = None,\\n    run_id: str | None = None,\\n    emit_events: bool = False,\\n    flow_id: str | None = None,\\n    http_request: Request | None = None,\\n):\\n    \\\"\\\"\\\"Run a flow task as a BackgroundTask, therefore it should not throw exceptions.\\n\\n    Args:\\n        flow: The flow to execute\\n        input_request: The simplified API request\\n        stream: Whether to stream results\\n        api_key_user: The user executing the flow\\n        event_manager: Event manager for streaming\\n        telemetry_service: Service for logging telemetry\\n        start_time: Start time for duration calculation\\n        run_id: Unique ID for this run\\n        emit_events: Whether to emit events to webhook_event_manager (for UI feedback)\\n        flow_id: Flow ID for event emission (required if emit_events=True)\\n        http_request: The incoming HTTP request, forwarded so serving-plane end-user\\n            session scoping can read the trusted identity header (None to skip).\\n    \\\"\\\"\\\"\\n    should_emit = emit_events and flow_id\\n\\n    # Create an EventManager that forwards events to webhook SSE if we should emit\\n    webhook_em = None\\n    if should_emit and event_manager is None and flow_id is not None:\\n        webhook_em = create_webhook_event_manager(flow_id, run_id)\\n\\n    # Use provided event_manager or the webhook one\\n    effective_event_manager = event_manager or webhook_em\\n\\n    try:\\n        if should_emit and flow_id is not None:\\n            vertex_ids = _get_vertex_ids_from_flow(flow)\\n            await webhook_event_manager.emit(\\n                flow_id,\\n                \\\"vertices_sorted\\\",\\n                {\\\"ids\\\": vertex_ids, \\\"to_run\\\": vertex_ids, \\\"run_id\\\": run_id},\\n            )\\n\\n        with execution_protocol(\\\"webhook\\\"):\\n            result = await simple_run_flow(\\n                flow=flow,\\n                input_request=input_request,\\n                stream=stream,\\n                api_key_user=api_key_user,\\n                event_manager=effective_event_manager,\\n                run_id=run_id,\\n                expose_error_details=api_key_user is not None and _caller_owns_flow(flow, api_key_user),\\n                http_request=http_request,\\n            )\\n\\n        if should_emit and flow_id is not None:\\n            await webhook_event_manager.emit(flow_id, \\\"end\\\", {\\\"run_id\\\": run_id, \\\"success\\\": True})\\n\\n        if telemetry_service and start_time is not None:\\n            await telemetry_service.log_package_run(\\n                RunPayload(\\n                    run_is_webhook=True,\\n                    run_seconds=int(time.perf_counter() - start_time),\\n                    run_success=True,\\n                    run_error_message=\\\"\\\",\\n                    run_id=run_id,\\n                )\\n            )\\n        return result  # noqa: TRY300\\n\\n    except Exception as exc:  # noqa: BLE001\\n        await logger.aexception(f\\\"Error running flow {flow.id} task\\\")\\n\\n        if should_emit and flow_id is not None:\\n            await webhook_event_manager.emit(flow_id, \\\"end\\\", {\\\"run_id\\\": run_id, \\\"success\\\": False, \\\"error\\\": str(exc)})\\n\\n        if telemetry_service and start_time is not None:\\n            await telemetry_service.log_package_run(\\n                RunPayload(\\n                    run_is_webhook=True,\\n                    run_seconds=int(time.perf_counter() - start_time),\\n                    run_success=False,\\n                    run_error_message=str(exc),\\n                    run_id=run_id,\\n                )\\n            )\\n        return None\\n\\n\\ndef _v1_run_response(response: RunResponse) -> JSONResponse:\\n    \\\"\\\"\\\"Serialize a RunResponse with content_blocks projected to the v1 shape.\\n\\n    The /run result holds Messages whose content_blocks serialize through the\\n    shared (v2) Message serializer, so project them at this v1 boundary to keep\\n    the release-1.11.0 wire shape. The live objects and the v2 path are untouched.\\n    \\\"\\\"\\\"\\n    return JSONResponse(content=project_payload_to_v1(jsonable_encoder(response)))\\n\\n\\ndef _project_run_event(value):\\n    \\\"\\\"\\\"Project a /run stream event's content_blocks to the v1 shape.\\n\\n    Covers add_message events and the final ``end`` result (which nests messages)\\n    before they reach a v1 client. The v2 path drains a different queue and never\\n    passes through here. The substring guard skips events that carry no\\n    content_blocks (tokens, ...).\\n    \\\"\\\"\\\"\\n    if not isinstance(value, (bytes, bytearray)):\\n        return value\\n    raw = value.decode(\\\"utf-8\\\")\\n    if \\\"content_blocks\\\" not in raw:\\n        return value\\n    try:\\n        event = json.loads(raw.rstrip(\\\"\\\\n\\\"))\\n    except (ValueError, TypeError):\\n        return value\\n    return (json.dumps(project_payload_to_v1(event)) + \\\"\\\\n\\\\n\\\").encode(\\\"utf-8\\\")\\n\\n\\nasync def consume_and_yield(queue: asyncio.Queue, client_consumed_queue: asyncio.Queue) -> AsyncGenerator:\\n    \\\"\\\"\\\"Consumes events from a queue and yields them to the client while tracking timing metrics.\\n\\n    This coroutine continuously pulls events from the input queue and yields them to the client.\\n    It tracks timing metrics for how long events spend in the queue and how long the client takes\\n    to process them.\\n\\n    Args:\\n        queue (asyncio.Queue): The queue containing events to be consumed and yielded\\n        client_consumed_queue (asyncio.Queue): A queue for tracking when the client has consumed events\\n\\n    Yields:\\n        The value from each event in the queue\\n\\n    Notes:\\n        - Events are tuples of (event_id, value, put_time)\\n        - Breaks the loop when receiving a None value, signaling completion\\n        - Tracks and logs timing metrics for queue time and client processing time\\n        - Notifies client consumption via client_consumed_queue\\n    \\\"\\\"\\\"\\n    while True:\\n        event_id, value, put_time = await queue.get()\\n        if value is None:\\n            break\\n        get_time = time.time()\\n        yield _project_run_event(value)\\n        get_time_yield = time.time()\\n        client_consumed_queue.put_nowait(event_id)\\n        await logger.adebug(\\n            f\\\"consumed event {event_id} \\\"\\n            f\\\"(time in queue, {get_time - put_time:.4f}, \\\"\\n            f\\\"client {get_time_yield - get_time:.4f})\\\"\\n        )\\n\\n\\nasync def run_flow_generator(\\n    flow: Flow,\\n    input_request: SimplifiedAPIRequest,\\n    api_key_user: User | None,\\n    event_manager: EventManager,\\n    client_consumed_queue: asyncio.Queue,\\n    context: dict | None = None,\\n    *,\\n    expose_error_details: bool = False,\\n    http_request: Request | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Executes a flow asynchronously and manages event streaming to the client.\\n\\n    This coroutine runs a flow with streaming enabled and handles the event lifecycle,\\n    including success completion and error scenarios.\\n\\n    Args:\\n        flow (Flow): The flow to execute\\n        input_request (SimplifiedAPIRequest): The input parameters for the flow\\n        api_key_user (User | None): Optional authenticated user running the flow\\n        event_manager (EventManager): Manages the streaming of events to the client\\n        client_consumed_queue (asyncio.Queue): Tracks client consumption of events\\n        context (dict | None): Optional context to pass to the flow\\n        expose_error_details: Whether client events may contain owner debugging details.\\n        http_request: The incoming HTTP request, forwarded so serving-plane end-user\\n            session scoping can read the trusted identity header (None to skip).\\n\\n    Events Generated:\\n        - \\\"add_message\\\": Sent when new messages are added during flow execution\\n        - \\\"token\\\": Sent for each token generated during streaming\\n        - \\\"end\\\": Sent when flow execution completes, includes final result\\n        - \\\"error\\\": Sent if an error occurs during execution\\n\\n    Notes:\\n        - Runs the flow with streaming enabled via simple_run_flow()\\n        - On success, sends the final result via event_manager.on_end()\\n        - On error, logs the error and sends it via event_manager.on_error()\\n        - Always sends a final None event to signal completion\\n    \\\"\\\"\\\"\\n    try:\\n        result = await simple_run_flow(\\n            flow=flow,\\n            input_request=input_request,\\n            stream=True,\\n            api_key_user=api_key_user,\\n            event_manager=event_manager,\\n            context=context,\\n            expose_error_details=expose_error_details,\\n            http_request=http_request,\\n        )\\n        event_manager.on_end(data={\\\"result\\\": result.model_dump()})\\n        await client_consumed_queue.get()\\n    except Exception as e:  # noqa: BLE001 - Catch ALL exceptions to ensure errors are propagated in streaming\\n        await logger.aerror(f\\\"Error running flow: {e}\\\")\\n        client_error = error_for_client(e, expose_details=expose_error_details)\\n        event_manager.on_error(data={\\\"error\\\": str(client_error)})\\n    finally:\\n        await event_manager.queue.put((None, None, time.time))\\n\\n\\nasync def get_flow_for_api_key_user(\\n    flow_id_or_name: str,\\n    api_key_user: Annotated[UserRead, Depends(api_key_security)],\\n) -> FlowRead:\\n    \\\"\\\"\\\"Auth-aware wrapper around ``get_flow_by_id_or_endpoint_name`` for API-key routes.\\n\\n    Using the raw helper as a FastAPI ``Depends`` exposed ``user_id`` as a\\n    plain query parameter that no real caller sets, so flow lookups on the\\n    ``/run*`` routes bypassed user scoping entirely. This wrapper pulls the\\n    authenticated user from ``api_key_security`` and passes it to the helper,\\n    so cross-user access fails closed with 404 at the helper layer.\\n\\n    When an authorization plugin is registered, the lookup is\\n    share-aware (load by id, route guard decides access). The OSS pass-through\\n    default keeps the owner-scoped lookup.\\n    \\\"\\\"\\\"\\n    # These wrappers always pair with ``ensure_flow_permission`` in the route\\n    # handler, so opting in to share-aware widening is safe.\\n    return await get_flow_by_id_or_endpoint_name(flow_id_or_name, api_key_user.id, widen_for_shares=True)\\n\\n\\nasync def get_flow_for_current_user(\\n    flow_id_or_name: str,\\n    current_user: CurrentActiveUser,\\n) -> FlowRead:\\n    \\\"\\\"\\\"Session-auth variant of :func:`get_flow_for_api_key_user`.\\\"\\\"\\\"\\n    return await get_flow_by_id_or_endpoint_name(flow_id_or_name, current_user.id, widen_for_shares=True)\\n\\n\\nclass SseAuth:\\n    \\\"\\\"\\\"Helper to carry both authenticated user and flow for SSE subscription.\\\"\\\"\\\"\\n\\n    def __init__(self, user: User | UserRead, flow: FlowRead):\\n        self.user = user\\n        self.flow = flow\\n\\n\\nasync def get_flow_for_sse_user(\\n    flow_id_or_name: str,\\n    user: Annotated[User | UserRead, Depends(get_current_user_for_sse)],\\n) -> SseAuth:\\n    \\\"\\\"\\\"Auth-aware dependency for SSE routes.\\n\\n    Returns both the SSE user and the flow so the route can call\\n    ``ensure_flow_permission`` *before* subscribing to the event stream.\\n    Widening to share-aware lookup is safe here only because the route\\n    immediately enforces ``flow:read``; without that enforcement, a non-owner\\n    with cross-user fetch enabled could subscribe to another user's webhook\\n    event stream and exfiltrate flow id/name plus event payloads.\\n    \\\"\\\"\\\"\\n    flow = await get_flow_by_id_or_endpoint_name(flow_id_or_name, user_id=user.id, widen_for_shares=True)\\n    return SseAuth(user=user, flow=flow)\\n\\n\\nclass WebhookAuth:\\n    \\\"\\\"\\\"Helper to carry both authenticated user and flow for webhook execution.\\\"\\\"\\\"\\n\\n    def __init__(self, user: UserRead, flow: FlowRead):\\n        self.user = user\\n        self.flow = flow\\n\\n\\nasync def get_webhook_auth(\\n    flow_id_or_name: str,\\n    request: Request,\\n) -> WebhookAuth:\\n    \\\"\\\"\\\"Auth-aware dependency that resolves both the webhook user and the flow.\\n\\n    Centralizes the security logic for webhook run endpoints.\\n    \\\"\\\"\\\"\\n    webhook_user = await get_auth_service().get_webhook_user(flow_id_or_name, request)\\n    # Webhook route also calls ``ensure_flow_permission`` after, so widening\\n    # for shared resources is acceptable here.\\n    flow = await get_flow_by_id_or_endpoint_name(flow_id_or_name, user_id=webhook_user.id, widen_for_shares=True)\\n    return WebhookAuth(user=webhook_user, flow=flow)\\n\\n\\nasync def _run_flow_internal(\\n    *,\\n    background_tasks: BackgroundTasks,\\n    flow: FlowRead | None,\\n    input_request: SimplifiedAPIRequest | None,\\n    stream: bool,\\n    api_key_user: User | UserRead,\\n    context: dict | None,\\n    http_request: Request,\\n) -> StreamingResponse | RunResponse:\\n    \\\"\\\"\\\"Internal function containing the core business logic for running a flow.\\n\\n    This function is shared between session-based and API key-based authentication endpoints.\\n\\n    Args:\\n        background_tasks (BackgroundTasks): FastAPI background task manager\\n        flow (FlowRead | None): The flow to execute, loaded via dependency\\n        input_request (SimplifiedAPIRequest | None): Input parameters for the flow\\n        stream (bool): Whether to stream the response\\n        api_key_user (User | UserRead): Authenticated user (either from session or API key)\\n        context (dict | None): Optional context to pass to the flow\\n        http_request (Request): The incoming HTTP request for extracting global variables\\n\\n    Returns:\\n        Union[StreamingResponse, RunResponse]: Either a streaming response for real-time results\\n        or a RunResponse with the complete execution results\\n\\n    Raises:\\n        HTTPException: For flow not found (404) or invalid input (400)\\n        APIException: For internal execution errors (500)\\n    \\\"\\\"\\\"\\n    # Authorization happens upstream. A granted share may execute the stored\\n    # graph, but only the owner may mutate it through request tweaks.\\n    telemetry_service = get_telemetry_service()\\n\\n    # If input_request is None, manually parse the request body\\n    # This happens when FastAPI can't automatically parse it due to the Request parameter\\n    if input_request is None:\\n        input_request = await parse_input_request_from_body(http_request)\\n\\n    if flow is None:\\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Flow not found\\\")\\n\\n    expose_error_details = _caller_owns_flow(flow, api_key_user)\\n    _enforce_owner_only_tweaks(flow, api_key_user, input_request.tweaks)\\n\\n    # Extract request-level variables from headers with prefix X-LANGFLOW-GLOBAL-VAR-*\\n    request_variables = extract_global_variables_from_headers(http_request.headers)\\n\\n    # Merge request variables with existing context\\n    if request_variables:\\n        if context is None:\\n            context = {\\\"request_variables\\\": request_variables}\\n        else:\\n            context = context.copy()  # Don't modify the original context\\n            context[\\\"request_variables\\\"] = request_variables\\n\\n    start_time = time.perf_counter()\\n\\n    # Required-identity gate must fire BEFORE the streaming branch: that branch returns a\\n    # StreamingResponse with 200 headers before simple_run_flow runs, so its 401 would only ever\\n    # arrive as an in-stream error event. Enforce it synchronously here (idempotent with the scope\\n    # simple_run_flow applies again on the same http_request). The non-stream path also flows\\n    # through this \u2014 harmless, it already surfaced the 401 by propagation. Mirrors the webhook\\n    # pre-check (I3); kept outside any try so the 401 is not rewritten. See BUG-01.\\n    try:\\n        resolve_serving_scope(\\n            http_request=http_request,\\n            requested_session_id=input_request.session_id,\\n            default_session_id=str(flow.id),\\n        )\\n    except EndUserIdentityRequiredError as exc:\\n        raise HTTPException(\\n            status_code=status.HTTP_401_UNAUTHORIZED,\\n            detail=end_user_required_detail(exc),\\n        ) from exc\\n\\n    if stream:\\n        asyncio_queue: asyncio.Queue = asyncio.Queue()\\n        asyncio_queue_client_consumed: asyncio.Queue = asyncio.Queue()\\n        event_manager = create_stream_tokens_event_manager(queue=asyncio_queue)\\n        main_task = asyncio.create_task(\\n            run_flow_generator(\\n                flow=flow,\\n                input_request=input_request,\\n                api_key_user=api_key_user,\\n                event_manager=event_manager,\\n                client_consumed_queue=asyncio_queue_client_consumed,\\n                context=context,\\n                expose_error_details=expose_error_details,\\n                http_request=http_request,\\n            )\\n        )\\n\\n        async def on_disconnect() -> None:\\n            await logger.adebug(\\\"Client disconnected, closing tasks\\\")\\n            main_task.cancel()\\n\\n        return StreamingResponse(\\n            consume_and_yield(asyncio_queue, asyncio_queue_client_consumed),\\n            background=on_disconnect,\\n            media_type=\\\"text/event-stream\\\",\\n        )\\n\\n    run_id = str(uuid4())\\n    try:\\n        result = await simple_run_flow(\\n            flow=flow,\\n            input_request=input_request,\\n            stream=stream,\\n            api_key_user=api_key_user,\\n            context=context,\\n            run_id=run_id,\\n            expose_error_details=expose_error_details,\\n            http_request=http_request,\\n        )\\n        end_time = time.perf_counter()\\n        background_tasks.add_task(\\n            telemetry_service.log_package_run,\\n            RunPayload(\\n                run_is_webhook=False,\\n                run_seconds=int(end_time - start_time),\\n                run_success=True,\\n                run_error_message=\\\"\\\",\\n                run_id=run_id,\\n            ),\\n        )\\n\\n    except ValueError as exc:\\n        background_tasks.add_task(\\n            telemetry_service.log_package_run,\\n            RunPayload(\\n                run_is_webhook=False,\\n                run_seconds=int(time.perf_counter() - start_time),\\n                run_success=False,\\n                run_error_message=str(exc),\\n                run_id=run_id,\\n            ),\\n        )\\n        if \\\"badly formed hexadecimal UUID string\\\" in str(exc):\\n            # This means the Flow ID is not a valid UUID which means it can't find the flow\\n            http_error = HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc))\\n            raise error_for_client(http_error, expose_details=expose_error_details) from exc\\n        if isinstance(exc, CustomComponentValidationError):\\n            http_error = HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc))\\n            raise error_for_client(http_error, expose_details=expose_error_details) from exc\\n        if \\\"not found\\\" in str(exc):\\n            http_error = HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=str(exc))\\n            raise error_for_client(http_error, expose_details=expose_error_details) from exc\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n        raise APIException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            exception=client_error,\\n            flow=flow if expose_error_details else None,\\n        ) from exc\\n    except InvalidChatInputError as exc:\\n        http_error = HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc))\\n        raise error_for_client(http_error, expose_details=expose_error_details) from exc\\n    except HTTPException as exc:\\n        if expose_error_details:\\n            raise\\n        raise error_for_client(exc, expose_details=expose_error_details) from exc\\n    except TweakRefusedError:\\n        # A refused tweak is a caller error, not a server fault. The generic\\n        # handler below turns it into a 500 and discards the structured body\\n        # naming the refused keys, so let the app-level handler answer with 422.\\n        #\\n        # Deliberately not routed through error_for_client. That helper only\\n        # preserves the status of an HTTPException, and this is not one, so\\n        # redacting would degrade it to RuntimeError -> 500 and reinstate the\\n        # exact bug this re-raise exists to fix, for delegated callers only.\\n        # The cost is that the refusal reason tells a non-owner whether the\\n        # flow declares an allowlist or the deployment refuses tweaks. Accepted:\\n        # no data, no stack trace, and the refused names are the caller's own\\n        # request keys. A caller who cannot tell a refused tweak from an applied\\n        # one is the failure this whole path is here to prevent.\\n        raise\\n    except Exception as exc:\\n        background_tasks.add_task(\\n            telemetry_service.log_package_run,\\n            RunPayload(\\n                run_is_webhook=False,\\n                run_seconds=int(time.perf_counter() - start_time),\\n                run_success=False,\\n                run_error_message=str(exc),\\n                run_id=run_id,\\n            ),\\n        )\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n        raise APIException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            exception=client_error,\\n            flow=flow if expose_error_details else None,\\n        ) from exc\\n\\n    return _v1_run_response(result)\\n\\n\\n@router.post(\\\"/run/{flow_id_or_name}\\\", response_model=None, response_model_exclude_none=True)\\nasync def simplified_run_flow(\\n    *,\\n    background_tasks: BackgroundTasks,\\n    flow: Annotated[FlowRead, Depends(get_flow_for_api_key_user)],\\n    input_request: SimplifiedAPIRequest | None = None,\\n    stream: bool = False,\\n    api_key_user: Annotated[UserRead, Depends(api_key_security)],\\n    context: dict | None = None,\\n    http_request: Request,\\n):\\n    \\\"\\\"\\\"Executes a specified flow by ID with support for streaming and telemetry (API key auth).\\n\\n    This endpoint executes a flow identified by ID or name, with options for streaming the response\\n    and tracking execution metrics. It handles both streaming and non-streaming execution modes.\\n    This endpoint uses API key authentication (Bearer token).\\n\\n    Args:\\n        background_tasks (BackgroundTasks): FastAPI background task manager\\n        flow (FlowRead | None): The flow to execute, loaded via dependency\\n        input_request (SimplifiedAPIRequest | None): Input parameters for the flow\\n        stream (bool): Whether to stream the response\\n        api_key_user (UserRead): Authenticated user from API key\\n        context (dict | None): Optional context to pass to the flow\\n        http_request (Request): The incoming HTTP request for extracting global variables\\n\\n    Returns:\\n        Union[StreamingResponse, RunResponse]: Either a streaming response for real-time results\\n        or a RunResponse with the complete execution results\\n\\n    Raises:\\n        HTTPException: For flow not found (404) or invalid input (400)\\n        APIException: For internal execution errors (500)\\n\\n    Notes:\\n        - Supports both streaming and non-streaming execution modes\\n        - Tracks execution time and success/failure via telemetry\\n        - Handles graceful client disconnection in streaming mode\\n        - Provides detailed error handling with appropriate HTTP status codes\\n        - Extracts global variables from HTTP headers with prefix X-LANGFLOW-GLOBAL-VAR-*\\n        - Merges extracted variables with the context parameter as \\\"request_variables\\\"\\n        - In streaming mode, uses EventManager to handle events:\\n            - \\\"add_message\\\": New messages during execution\\n            - \\\"token\\\": Individual tokens during streaming\\n            - \\\"end\\\": Final execution result\\n        - Authentication: Requires API key (Bearer token)\\n    \\\"\\\"\\\"\\n    await ensure_flow_permission(\\n        api_key_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n    return await _run_flow_internal(\\n        background_tasks=background_tasks,\\n        flow=flow,\\n        input_request=input_request,\\n        stream=stream,\\n        api_key_user=api_key_user,\\n        context=context,\\n        http_request=http_request,\\n    )\\n\\n\\n@router.post(\\n    \\\"/run/session/{flow_id_or_name}\\\", response_model=None, response_model_exclude_none=True, include_in_schema=False\\n)\\nasync def simplified_run_flow_session(\\n    *,\\n    background_tasks: BackgroundTasks,\\n    flow: Annotated[FlowRead, Depends(get_flow_for_current_user)],\\n    input_request: SimplifiedAPIRequest | None = None,\\n    stream: bool = False,\\n    api_key_user: CurrentActiveUser,\\n    session: DbSession,\\n    context: dict | None = None,\\n    http_request: Request,\\n):\\n    \\\"\\\"\\\"Executes a specified flow by ID with support for streaming and telemetry (session auth).\\n\\n    This endpoint executes a flow identified by ID or name, with options for streaming the response\\n    and tracking execution metrics. It handles both streaming and non-streaming execution modes.\\n    This endpoint uses session-based authentication (cookies).\\n\\n    Args:\\n        background_tasks (BackgroundTasks): FastAPI background task manager\\n        flow (FlowRead | None): The flow to execute, loaded via dependency\\n        input_request (SimplifiedAPIRequest | None): Input parameters for the flow\\n        stream (bool): Whether to stream the response\\n        api_key_user (User): Authenticated user from session\\n        session (AsyncSession): Request-scoped DB session (shared with the auth\\n            dependency); its transaction is released before the flow runs\\n        context (dict | None): Optional context to pass to the flow\\n        http_request (Request): The incoming HTTP request for extracting global variables\\n\\n    Returns:\\n        Union[StreamingResponse, RunResponse]: Either a streaming response for real-time results\\n        or a RunResponse with the complete execution results\\n\\n    Raises:\\n        HTTPException: For flow not found (404) or invalid input (400)\\n        APIException: For internal execution errors (500)\\n\\n    Notes:\\n        - Supports both streaming and non-streaming execution modes\\n        - Tracks execution time and success/failure via telemetry\\n        - Handles graceful client disconnection in streaming mode\\n        - Provides detailed error handling with appropriate HTTP status codes\\n        - Extracts global variables from HTTP headers with prefix X-LANGFLOW-GLOBAL-VAR-*\\n        - Merges extracted variables with the context parameter as \\\"request_variables\\\"\\n        - In streaming mode, uses EventManager to handle events:\\n            - \\\"add_message\\\": New messages during execution\\n            - \\\"token\\\": Individual tokens during streaming\\n            - \\\"end\\\": Final execution result\\n        - Authentication: Requires active session (cookies)\\n        - Feature Flag: Only available when agentic_experience is enabled\\n    \\\"\\\"\\\"\\n    # Feature flag: Only allow access if agentic_experience is enabled\\n    if not get_settings_service().settings.agentic_experience:\\n        raise HTTPException(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            detail=\\\"This endpoint is not available\\\",\\n        )\\n\\n    await ensure_flow_permission(\\n        api_key_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    # ``session`` is the same cached dependency the auth chain used, so this\\n    # ends the transaction opened by the auth reads before the flow runs \u2014\\n    # the run can take minutes and would otherwise hold the request\\n    # transaction (and its pooled connection) open the whole time (#14445).\\n    # The API-key ``/run`` variant is not affected: ``api_key_security``\\n    # scopes its own short-lived session.\\n    await release_db_transaction(session)\\n\\n    return await _run_flow_internal(\\n        background_tasks=background_tasks,\\n        flow=flow,\\n        input_request=input_request,\\n        stream=stream,\\n        api_key_user=api_key_user,\\n        context=context,\\n        http_request=http_request,\\n    )\\n\\n\\n@router.get(\\\"/webhook-events/{flow_id_or_name}\\\", include_in_schema=False)\\nasync def webhook_events_stream(\\n    auth: Annotated[SseAuth, Depends(get_flow_for_sse_user)],\\n    request: Request,\\n    session: DbSession,\\n):\\n    \\\"\\\"\\\"Server-Sent Events (SSE) endpoint for real-time webhook build updates.\\n\\n    When a flow is open in the UI, this endpoint provides live feedback\\n    of webhook execution progress, similar to clicking \\\"Play\\\" in the UI.\\n\\n    Authentication: Requires user to be logged in (via cookie) or provide API key.\\n    The user must own the flow OR have an authorization-plugin-granted\\n    ``flow:read`` permission to subscribe to its events.\\n    \\\"\\\"\\\"\\n    flow = auth.flow\\n    # Enforce flow:read before subscribing \u2014 the SSE fetcher uses share-aware\\n    # lookup, so without this check a non-owner with cross-user fetch enabled\\n    # would receive another user's webhook event payloads.\\n    await ensure_flow_permission(\\n        auth.user,\\n        FlowAction.READ,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=getattr(flow, \\\"workspace_id\\\", None),\\n        folder_id=getattr(flow, \\\"folder_id\\\", None),\\n    )\\n\\n    # ``session`` is the same cached dependency the SSE auth chain used. The\\n    # EventSource stream below is indefinite and the session dependency is\\n    # only torn down when it ends, so without this commit every open tab\\n    # would hold a pooled connection in an idle transaction (#14445).\\n    await release_db_transaction(session)\\n\\n    async def event_generator() -> AsyncGenerator[str, None]:\\n        \\\"\\\"\\\"Generate SSE events from the webhook event manager.\\\"\\\"\\\"\\n        flow_id_str = str(flow.id)\\n        queue = await webhook_event_manager.subscribe(flow_id_str)\\n\\n        try:\\n            # Send initial connection event\\n            yield f\\\"event: connected\\\\ndata: {json.dumps({'flow_id': flow_id_str, 'flow_name': flow.name})}\\\\n\\\\n\\\"\\n\\n            while True:\\n                if await request.is_disconnected():\\n                    break\\n\\n                try:\\n                    event = await asyncio.wait_for(queue.get(), timeout=SSE_HEARTBEAT_TIMEOUT_SECONDS)\\n                    event_type = event[\\\"event\\\"]\\n                    payload = event[\\\"data\\\"]\\n                    # add_message carries message.model_dump(), which holds the new\\n                    # content_blocks union at both the top level and the nested Data\\n                    # mirror. Project both to the v1 shape for this v1 SSE, matching\\n                    # the build stream and /run.\\n                    if event_type == \\\"add_message\\\":\\n                        payload = project_payload_to_v1(payload)\\n                    event_data = json.dumps(payload)\\n                    yield f\\\"event: {event_type}\\\\ndata: {event_data}\\\\n\\\\n\\\"\\n                except asyncio.TimeoutError:\\n                    yield f\\\"event: heartbeat\\\\ndata: {json.dumps({'timestamp': time.time()})}\\\\n\\\\n\\\"\\n\\n        except asyncio.CancelledError:\\n            pass\\n        finally:\\n            await webhook_event_manager.unsubscribe(flow_id_str, queue)\\n\\n    return StreamingResponse(\\n        event_generator(),\\n        media_type=\\\"text/event-stream\\\",\\n        headers={\\n            \\\"Cache-Control\\\": \\\"no-cache\\\",\\n            \\\"Connection\\\": \\\"keep-alive\\\",\\n            \\\"X-Accel-Buffering\\\": \\\"no\\\",\\n        },\\n    )\\n\\n\\n@router.post(\\\"/webhook/{flow_id_or_name}\\\", response_model=dict, status_code=HTTPStatus.ACCEPTED)  # noqa: RUF100, FAST003\\nasync def webhook_run_flow(\\n    auth: Annotated[WebhookAuth, Depends(get_webhook_auth)],\\n    request: Request,\\n):\\n    \\\"\\\"\\\"Run a flow using a webhook request.\\n\\n    Args:\\n        auth: Resolved webhook user and flow, scoped to the authenticated caller.\\n        request: The incoming HTTP request.\\n\\n    Returns:\\n        A dictionary containing the status of the task.\\n\\n    Raises:\\n        HTTPException: If the flow is not found or if there is an error processing the request.\\n    \\\"\\\"\\\"\\n    telemetry_service = get_telemetry_service()\\n    start_time = time.perf_counter()\\n    await logger.adebug(\\\"Received webhook request\\\")\\n    error_msg = \\\"\\\"\\n\\n    # Webhook user and flow are resolved by the dependency\\n    webhook_user = auth.user\\n    flow = auth.flow\\n\\n    await ensure_flow_permission(\\n        webhook_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    try:\\n        data = await request.body()\\n    except Exception as exc:\\n        error_msg = str(exc)\\n        raise HTTPException(status_code=500, detail=error_msg) from exc\\n\\n    if not data:\\n        error_msg = \\\"Request body is empty. You should provide a JSON payload containing the flow ID.\\\"\\n        raise HTTPException(status_code=400, detail=error_msg)\\n\\n    raise_if_hitl_unsupported(flow.data or {})\\n\\n    # The run executes in a fire-and-forget background task that never raises, so the identity gate\\n    # inside simple_run_flow can't surface its 401 from the webhook. Enforce it synchronously here so\\n    # a required-but-absent end-user identity is rejected BEFORE the task is scheduled (idempotent\\n    # with the scoping simple_run_flow does again on the same http_request). See I3. Kept outside the\\n    # try below so the 401 is not rewritten to a 500 by its generic handler.\\n    try:\\n        resolve_serving_scope(http_request=request, requested_session_id=None, default_session_id=str(flow.id))\\n    except EndUserIdentityRequiredError as exc:\\n        raise HTTPException(\\n            status_code=status.HTTP_401_UNAUTHORIZED,\\n            detail=end_user_required_detail(exc),\\n        ) from exc\\n\\n    try:\\n        # get all webhook components in the flow\\n        webhook_components = get_all_webhook_components_in_flow(flow.data)\\n        tweaks = {}\\n\\n        for component in webhook_components:\\n            tweaks[component[\\\"id\\\"]] = {\\\"data\\\": data.decode() if isinstance(data, bytes) else data}\\n        input_request = SimplifiedAPIRequest(\\n            input_value=\\\"\\\",\\n            input_type=\\\"chat\\\",\\n            output_type=\\\"chat\\\",\\n            tweaks=tweaks,\\n            session_id=None,\\n        )\\n\\n        # Check if there are UI listeners connected via SSE\\n        flow_id_str = str(flow.id)\\n        has_ui_listeners = webhook_event_manager.has_listeners(flow_id_str)\\n\\n        await logger.adebug(\\\"Starting background task\\\")\\n        run_id = str(uuid4())\\n\\n        # Use asyncio.create_task to run in same event loop (needed for SSE)\\n        background_task = asyncio.create_task(\\n            simple_run_flow_task(\\n                flow=flow,\\n                input_request=input_request,\\n                api_key_user=webhook_user,\\n                telemetry_service=telemetry_service,\\n                start_time=start_time,\\n                run_id=run_id,\\n                emit_events=has_ui_listeners,\\n                flow_id=flow_id_str,\\n                http_request=request,\\n            )\\n        )\\n        # Fire-and-forget: log exceptions but don't block\\n        background_task.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)\\n    except Exception as exc:\\n        error_msg = str(exc)\\n        raise HTTPException(status_code=500, detail=error_msg) from exc\\n\\n    return {\\\"message\\\": \\\"Task started in the background\\\", \\\"status\\\": \\\"in progress\\\"}\\n\\n\\n@router.post(\\n    \\\"/run/advanced/{flow_id_or_name}\\\",\\n    response_model=RunResponse,\\n    response_model_exclude_none=True,\\n)\\nasync def experimental_run_flow(\\n    *,\\n    session: DbSession,\\n    flow: Annotated[Flow, Depends(get_flow_for_api_key_user)],\\n    inputs: list[InputValueRequest] | None = None,\\n    outputs: list[str] | None = None,\\n    tweaks: Annotated[Tweaks | None, Body(embed=True)] = None,\\n    stream: Annotated[bool, Body(embed=True)] = False,\\n    session_id: Annotated[None | str, Body(embed=True)] = None,\\n    api_key_user: Annotated[UserRead, Depends(api_key_security)],\\n) -> RunResponse:\\n    \\\"\\\"\\\"Executes a specified flow by ID with optional input values, output selection, tweaks, and streaming capability.\\n\\n    This endpoint supports running flows with caching to enhance performance and efficiency.\\n\\n    ### Parameters:\\n    - `flow` (Flow): The flow object to be executed, resolved via dependency injection.\\n    - `inputs` (List[InputValueRequest], optional): A list of inputs specifying the input values and components\\n      for the flow. Each input can target specific components and provide custom values.\\n    - `outputs` (List[str], optional): A list of output names to retrieve from the executed flow.\\n      If not provided, all outputs are returned.\\n    - `tweaks` (Optional[Tweaks], optional): A dictionary of tweaks to customize the flow execution.\\n      The tweaks can be used to modify the flow's parameters and components.\\n      Tweaks can be overridden by the input values.\\n    - `stream` (bool, optional): Specifies whether the results should be streamed. Defaults to False.\\n    - `session_id` (Union[None, str], optional): An optional session ID to utilize existing session data for the flow\\n      execution.\\n    - `api_key_user` (User): The user associated with the current API key. Automatically resolved from the API key.\\n\\n    ### Returns:\\n    A `RunResponse` object containing the selected outputs (or all if not specified) of the executed flow\\n    and the session ID.\\n    The structure of the response accommodates multiple inputs, providing a nested list of outputs for each input.\\n\\n    ### Raises:\\n    HTTPException: Indicates issues with finding the specified flow, invalid input formats, or internal errors during\\n    flow execution.\\n\\n    ### Example usage:\\n    ```json\\n    POST /run/flow_id\\n    x-api-key: YOUR_API_KEY\\n    Payload:\\n    {\\n        \\\"inputs\\\": [\\n            {\\\"components\\\": [\\\"component1\\\"], \\\"input_value\\\": \\\"value1\\\"},\\n            {\\\"components\\\": [\\\"component3\\\"], \\\"input_value\\\": \\\"value2\\\"}\\n        ],\\n        \\\"outputs\\\": [\\\"Component Name\\\", \\\"component_id\\\"],\\n        \\\"tweaks\\\": {\\\"parameter_name\\\": \\\"value\\\", \\\"Component Name\\\": {\\\"parameter_name\\\": \\\"value\\\"}, \\\"component_id\\\": {\\\"parameter_name\\\": \\\"value\\\"}}\\n        \\\"stream\\\": false\\n    }\\n    ```\\n\\n    This endpoint facilitates complex flow executions with customized inputs, outputs, and configurations,\\n    catering to diverse application requirements.\\n    \\\"\\\"\\\"  # noqa: E501\\n    await ensure_flow_permission(\\n        api_key_user,\\n        FlowAction.EXECUTE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    expose_error_details = _caller_owns_flow(flow, api_key_user)\\n    _enforce_owner_only_tweaks(flow, api_key_user, tweaks)\\n\\n    flow_id_str = str(flow.id)\\n    if outputs is None:\\n        outputs = []\\n    if inputs is None:\\n        inputs = [InputValueRequest(components=[], input_value=\\\"\\\")]\\n\\n    graph: Graph | None = None\\n    if session_id:\\n        session_service = get_session_service()\\n        try:\\n            session_data = await session_service.load_session(session_id, flow_id=flow_id_str)\\n        except Exception as exc:\\n            await logger.aexception(\\\"Failed to load advanced-run session for flow %s\\\", flow.id)\\n            client_error = error_for_client(exc, expose_details=expose_error_details)\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=str(client_error)) from exc\\n        graph, _artifacts = session_data or (None, None)\\n        if graph is None:\\n            msg = f\\\"Session {session_id} not found\\\"\\n            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=msg)\\n        if not _graph_executes_as_actor(graph, api_key_user, flow_id=flow.id):\\n            # Cache keys are legacy and not actor-scoped. Reusing an instantiated\\n            # graph across principals would retain the first actor's component\\n            # credentials, variables, files, and tweaks. Rebuild the immutable\\n            # stored flow under the current actor instead.\\n            await logger.awarning(\\n                \\\"Ignoring advanced-run graph cached under another execution principal for flow %s\\\",\\n                flow.id,\\n            )\\n            graph = None\\n        elif admin_only_build_required(is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False))):\\n            # The cached graph was compiled under whatever component policy was in force when\\n            # it was cached. Session cache keys carry no policy generation, so a graph cached\\n            # while admin-only mode was off still embeds the caller's own component source and\\n            # would execute it unchecked. Rebuild from stored data through the policy instead.\\n            await logger.awarning(\\n                \\\"Ignoring advanced-run cached graph that predates the admin-only component policy for flow %s\\\",\\n                flow.id,\\n            )\\n            graph = None\\n\\n    if graph is None:\\n        if flow.data is None:\\n            msg = f\\\"Flow {flow_id_str} has no data\\\"\\n            if expose_error_details:\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=msg)\\n            client_error = error_for_client(ValueError(msg), expose_details=False)\\n            raise HTTPException(\\n                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n                detail=str(client_error),\\n            )\\n        try:\\n            # Same caller-aware component policy the other stored-graph run paths apply:\\n            # the persisted graph is caller-controlled, so admin-only mode must resolve its\\n            # component source against the server registry before anything is compiled.\\n            sanitized_flow_data = await prepare_flow_build_for_user(\\n                flow.data,\\n                is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False)),\\n            )\\n            graph_data = deepcopy(sanitized_flow_data if sanitized_flow_data is not None else flow.data)\\n            graph_data = process_tweaks(graph_data, tweaks or {})\\n            raise_if_hitl_unsupported(graph_data)\\n            with scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=api_key_user.id,\\n                is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False)),\\n            ):\\n                graph = Graph.from_payload(\\n                    graph_data,\\n                    flow_id=flow_id_str,\\n                    user_id=str(api_key_user.id),\\n                    flow_name=flow.name,\\n                )\\n        except CustomComponentValidationError as exc:\\n            await logger.aexception(\\\"Advanced-run flow validation failed for flow %s\\\", flow.id)\\n            http_error = HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(exc))\\n            raise error_for_client(http_error, expose_details=expose_error_details) from exc\\n        except HTTPException as exc:\\n            await logger.aexception(\\\"Advanced-run flow validation failed for flow %s\\\", flow.id)\\n            if expose_error_details:\\n                # error_for_client returns ``exc`` itself here; re-raise rather\\n                # than chaining the exception to itself.\\n                raise\\n            raise error_for_client(exc, expose_details=expose_error_details) from exc\\n        except TweakRefusedError:\\n            # Third run route that applies tweaks, and the generic handler below\\n            # would turn a refused tweak into a redacted 500 with a stack trace\\n            # in the logs. Let it through so the app-level handler answers 422\\n            # naming the refused keys, as the setting documents for every mode.\\n            raise\\n        except Exception as exc:\\n            await logger.aexception(\\\"Failed to build advanced-run graph for flow %s\\\", flow.id)\\n            client_error = error_for_client(exc, expose_details=expose_error_details)\\n            raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=str(client_error)) from exc\\n\\n    # Graph execution below can run for minutes; end any request transaction\\n    # opened by dependency resolution so it does not pin a pooled connection\\n    # (Postgres: idle-in-transaction) for the whole run (#14445).\\n    await release_db_transaction(session)\\n\\n    try:\\n        with (\\n            scoped_model_provider_policy_for_flow(\\n                flow,\\n                user_id=api_key_user.id,\\n                is_superuser=bool(getattr(api_key_user, \\\"is_superuser\\\", False)),\\n            ),\\n            execution_protocol(\\\"v1.advanced\\\"),\\n        ):\\n            task_result, session_id = await run_graph_internal(\\n                graph=graph,\\n                flow_id=flow_id_str,\\n                session_id=session_id,\\n                inputs=inputs,\\n                outputs=outputs,\\n                stream=stream,\\n            )\\n    except TweakRefusedError:\\n        # Let the app-level handler return the documented structured 422.\\n        raise\\n    except Exception as exc:\\n        await logger.aexception(\\\"Advanced-run execution failed for flow %s\\\", flow.id)\\n        if isinstance(exc, HTTPException):\\n            if expose_error_details:\\n                raise\\n            raise error_for_client(exc, expose_details=expose_error_details) from exc\\n        client_error = error_for_client(exc, expose_details=expose_error_details)\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=str(client_error)) from exc\\n\\n    # Memory-base auto-capture is owner-scoped; shared callers must not spend or\\n    # persist through the flow owner's private credentials.\\n    if _caller_owns_flow(flow, api_key_user):\\n        try:\\n            _run_id_uuid = UUID(graph.run_id) if graph.run_id else None  # type-cast only\\n            await get_task_service().fire_and_forget_task(\\n                get_memory_base_service().on_flow_output,\\n                flow_id=flow.id,\\n                session_id=session_id,\\n                job_id=_run_id_uuid,\\n            )\\n        except (RuntimeError, ValueError, OSError):\\n            await logger.awarning(\\\"Memory base hook scheduling failed for flow %s\\\", flow.id, exc_info=True)\\n\\n    return _v1_run_response(RunResponse(outputs=task_result, session_id=session_id))\\n\\n\\n@router.post(\\n    \\\"/predict/{_flow_id}\\\",\\n    dependencies=[Depends(api_key_security)],\\n    include_in_schema=False,\\n)\\n@router.post(\\n    \\\"/process/{_flow_id}\\\",\\n    dependencies=[Depends(api_key_security)],\\n    include_in_schema=False,\\n)\\nasync def process(_flow_id) -> None:\\n    \\\"\\\"\\\"Endpoint to process an input with a given flow_id.\\\"\\\"\\\"\\n    # Raise a depreciation warning\\n    await logger.awarning(\\n        \\\"The /process endpoint is deprecated and will be removed in a future version. Please use /run instead.\\\"\\n    )\\n    raise HTTPException(\\n        status_code=status.HTTP_400_BAD_REQUEST,\\n        detail=\\\"The /process endpoint is deprecated and will be removed in a future version. Please use /run instead.\\\",\\n    )\\n\\n\\n@router.get(\\\"/task/{_task_id}\\\", deprecated=True, include_in_schema=False)\\nasync def get_task_status(_task_id: str) -> TaskStatusResponse:\\n    \\\"\\\"\\\"Get the status of a task by ID (Deprecated).\\n\\n    This endpoint is deprecated and will be removed in a future version.\\n    \\\"\\\"\\\"\\n    raise HTTPException(\\n        status_code=status.HTTP_400_BAD_REQUEST,\\n        detail=\\\"The /task endpoint is deprecated and will be removed in a future version. Please use /run instead.\\\",\\n    )\\n\\n\\n@router.post(\\n    \\\"/upload/{flow_id}\\\",\\n    status_code=HTTPStatus.CREATED,\\n    deprecated=True,\\n    include_in_schema=False,\\n)\\nasync def create_upload_file(\\n    file: UploadFile,\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    current_user: CurrentActiveUser,\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n) -> UploadFileResponse:\\n    \\\"\\\"\\\"Upload a file for a specific flow (Deprecated).\\n\\n    This endpoint is deprecated and will be removed in a future version.\\n    Authorization is handled by the ``get_flow`` dependency, which requires an\\n    authenticated user and verifies flow ownership.  Mirrors the\\n    ``max_file_size_upload`` guard on the non-deprecated twin at\\n    ``/api/v1/files/upload/{flow_id}`` so authenticated callers can't fill\\n    disk through this route either.\\n    \\\"\\\"\\\"\\n    # Writing a file to a flow's storage is a flow mutation: enforce WRITE so\\n    # the external access ceiling (e.g. a \\\"viewer\\\") cannot upload via this\\n    # deprecated route. Mirrors the non-deprecated twin in files.py.\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.WRITE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n    try:\\n        max_file_size_upload = settings_service.settings.max_file_size_upload\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n    if file.size is not None and file.size > max_file_size_upload * 1024 * 1024:\\n        raise HTTPException(\\n            status_code=413,\\n            detail=f\\\"File size is larger than the maximum file size {max_file_size_upload}MB.\\\",\\n        )\\n\\n    try:\\n        flow_id_str = str(flow.id)\\n        file_path = await asyncio.to_thread(save_uploaded_file, file, folder_name=flow_id_str)\\n\\n        return UploadFileResponse(\\n            flow_id=flow_id_str,\\n            file_path=file_path.as_posix(),\\n        )\\n    except Exception as exc:\\n        await logger.aexception(\\\"Error saving file\\\")\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\n# get endpoint to return version of langflow\\n@router.get(\\\"/version\\\")\\nasync def get_version():\\n    return get_version_info()\\n\\n\\ndef _raw_component_parameters(\\n    template: Mapping[str, Any] | None,\\n    *,\\n    field: str | None = None,\\n    field_value: Any = None,\\n) -> dict[str, Any]:\\n    \\\"\\\"\\\"Parse non-secret component form values for provider preflight.\\\"\\\"\\\"\\n    params: dict[str, Any] = {}\\n    if isinstance(template, Mapping):\\n        for key, value_dict in template.items():\\n            if isinstance(value_dict, Mapping):\\n                params[key] = parse_value(value_dict.get(\\\"value\\\"), str(value_dict.get(\\\"_input_type\\\")))\\n\\n    # A real-time-refresh event can be newer than the template snapshot sent\\n    # beside it, so its value wins for the changed field.\\n    if field:\\n        field_template = template.get(field) if isinstance(template, Mapping) else None\\n        field_input_type = str(field_template.get(\\\"_input_type\\\")) if isinstance(field_template, Mapping) else \\\"None\\\"\\n        params[field] = parse_value(field_value, field_input_type)\\n    return params\\n\\n\\n@router.post(\\\"/custom_component\\\", status_code=HTTPStatus.OK, include_in_schema=False)\\nasync def custom_component(\\n    raw_code: CustomComponentRequest,\\n    user: CurrentActiveUser,\\n    request: Request,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n) -> CustomComponentResponse:\\n    # Building a custom component instantiates (and partially executes) posted\\n    # code. That is a create/write-class action, so enforce the external access\\n    # ceiling directly: a \\\"viewer\\\" external identity is denied while\\n    # editor/admin (and all non-external users) pass unchanged. This route is\\n    # not tied to a single owned resource, so the deny-only primitive is used\\n    # instead of an ``ensure_*_permission`` guard.\\n    external_context = get_current_external_access_context()\\n    if external_context is not None and not external_access_allows(\\\"create\\\", external_context):\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"External credentials do not allow this action\\\",\\n        )\\n\\n    settings_service = get_settings_service()\\n    settings = settings_service.settings\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n    effective_code = resolve_component_code_for_action(\\n        raw_code.code,\\n        user=user,\\n        settings=settings,\\n        snapshot=catalog_policy_snapshot,\\n        disabled_detail=\\\"Custom component creation is disabled\\\",\\n        admin_only_detail=\\\"Custom component creation is restricted to administrators\\\",\\n    )\\n\\n    policy_context_token = set_current_model_provider_policy_context(\\n        user_id=user.id,\\n        attributes=provider_policy_attributes,\\n    )\\n    try:\\n        component = Component(_code=effective_code)\\n\\n        built_frontend_node, component_instance = build_custom_component_template(component, user_id=user.id)\\n        type_ = get_instance_name(component_instance)\\n        enforce_catalog_policy_for_component_type(type_, snapshot=catalog_policy_snapshot)\\n        if isinstance(component_instance, Component):\\n            # Dynamic configuration may resolve DB-backed credentials or call\\n            # provider APIs. Refresh the active hierarchy before either hook\\n            # runs so moved-project and newly inherited grants are current.\\n            current_template = (\\n                raw_code.frontend_node.get(\\\"template\\\") if isinstance(raw_code.frontend_node, Mapping) else None\\n            )\\n            await component_instance.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.CONFIGURE,\\n                user_id=user.id,\\n                parameters=_raw_component_parameters(current_template),\\n            )\\n        if raw_code.frontend_node is not None:\\n            built_frontend_node = await component_instance.update_frontend_node(\\n                built_frontend_node,\\n                raw_code.frontend_node,\\n            )\\n\\n        tool_mode: bool = built_frontend_node.get(\\\"tool_mode\\\", False)\\n        if isinstance(component_instance, Component):\\n            await component_instance.run_and_validate_update_outputs(\\n                frontend_node=built_frontend_node,\\n                field_name=\\\"tool_mode\\\",\\n                field_value=tool_mode,\\n            )\\n    except ModelProviderPolicyError as exc:\\n        # Keep scoped denials indistinguishable from unavailable providers and\\n        # avoid surfacing an authorization decision as a retryable server error.\\n        raise HTTPException(status_code=404, detail=\\\"Model provider not found\\\") from exc\\n    finally:\\n        reset_current_model_provider_policy_context(policy_context_token)\\n    locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n    if locale != \\\"en\\\":\\n        from langflow.utils.i18n import translate_component_node\\n\\n        try:\\n            built_frontend_node = translate_component_node(type_, built_frontend_node, locale)\\n        except Exception:  # noqa: BLE001\\n            logger.exception(\\\"Failed to translate component node\\\", extra={\\\"locale\\\": locale})\\n    return CustomComponentResponse(data=built_frontend_node, type=type_)\\n\\n\\n@router.post(\\\"/custom_component/update\\\", status_code=HTTPStatus.OK, include_in_schema=False)\\nasync def custom_component_update(\\n    code_request: UpdateCustomComponentRequest,\\n    user: CurrentActiveUser,\\n    request: Request,\\n    provider_policy_attributes: ProviderPolicyAttributesDependency,\\n):\\n    \\\"\\\"\\\"Update an existing custom component with new code and configuration.\\n\\n    Processes the provided code and template updates, applies parameter changes (including those loaded from the\\n    database), updates the component's build configuration, and validates outputs. Returns the updated component node as\\n    a JSON-serializable dictionary.\\n\\n    Raises:\\n        HTTPException: If an error occurs during component building or updating.\\n        SerializationError: If serialization of the updated component node fails.\\n    \\\"\\\"\\\"\\n    # Updating a custom component instantiates (and partially executes) posted\\n    # code, a create/write-class action. Enforce the external access ceiling\\n    # directly so a \\\"viewer\\\" external identity is denied; editor/admin (and all\\n    # non-external users) pass unchanged. Same action string as ``custom_component``.\\n    external_context = get_current_external_access_context()\\n    if external_context is not None and not external_access_allows(\\\"create\\\", external_context):\\n        raise HTTPException(\\n            status_code=status.HTTP_403_FORBIDDEN,\\n            detail=\\\"External credentials do not allow this action\\\",\\n        )\\n\\n    settings_service = get_settings_service()\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n    effective_code = resolve_component_code_for_action(\\n        code_request.code,\\n        user=user,\\n        settings=settings_service.settings,\\n        snapshot=catalog_policy_snapshot,\\n        disabled_detail=\\\"Custom component creation is disabled\\\",\\n        admin_only_detail=\\\"Custom component editing is restricted to administrators\\\",\\n    )\\n\\n    policy_context_token = set_current_model_provider_policy_context(\\n        user_id=user.id,\\n        attributes=provider_policy_attributes,\\n    )\\n    try:\\n        component = Component(_code=effective_code)\\n        component_node, cc_instance = build_custom_component_template(\\n            component,\\n            user_id=user.id,\\n        )\\n        component_type = get_instance_name(cc_instance)\\n        enforce_catalog_policy_for_component_type(component_type, snapshot=catalog_policy_snapshot)\\n\\n        template = code_request.get_template()\\n        params = _raw_component_parameters(template)\\n        policy_params = _raw_component_parameters(\\n            template,\\n            field=code_request.field,\\n            field_value=code_request.field_value,\\n        )\\n\\n        if isinstance(cc_instance, Component):\\n            # Authorize both fixed-provider components and the raw selected\\n            # ModelInput provider before load_from_db can hydrate any secret.\\n            await cc_instance.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.CONFIGURE,\\n                user_id=user.id,\\n                parameters=policy_params,\\n            )\\n\\n        component_node[\\\"tool_mode\\\"] = code_request.tool_mode\\n\\n        if hasattr(cc_instance, \\\"set_attributes\\\"):\\n            load_from_db_fields = [\\n                field_name\\n                for field_name, field_dict in template.items()\\n                if isinstance(field_dict, dict) and field_dict.get(\\\"load_from_db\\\") and field_dict.get(\\\"value\\\")\\n            ]\\n            if isinstance(cc_instance, Component):\\n                # ``fallback_to_env_vars=True`` so a missing variable (e.g. an\\n                # imported flow referencing ``ANTHROPIC_API_KEY`` when the\\n                # current user hasn't configured one) degrades to ``None``\\n                # instead of raising.  This endpoint only refreshes form\\n                # metadata \u2014 it does not execute the component \u2014 so we don't\\n                # need the real credential here.  The runtime build path still\\n                # calls ``update_params_with_load_from_db_fields`` with its own\\n                # fallback setting, so this change doesn't relax execution-time\\n                # requirements.\\n                params = await update_params_with_load_from_db_fields(\\n                    cc_instance,\\n                    params,\\n                    load_from_db_fields,\\n                    fallback_to_env_vars=True,\\n                )\\n                cc_instance.set_attributes(params)\\n        updated_build_config = code_request.get_template()\\n        await update_component_build_config(\\n            cc_instance,\\n            build_config=updated_build_config,\\n            field_value=code_request.field_value,\\n            field_name=code_request.field,\\n        )\\n        if \\\"code\\\" not in updated_build_config or not updated_build_config.get(\\\"code\\\", {}).get(\\\"value\\\"):\\n            updated_build_config = add_code_field_to_build_config(updated_build_config, effective_code)\\n        else:\\n            # Never echo client bytes back in restricted mode. A colliding\\n            # payload may have cleared the truncated-hash gate, but the server\\n            # executed its trusted copy (``effective_code``); the returned node\\n            # must carry that trusted code too, otherwise the attacker bytes\\n            # could be persisted into a saved flow and later exec'd on the\\n            # build path. In the default (unrestricted) mode ``effective_code``\\n            # is ``code_request.code``, so this is a no-op.\\n            updated_build_config[\\\"code\\\"][\\\"value\\\"] = effective_code\\n        component_node[\\\"template\\\"] = updated_build_config\\n\\n        if isinstance(cc_instance, Component):\\n            await cc_instance.run_and_validate_update_outputs(\\n                frontend_node=component_node,\\n                field_name=code_request.field,\\n                field_value=code_request.field_value,\\n            )\\n\\n    except CatalogPolicyHTTPException:\\n        raise\\n    except ModelProviderPolicyError as exc:\\n        raise HTTPException(status_code=404, detail=\\\"Model provider not found\\\") from exc\\n    except Exception as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    finally:\\n        reset_current_model_provider_policy_context(policy_context_token)\\n\\n    locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n    if locale != \\\"en\\\":\\n        from langflow.utils.i18n import translate_component_node\\n\\n        try:\\n            component_node = translate_component_node(component_type, component_node, locale)\\n        except Exception:  # noqa: BLE001\\n            logger.exception(\\\"Failed to translate component node\\\", extra={\\\"locale\\\": locale})\\n\\n    try:\\n        return jsonable_encoder(component_node)\\n    except Exception as exc:\\n        raise SerializationError.from_exception(exc, data=component_node) from exc\\n\\n\\ndef _blocked_component_types(snapshot) -> list[str]:\\n    \\\"\\\"\\\"Return every component type the editor should treat as policy-blocked.\\n\\n    The editor compares a node's ``type`` against this set, and a saved node\\n    carries whichever identity it was saved under -- ``Prompt`` rather than the\\n    registry key ``Prompt Template``. Alias resolution only runs one way, so\\n    reporting the administrator's key and its canonical candidates is not\\n    enough: blocking the canonical key would leave every node saved under an\\n    alias unmatched, and the palette exposes only the canonical key, so that is\\n    the one an administrator can find.\\n\\n    ``_resolve_catalog_policy_matches`` decides the write by resolving the node\\n    side too and intersecting, so the same rule is applied here in reverse:\\n    every alias whose canonical candidates meet the blocked identities is\\n    reported. That keeps this answer identical to the one that decides whether\\n    the save succeeds, which is the whole point of sending it.\\n    \\\"\\\"\\\"\\n    blocked_keys = getattr(snapshot, \\\"blocked_component_keys\\\", None)\\n    if not blocked_keys:\\n        return []\\n\\n    types = set(blocked_keys)\\n    try:\\n        from lfx.utils.flow_validation import get_component_identity_index_for_validation\\n\\n        identity_index = get_component_identity_index_for_validation()\\n    except Exception:  # noqa: BLE001\\n        identity_index = None\\n    if identity_index is not None:\\n        blocked_identities = frozenset(identity_index.resolve_many(blocked_keys))\\n        types |= blocked_identities\\n        types |= {\\n            alias\\n            for alias, candidates in identity_index.aliases.items()\\n            # Any overlap blocks the node server side, including an alias that\\n            # is ambiguous across components.\\n            if not blocked_identities.isdisjoint(candidates)\\n        }\\n    return sorted(types)\\n\\n\\n@router.get(\\\"/config\\\")\\nasync def get_config(\\n    user: Annotated[User | None, Depends(get_optional_user)] = None,\\n) -> ConfigResponse | PublicConfigResponse:\\n    \\\"\\\"\\\"Retrieve application configuration settings.\\n\\n    Returns different configuration based on authentication status:\\n    - Authenticated users: Full ConfigResponse with all settings\\n    - Unauthenticated users: PublicConfigResponse with limited, safe-to-expose settings\\n\\n    Args:\\n        user: The authenticated user, or None if unauthenticated.\\n\\n    Returns:\\n        ConfigResponse | PublicConfigResponse: Configuration settings appropriate for the user's auth status.\\n\\n    Raises:\\n        HTTPException: If an error occurs while retrieving the configuration.\\n    \\\"\\\"\\\"\\n    try:\\n        settings_service: SettingsService = get_settings_service()\\n        blocked_component_types: list[str] = []\\n        try:\\n            catalog_policy_service = get_catalog_policy_service()\\n            catalog_governance_enabled = catalog_policy_service.enabled\\n            # A custom policy service need not expose a snapshot. Reporting no\\n            # identities then simply leaves the editor unable to name a cause,\\n            # which is the safe direction.\\n            blocked_component_types = _blocked_component_types(getattr(catalog_policy_service, \\\"snapshot\\\", None))\\n        except Exception as exc:  # noqa: BLE001\\n            # Catalog governance is explicitly fail-open. A broken custom\\n            # policy implementation must not break the public config endpoint\\n            # or expose its internal exception text.\\n            await logger.aexception(\\\"Catalog policy status unavailable; reporting governance disabled\\\", exception=exc)\\n            catalog_governance_enabled = False\\n            blocked_component_types = []\\n\\n        if user is None:\\n            return PublicConfigResponse.from_settings(\\n                settings_service.settings,\\n                settings_service.auth_settings,\\n                catalog_governance_enabled=catalog_governance_enabled,\\n            )\\n\\n        return ConfigResponse.from_settings(\\n            settings_service.settings,\\n            settings_service.auth_settings,\\n            catalog_governance_enabled=catalog_governance_enabled,\\n            blocked_component_types=blocked_component_types,\\n        )\\n\\n    except Exception as exc:\\n        raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/extensions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7322bf290e46630c6b38617793a578aa01be74ff8a9b60a82f48d91f66e6c5a4\",\"content\":\"\\\"\\\"\\\"Extension System HTTP surface: reload.\\n\\nCurrently exposes a single endpoint, ``POST /extensions/{extension_id}/bundles/{bundle_name}/reload``,\\nwhich drives the atomic-swap reload pipeline against the process-default\\n:class:`~lfx.extension.bundle_registry.BundleRegistry`.\\n\\nFuture list / status / migrate endpoints will live alongside this one.\\nMode A only -- in Mode B/C the path is to rebuild the Docker image, and\\nthe runtime guard at the request layer short-circuits with 404 when\\n``LANGFLOW_ENABLE_EXTENSION_RELOAD`` is off.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom typing import Annotated\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query, status\\nfrom lfx.extension.bundle_registry import get_default_registry\\nfrom lfx.extension.errors import ExtensionError\\nfrom lfx.extension.reload import ReloadInProgressError, reload_bundle\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_extension_events_service, get_settings_service\\nfrom pydantic import BaseModel\\n\\nfrom langflow.api.utils.core import CurrentActiveUser\\n\\nrouter = APIRouter(prefix=\\\"/extensions\\\", tags=[\\\"Extensions\\\"])\\n\\n\\nclass ExtensionEventResponse(BaseModel):\\n    type: str\\n    timestamp: float\\n    payload: dict\\n\\n\\nclass ExtensionEventsResponse(BaseModel):\\n    events: list[ExtensionEventResponse]\\n    settled: bool\\n\\n\\ndef _typed_http_exception(*, status_code: int, error: ExtensionError) -> HTTPException:\\n    \\\"\\\"\\\"Wrap an :class:`ExtensionError` in a FastAPI HTTPException.\\n\\n    The ``detail`` body is the full ``{code, message, location, content,\\n    hint, ref_url}`` envelope, matching the typed-error contract documented\\n    in the extensions error guide.  Returning anything narrower here would\\n    drop the fix hint and the docs link from the client surface, which the\\n    palette + CLI consumers depend on.\\n    \\\"\\\"\\\"\\n    return HTTPException(status_code=status_code, detail=error.to_dict())\\n\\n\\ndef _require_extension_reload_enabled() -> None:\\n    \\\"\\\"\\\"Per-request guard for the Mode A reload route.\\n\\n    The route is always mounted (see ``langflow.api.router``) so that\\n    ``--env-file`` can opt in to it without forcing route registration\\n    to happen after the env file is loaded.  Operators on Mode B/C\\n    deployments leave ``LANGFLOW_ENABLE_EXTENSION_RELOAD`` unset; the\\n    guard returns 404 so the route is indistinguishable from \\\"not\\n    mounted\\\" for those operators, with the typed error body so the\\n    client renders the same envelope shape it does for any other\\n    reload error.\\n    \\\"\\\"\\\"\\n    settings = get_settings_service().settings\\n    if not getattr(settings, \\\"enable_extension_reload\\\", False):\\n        raise _typed_http_exception(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            error=ExtensionError(\\n                code=\\\"extension-reload-disabled\\\",\\n                message=(\\n                    \\\"Extension reload is disabled on this server.  \\\"\\n                    \\\"Set LANGFLOW_ENABLE_EXTENSION_RELOAD=true to enable it on \\\"\\n                    \\\"a local-development install (Mode A).\\\"\\n                ),\\n                hint=(\\n                    \\\"Local development: ``lfx extension dev`` sets the flag \\\"\\n                    \\\"for you.  Self-hosted: export LANGFLOW_ENABLE_EXTENSION_RELOAD=true \\\"\\n                    \\\"or include it in your --env-file.\\\"\\n                ),\\n            ),\\n        )\\n\\n\\n@router.post(\\n    \\\"/{extension_id}/bundles/{bundle_name}/reload\\\",\\n    status_code=status.HTTP_200_OK,\\n    dependencies=[\\n        Depends(_require_extension_reload_enabled),\\n    ],\\n)\\nasync def reload_extension_bundle(\\n    extension_id: str,\\n    bundle_name: str,\\n    current_user: CurrentActiveUser,\\n) -> dict:\\n    \\\"\\\"\\\"Trigger an atomic-swap reload for a single Bundle.\\n\\n    Returns the typed :class:`~lfx.extension.reload.ReloadResult` body on\\n    success.  Per the typed-error contract, structural failures\\n    (broken bundle, missing source path, name mismatch) surface as\\n    ``422 Unprocessable Entity`` with the first typed error in the body\\n    so clients can surface fix hints inline; the full ``ReloadResult``\\n    payload (with all errors and warnings) is returned via the FastAPI\\n    ``detail`` envelope.  Concurrency-control collisions surface as\\n    ``409 Conflict`` (``reload-in-progress``).  Non-2xx is the wire\\n    contract for every error path -- the body still carries the typed\\n    error so the client renders the same fix-hint envelope.\\n    \\\"\\\"\\\"\\n    registry = get_default_registry()\\n    record = registry.get_bundle(bundle_name)\\n    if record is not None and record.extension_id != extension_id:\\n        # Bundle name is registered but under a different extension -- treat as\\n        # a 404 so a typo in the URL doesn't mutate someone else's bundle.\\n        raise _typed_http_exception(\\n            status_code=status.HTTP_404_NOT_FOUND,\\n            error=ExtensionError(\\n                code=\\\"reload-bundle-not-installed\\\",\\n                message=(\\n                    f\\\"Bundle {bundle_name!r} is registered to extension {record.extension_id!r}, not {extension_id!r}.\\\"\\n                ),\\n                location=f\\\"{extension_id}/{bundle_name}\\\",\\n                content=bundle_name,\\n                hint=(\\n                    \\\"Use the bundle's actual extension id (typically the pip \\\"\\n                    \\\"distribution name); run ``lfx extension list`` to see the \\\"\\n                    \\\"registered (extension, bundle) pairs.\\\"\\n                ),\\n            ),\\n        )\\n\\n    try:\\n        # reload_bundle is synchronous and does substantial blocking work\\n        # (disk I/O, importlib execution of arbitrary extension code, file\\n        # hashing, RLock acquisition).  Run it off the event loop so a slow\\n        # or large bundle import does not freeze the worker for every other\\n        # in-flight request.  ``asyncio.to_thread`` propagates the result\\n        # and any exception (including ReloadInProgressError) back to us.\\n        result = await asyncio.to_thread(\\n            reload_bundle,\\n            registry,\\n            bundle_name,\\n            user_id=str(current_user.id),\\n        )\\n    except ReloadInProgressError as exc:\\n        # 409 is the conventional \\\"in-progress / conflicting state\\\" code.\\n        logger.info(\\\"extension reload-in-progress collision for %s\\\", exc.bundle)\\n        raise _typed_http_exception(\\n            status_code=status.HTTP_409_CONFLICT,\\n            error=ExtensionError(\\n                code=\\\"reload-in-progress\\\",\\n                message=str(exc),\\n                location=exc.bundle,\\n                content=exc.bundle,\\n                hint=(\\n                    \\\"Wait for the in-flight reload to finish before retrying; \\\"\\n                    \\\"another tab or worker is already swapping this bundle.\\\"\\n                ),\\n            ),\\n        ) from exc\\n\\n    if not result.ok:\\n        # Structural failure: surface as 422 with the first typed error so\\n        # the body shape matches every other typed-error response in this\\n        # router.  The full ReloadResult body (including additional errors\\n        # and warnings) is preserved under the HTTPException ``detail``.\\n        primary = (\\n            result.errors[0]\\n            if result.errors\\n            else ExtensionError(\\n                code=\\\"reload-failed\\\",\\n                message=f\\\"Reload failed for bundle {bundle_name!r}.\\\",\\n                location=f\\\"{extension_id}/{bundle_name}\\\",\\n                hint=\\\"Run `lfx extension validate` against the bundle source for details.\\\",\\n            )\\n        )\\n        logger.warning(\\n            \\\"extension reload failed: bundle=%s code=%s\\\",\\n            bundle_name,\\n            primary.code,\\n        )\\n        raise HTTPException(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            detail={\\n                **primary.to_dict(),\\n                \\\"result\\\": result.to_dict(),\\n            },\\n        )\\n\\n    return result.to_dict()\\n\\n\\n@router.get(\\n    \\\"/events\\\",\\n    response_model=ExtensionEventsResponse,\\n)\\nasync def get_extension_events(\\n    current_user: CurrentActiveUser,\\n    since: Annotated[float, Query(description=\\\"UTC epoch timestamp; return events after this cursor\\\")] = 0.0,\\n    keyspace: Annotated[\\n        str | None,\\n        Query(\\n            description=(\\n                \\\"Reserved. Events are scoped server-side to the authenticated user; \\\"\\n                \\\"passing this parameter is rejected with 422.\\\"\\n            ),\\n            include_in_schema=False,\\n        ),\\n    ] = None,\\n) -> ExtensionEventsResponse:\\n    \\\"\\\"\\\"Poll for extension lifecycle events the current user has triggered.\\n\\n    Events are scoped to the authenticated user via a server-derived keyspace\\n    (``user:{user_id}``); there is no client-controllable keyspace, so an\\n    authenticated user cannot read another user's flow-migration or\\n    bundle-reload events. A client-supplied ``keyspace`` query parameter is\\n    rejected with 422 so the contract is explicit -- previously the value was\\n    silently dropped, which masked client bugs that assumed it had effect.\\n\\n    svc.since() uses blocking sqlite3; run in a thread pool so the asyncio\\n    event loop is not held while waiting on disk I/O.\\n    \\\"\\\"\\\"\\n    if keyspace is not None:\\n        raise _typed_http_exception(\\n            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n            error=ExtensionError(\\n                code=\\\"extension-events-keyspace-forbidden\\\",\\n                message=(\\n                    \\\"The 'keyspace' query parameter is not accepted on /extensions/events; \\\"\\n                    \\\"events are scoped to the authenticated user automatically.\\\"\\n                ),\\n                location=\\\"query.keyspace\\\",\\n                content=keyspace,\\n                hint=(\\n                    \\\"Remove the 'keyspace' query parameter from the request; the server \\\"\\n                    \\\"derives the keyspace from the authenticated user.\\\"\\n                ),\\n            ),\\n        )\\n    svc = get_extension_events_service()\\n    if svc is None:\\n        return ExtensionEventsResponse(events=[], settled=True)\\n    keyspace = f\\\"user:{current_user.id}\\\"\\n    events, settled = await asyncio.to_thread(svc.since, since, keyspace)\\n    return ExtensionEventsResponse(\\n        events=[ExtensionEventResponse(type=e.type, timestamp=e.timestamp, payload=e.payload) for e in events],\\n        settled=settled,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/files.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a484cba0b0f677c452d6c0880814346eb991cea168f9ee420a822f1f76ff9e3\",\"content\":\"import hashlib\\nimport os\\nfrom datetime import datetime, timezone\\nfrom http import HTTPStatus\\nfrom io import BytesIO\\nfrom pathlib import Path\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nimport anyio\\nfrom fastapi import APIRouter, Depends, HTTPException, UploadFile\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.services.settings.service import SettingsService\\nfrom lfx.utils.helpers import build_content_type_from_extension\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    ValidatedFileName,\\n    ValidatedFolderName,\\n    build_content_disposition,\\n)\\nfrom langflow.api.v1.schemas import UploadFileResponse\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.deps import get_settings_service, get_storage_service\\nfrom langflow.services.storage.service import StorageService\\n\\nrouter = APIRouter(tags=[\\\"Files\\\"], prefix=\\\"/files\\\")\\n\\n\\ndef _get_allowed_profile_picture_folders(settings_service: SettingsService) -> set[str]:\\n    \\\"\\\"\\\"Return the set of allowed profile picture folders.\\n\\n    This enumerates subdirectories under the profile_pictures directory in both\\n    the user's config_dir and the package's bundled assets. This makes the API\\n    flexible (users may add new folders under config_dir/profile_pictures) while\\n    still safe because we only ever serve files contained within the resolved\\n    base directory and validate path containment below.\\n\\n    If no directories can be found (unexpected), fall back to the curated\\n    defaults {\\\"People\\\", \\\"Space\\\"} shipped with Langflow.\\n    \\\"\\\"\\\"\\n    allowed: set[str] = set()\\n    try:\\n        # Config-provided folders\\n        config_dir = Path(settings_service.settings.config_dir)\\n        cfg_base = config_dir / \\\"profile_pictures\\\"\\n        if cfg_base.exists():\\n            allowed.update({p.name for p in cfg_base.iterdir() if p.is_dir()})\\n        # Package-provided folders\\n        from langflow.initial_setup import setup\\n\\n        pkg_base = Path(setup.__file__).parent / \\\"profile_pictures\\\"\\n        if pkg_base.exists():\\n            allowed.update({p.name for p in pkg_base.iterdir() if p.is_dir()})\\n    except Exception as _:\\n        import logging\\n\\n        logger = logging.getLogger(__name__)\\n        logger.exception(\\\"Exception occurred while getting allowed profile picture folders\\\")\\n\\n    # Sensible defaults ensure tests and OOTB behavior\\n    return allowed or {\\\"People\\\", \\\"Space\\\"}\\n\\n\\n# Create dep that gets the flow_id from the request\\n# then finds it in the database and returns it while\\n# using the current user as the owner\\nasync def get_flow(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n):\\n    # AttributeError: 'SelectOfScalar' object has no attribute 'first'\\n    flow = await session.get(Flow, flow_id)\\n    # Return 404 for both non-existent flows and unauthorized access to prevent information disclosure\\n    if not flow or flow.user_id != current_user.id:\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n    return flow\\n\\n\\n@router.post(\\\"/upload/{flow_id}\\\", status_code=HTTPStatus.CREATED)\\nasync def upload_file(\\n    *,\\n    file: UploadFile,\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    current_user: CurrentActiveUser,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n) -> UploadFileResponse:\\n    # Writing a file to a flow's storage is a flow mutation: enforce WRITE so\\n    # the external access ceiling (e.g. a \\\"viewer\\\") cannot upload via this route.\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.WRITE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n    try:\\n        max_file_size_upload = settings_service.settings.max_file_size_upload\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if file.size > max_file_size_upload * 1024 * 1024:\\n        raise HTTPException(\\n            status_code=413, detail=f\\\"File size is larger than the maximum file size {max_file_size_upload}MB.\\\"\\n        )\\n\\n    # Authorization handled by get_flow dependency\\n    try:\\n        file_content = await file.read()\\n        timestamp = datetime.now(tz=timezone.utc).astimezone().strftime(\\\"%Y-%m-%d_%H-%M-%S\\\")\\n        file_name = file.filename or hashlib.sha256(file_content).hexdigest()\\n        full_file_name = f\\\"{timestamp}_{file_name}\\\"\\n        folder = str(flow.id)\\n        await storage_service.save_file(flow_id=folder, file_name=full_file_name, data=file_content)\\n        return UploadFileResponse(flow_id=str(flow.id), file_path=f\\\"{folder}/{full_file_name}\\\")\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/download/{flow_id}/{file_name}\\\")\\nasync def download_file(\\n    file_name: ValidatedFileName,\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    # Authorization handled by get_flow dependency\\n    flow_id_str = str(flow.id)\\n    extension = file_name.split(\\\".\\\")[-1]\\n\\n    if not extension:\\n        raise HTTPException(status_code=500, detail=f\\\"Extension not found for file {file_name}\\\")\\n    try:\\n        content_type = build_content_type_from_extension(extension)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if not content_type:\\n        raise HTTPException(status_code=500, detail=f\\\"Content type not found for extension {extension}\\\")\\n\\n    try:\\n        file_content = await storage_service.get_file(flow_id=flow_id_str, file_name=file_name)\\n        headers = {\\n            \\\"Content-Disposition\\\": build_content_disposition(file_name),\\n            \\\"Content-Type\\\": \\\"application/octet-stream\\\",\\n            \\\"Content-Length\\\": str(len(file_content)),\\n        }\\n        return StreamingResponse(BytesIO(file_content), media_type=content_type, headers=headers)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/images/{flow_id}/{file_name}\\\")\\nasync def download_image(\\n    file_name: ValidatedFileName,\\n    # Security: resolve flow through get_flow so image access requires authentication and owner match.\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Download image from storage for browser rendering.\\\"\\\"\\\"\\n    extension = file_name.split(\\\".\\\")[-1]\\n    flow_id_str = str(flow.id)\\n\\n    if not extension:\\n        raise HTTPException(status_code=500, detail=f\\\"Extension not found for file {file_name}\\\")\\n    try:\\n        content_type = build_content_type_from_extension(extension)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    if not content_type:\\n        raise HTTPException(status_code=500, detail=f\\\"Content type not found for extension {extension}\\\")\\n    if not content_type.startswith(\\\"image\\\"):\\n        raise HTTPException(status_code=500, detail=f\\\"Content type {content_type} is not an image\\\")\\n\\n    try:\\n        file_content = await storage_service.get_file(flow_id=flow_id_str, file_name=file_name)\\n        # Defense-in-depth: a tenant-uploaded SVG/HTML served inline with a renderable content type\\n        # would execute scripts in the app origin if opened directly. nosniff stops MIME sniffing\\n        # and Content-Disposition: attachment forces a download on direct navigation (so any script\\n        # cannot run in-origin). <img>/blob embedding -- the intended use -- is unaffected.\\n        return StreamingResponse(\\n            BytesIO(file_content),\\n            media_type=content_type,\\n            headers={\\\"X-Content-Type-Options\\\": \\\"nosniff\\\", \\\"Content-Disposition\\\": \\\"attachment\\\"},\\n        )\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/profile_pictures/{folder_name}/{file_name}\\\")\\nasync def download_profile_picture(\\n    folder_name: ValidatedFolderName,\\n    file_name: ValidatedFileName,\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    \\\"\\\"\\\"Download profile picture from local filesystem.\\n\\n    Profile pictures are first looked up in config_dir/profile_pictures/,\\n    then fallback to the package's bundled profile_pictures directory.\\n    \\\"\\\"\\\"\\n    try:\\n        # Only allow specific folder names (dynamic from config + package)\\n        allowed_folders = _get_allowed_profile_picture_folders(settings_service)\\n        if folder_name not in allowed_folders:\\n            raise HTTPException(status_code=400, detail=f\\\"Folder must be one of: {', '.join(sorted(allowed_folders))}\\\")\\n\\n        # SECURITY: Extract only the final path component to prevent path traversal.\\n        # This is defense-in-depth on top of ValidatedFileName/ValidatedFolderName.\\n        safe_folder = Path(folder_name).name\\n        safe_file = Path(file_name).name\\n\\n        extension = safe_file.split(\\\".\\\")[-1]\\n        config_dir = settings_service.settings.config_dir\\n\\n        # SECURITY: use os.path.realpath + startswith \u2014 the sanitiser pattern\\n        # recognised by CodeQL's py/path-injection analysis. realpath canonicalises\\n        # the path and resolves symlinks, so the subsequent startswith check is\\n        # robust against both traversal sequences and symlink-based escapes.\\n        # os.path.join is deliberate here (PTH118) to match CodeQL's sanitiser model.\\n        allowed_base = os.path.realpath(os.path.join(str(config_dir), \\\"profile_pictures\\\"))  # noqa: PTH118\\n        candidate = os.path.realpath(os.path.join(allowed_base, safe_folder, safe_file))  # noqa: PTH118\\n        if candidate != allowed_base and not candidate.startswith(allowed_base + os.sep):\\n            raise HTTPException(status_code=404, detail=\\\"Profile picture not found\\\")\\n        file_path = Path(candidate)\\n\\n        # Fallback to package bundled profile pictures if not found in config_dir\\n        if not file_path.exists():\\n            from langflow.initial_setup import setup\\n\\n            package_base = os.path.realpath(str(Path(setup.__file__).parent / \\\"profile_pictures\\\"))\\n            package_candidate = os.path.realpath(os.path.join(package_base, safe_folder, safe_file))  # noqa: PTH118\\n            if package_candidate != package_base and not package_candidate.startswith(package_base + os.sep):\\n                raise HTTPException(status_code=404, detail=\\\"Profile picture not found\\\")\\n\\n            package_path = Path(package_candidate)\\n            if package_path.exists():\\n                file_path = package_path\\n            else:\\n                raise HTTPException(status_code=404, detail=f\\\"Profile picture {safe_folder}/{safe_file} not found\\\")\\n\\n        content_type = build_content_type_from_extension(extension)\\n        # Read file directly from local filesystem using async file operations\\n        file_content = await anyio.Path(file_path).read_bytes()\\n        return StreamingResponse(BytesIO(file_content), media_type=content_type)\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n\\n@router.get(\\\"/profile_pictures/list\\\")\\nasync def list_profile_pictures(\\n    settings_service: Annotated[SettingsService, Depends(get_settings_service)],\\n):\\n    \\\"\\\"\\\"List profile pictures from local filesystem.\\n\\n    Profile pictures are first looked up in config_dir/profile_pictures/,\\n    then fallback to the package's bundled profile_pictures directory.\\n    \\\"\\\"\\\"\\n    try:\\n        config_dir = settings_service.settings.config_dir\\n        config_path = Path(config_dir)  # type: ignore[arg-type]\\n\\n        # Build list for all allowed folders (dynamic)\\n        allowed_folders = _get_allowed_profile_picture_folders(settings_service)\\n\\n        results: list[str] = []\\n        cfg_base = config_path / \\\"profile_pictures\\\"\\n        if cfg_base.exists():\\n            for folder in sorted(allowed_folders):\\n                p = cfg_base / folder\\n                if p.exists():\\n                    results += [f\\\"{folder}/{f.name}\\\" for f in p.iterdir() if f.is_file()]\\n\\n        # Fallback to package if config_dir produced no results\\n        if not results:\\n            from langflow.initial_setup import setup\\n\\n            package_base = Path(setup.__file__).parent / \\\"profile_pictures\\\"\\n            for folder in sorted(allowed_folders):\\n                p = package_base / folder\\n                if p.exists():\\n                    results += [f\\\"{folder}/{f.name}\\\" for f in p.iterdir() if f.is_file()]\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return {\\\"files\\\": results}\\n\\n\\n@router.get(\\\"/list/{flow_id}\\\")\\nasync def list_files(\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    try:\\n        files = await storage_service.list_files(flow_id=str(flow.id))\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return {\\\"files\\\": files}\\n\\n\\n@router.delete(\\\"/delete/{flow_id}/{file_name}\\\")\\nasync def delete_file(\\n    file_name: ValidatedFileName,\\n    flow: Annotated[Flow, Depends(get_flow)],\\n    current_user: CurrentActiveUser,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    # Deleting a file from a flow's storage mutates the flow's attachments;\\n    # enforce WRITE so the external access ceiling (e.g. a \\\"viewer\\\") is honored.\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.WRITE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n    try:\\n        await storage_service.delete_file(flow_id=str(flow.id), file_name=file_name)\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\\n    return {\\\"message\\\": f\\\"File {file_name} deleted successfully\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/flow_events.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a79b422e547826f8578ece58b40d65519eb6abbbf0292eb800b30551afb17b5\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, Depends, HTTPException, Query\\nfrom pydantic import BaseModel, Field\\nfrom sqlmodel import or_, select\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.deps import get_flow_events_service\\nfrom langflow.services.flow_events import FLOW_EVENT_TYPES, FlowEventsService\\n\\nrouter = APIRouter(prefix=\\\"/flows\\\", tags=[\\\"Flow Events\\\"], include_in_schema=False)\\n\\n\\nclass FlowEventResponse(BaseModel):\\n    type: str\\n    timestamp: float\\n    summary: str\\n\\n\\nclass FlowEventsResponse(BaseModel):\\n    events: list[FlowEventResponse]\\n    settled: bool\\n\\n\\nclass FlowEventCreate(BaseModel):\\n    type: FLOW_EVENT_TYPES\\n    summary: str = Field(default=\\\"\\\", max_length=500)\\n\\n\\nasync def _verify_flow_owner(session: DbSession, flow_id: UUID, user_id: UUID) -> None:\\n    result = await session.exec(\\n        select(Flow).where(\\n            Flow.id == flow_id,\\n            or_(Flow.user_id == user_id, Flow.user_id == None),  # noqa: E711\\n        )\\n    )\\n    if not result.first():\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n\\n\\n@router.get(\\\"/{flow_id}/events\\\", response_model=FlowEventsResponse)\\nasync def get_flow_events(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    since: Annotated[float, Query(description=\\\"UTC timestamp to get events after\\\")] = 0.0,\\n    *,\\n    service: Annotated[FlowEventsService, Depends(get_flow_events_service)],\\n) -> FlowEventsResponse:\\n    await _verify_flow_owner(session, flow_id, current_user.id)\\n    events, settled = service.get_since(str(flow_id), since)\\n    return FlowEventsResponse(\\n        events=[FlowEventResponse(type=e.type, timestamp=e.timestamp, summary=e.summary) for e in events],\\n        settled=settled,\\n    )\\n\\n\\n@router.post(\\\"/{flow_id}/events\\\", response_model=FlowEventResponse, status_code=201)\\nasync def create_flow_event(\\n    flow_id: UUID,\\n    event: FlowEventCreate,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    *,\\n    service: Annotated[FlowEventsService, Depends(get_flow_events_service)],\\n) -> FlowEventResponse:\\n    \\\"\\\"\\\"Append an event to a flow's event queue.\\\"\\\"\\\"\\n    await _verify_flow_owner(session, flow_id, current_user.id)\\n    e = service.append(str(flow_id), event.type, event.summary)\\n    return FlowEventResponse(type=e.type, timestamp=e.timestamp, summary=e.summary)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/flow_version.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"deee179f6d9753fe3f4120dbccb209e0d48c4ddc261fcfc92baf8636e434aa2e\",\"content\":\"import copy\\nfrom datetime import datetime, timezone\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nfrom fastapi import APIRouter, HTTPException, Query\\nfrom lfx.log import logger\\nfrom lfx.services.settings.feature_flags import FEATURE_FLAGS\\nfrom sqlalchemy.exc import IntegrityError, SQLAlchemyError\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.api.utils import CurrentActiveUser, DbSession\\nfrom langflow.api.utils.core import strip_secret_field_values\\nfrom langflow.api.v1.flows import _validate_catalog_policy_for_write\\nfrom langflow.api.v1.mappers.deployments.helpers import get_owned_provider_account_or_404\\nfrom langflow.api.v1.mappers.deployments.sync import sync_flow_version_attachments\\nfrom langflow.services.authorization import FlowAction, ensure_flow_permission\\nfrom langflow.services.database.models.flow.model import Flow, FlowRead\\nfrom langflow.services.database.models.flow_version.crud import (\\n    create_flow_version_entry,\\n    delete_flow_version_entry,\\n    get_flow_version_entry_or_raise,\\n    get_flow_version_list_simple,\\n    get_flow_versions_with_provider_status,\\n)\\nfrom langflow.services.database.models.flow_version.exceptions import (\\n    FlowVersionConflictError,\\n    FlowVersionDeployedError,\\n    FlowVersionError,\\n    FlowVersionNotFoundError,\\n    FlowVersionSerializationError,\\n)\\nfrom langflow.services.database.models.flow_version.model import (\\n    FlowVersion,\\n    FlowVersionCreate,\\n    FlowVersionListResponse,\\n    FlowVersionRead,\\n    FlowVersionReadWithData,\\n)\\nfrom langflow.services.deps import get_catalog_policy_service, get_settings_service\\n\\nrouter = APIRouter(prefix=\\\"/flows/{flow_id}/versions\\\", tags=[\\\"Flow Versions\\\"], include_in_schema=False)\\n\\n\\ndef strip_version_data(data: dict | None) -> dict | None:\\n    \\\"\\\"\\\"Strip secret field values from a version entry's flow data dict.\\n\\n    Uses the metadata-driven scrubber, so ``password``-marked fields under\\n    ordinary names and credential-bearing connection strings are cleared too --\\n    not only fields whose name matches the legacy API-key pattern.\\n\\n    Returns None if stripping fails, to prevent accidental secret leakage.\\n    \\\"\\\"\\\"\\n    if data is None:\\n        return None\\n    try:\\n        return strip_secret_field_values(data)\\n    except (KeyError, TypeError, AttributeError, ValueError):\\n        logger.warning(\\n            \\\"Failed to strip API keys from version data \u2014 excluding data from response to prevent secret leakage\\\",\\n            exc_info=True,\\n        )\\n        return None\\n\\n\\ndef _version_to_read(entry: FlowVersion, *, is_deployed: bool | None = None) -> FlowVersionRead:\\n    result = FlowVersionRead.model_validate(entry, from_attributes=True)\\n    result.is_deployed = is_deployed\\n    return result\\n\\n\\ndef _version_to_read_full(\\n    entry: FlowVersion, *, strip_keys: bool = False, is_deployed: bool | None = None\\n) -> FlowVersionReadWithData:\\n    result = FlowVersionReadWithData.model_validate(entry, from_attributes=True)\\n    result.is_deployed = is_deployed\\n    if strip_keys:\\n        result.data = strip_version_data(result.data)\\n    return result\\n\\n\\nasync def _get_user_flow(session: AsyncSession, flow_id: UUID, user_id: UUID) -> Flow:\\n    result = await session.exec(select(Flow).where(Flow.id == flow_id, Flow.user_id == user_id))\\n    flow = result.first()\\n    if not flow:\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n    return flow\\n\\n\\ndef _translate_version_error(exc: FlowVersionError) -> HTTPException:\\n    \\\"\\\"\\\"Translate a domain exception into an HTTPException.\\\"\\\"\\\"\\n    if isinstance(exc, FlowVersionSerializationError):\\n        return HTTPException(status_code=422, detail=str(exc))\\n    if isinstance(exc, FlowVersionConflictError):\\n        return HTTPException(status_code=409, detail=str(exc))\\n    if isinstance(exc, FlowVersionDeployedError):\\n        return HTTPException(status_code=409, detail=str(exc))\\n    if isinstance(exc, FlowVersionNotFoundError):\\n        return HTTPException(status_code=404, detail=str(exc))\\n    return HTTPException(status_code=500, detail=str(exc))\\n\\n\\ndef _ensure_deployments_enabled_for_provider_id(deployment_provider_id: UUID | None) -> None:\\n    if deployment_provider_id and not FEATURE_FLAGS.wxo_deployments:\\n        msg = \\\"Cannot use deployment_provider_id: the wxo_deployments feature flag is disabled\\\"\\n        raise HTTPException(status_code=400, detail=msg)\\n\\n\\n# NOTE: `response_model_exclude_none=True` is intentionally narrow here: we use\\n# it to omit `is_deployed` unless deployment status is explicitly requested.\\n# If future nullable fields must be returned as explicit null, prefer splitting\\n# response schemas/routes and disabling this global exclude-none behavior.\\n@router.get(\\\"/\\\", response_model_exclude_none=True)\\nasync def list_flow_versions(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    limit: Annotated[int, Query(ge=1, le=100)] = 50,\\n    offset: Annotated[int, Query(ge=0)] = 0,\\n    deployment_provider_id: Annotated[\\n        UUID | None,\\n        Query(description=(\\\"Optional provider account ID for provider account-scoped deployment status.\\\")),\\n    ] = None,\\n) -> FlowVersionListResponse:\\n    await _get_user_flow(session, flow_id, current_user.id)\\n    _ensure_deployments_enabled_for_provider_id(deployment_provider_id)\\n\\n    if deployment_provider_id is not None:\\n        await get_owned_provider_account_or_404(\\n            provider_id=deployment_provider_id,\\n            user_id=current_user.id,\\n            db=session,\\n        )\\n        # Best-effort provider-scoped sync before read to keep status fresh.\\n        try:\\n            await sync_flow_version_attachments(\\n                db=session,\\n                flow_id=flow_id,\\n                user_id=current_user.id,\\n                deployment_provider_account_id=deployment_provider_id,\\n            )\\n        except Exception:  # noqa: BLE001\\n            logger.warning(\\n                \\\"Snapshot-level sync failed for flow %s; returning unverified deployment status\\\",\\n                flow_id,\\n                exc_info=True,\\n            )\\n\\n    if deployment_provider_id is not None:\\n        rows = await get_flow_versions_with_provider_status(\\n            session,\\n            flow_id,\\n            current_user.id,\\n            provider_account_id=deployment_provider_id,\\n            limit=limit,\\n            offset=offset,\\n        )\\n        entries = [_version_to_read(entry, is_deployed=is_deployed) for entry, is_deployed in rows]\\n    else:\\n        rows_simple = await get_flow_version_list_simple(\\n            session,\\n            flow_id,\\n            current_user.id,\\n            limit,\\n            offset,\\n        )\\n        entries = [_version_to_read(entry, is_deployed=None) for entry, _is_deployed in rows_simple]\\n\\n    max_entries = get_settings_service().settings.max_flow_version_entries_per_flow\\n    return FlowVersionListResponse(\\n        entries=entries,\\n        max_entries=max_entries,\\n    )\\n\\n\\n# TODO: Full-version export endpoint (export flow with all version entries embedded).\\n# This is planned as a follow-up feature. The per-version export (exporting a single\\n# version as a standalone flow) is available via the GET /{version_id} endpoint.\\n\\n\\n@router.get(\\\"/{version_id}\\\")\\nasync def get_single_flow_version(\\n    flow_id: UUID,\\n    version_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> FlowVersionReadWithData:\\n    await _get_user_flow(session, flow_id, current_user.id)\\n\\n    try:\\n        entry = await get_flow_version_entry_or_raise(session, version_id, current_user.id, flow_id=flow_id)\\n    except FlowVersionNotFoundError as exc:\\n        raise HTTPException(status_code=404, detail=\\\"Version entry not found\\\") from exc\\n\\n    return _version_to_read_full(entry, strip_keys=True)\\n\\n\\n# shares FlowVersionRead model with list endpoint (inside FlowVersionListResponse),\\n# but omits is_deployed field because its not relevant to this endpoint\\n@router.post(\\\"/\\\", status_code=201, response_model_exclude={\\\"is_deployed\\\"})\\nasync def create_snapshot(\\n    flow_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    body: FlowVersionCreate | None = None,\\n) -> FlowVersionRead:\\n    flow = await _get_user_flow(session, flow_id, current_user.id)\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.WRITE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n    description = body.description if body else None\\n\\n    try:\\n        data = copy.deepcopy(flow.data)\\n    except Exception as exc:\\n        raise HTTPException(\\n            status_code=422,\\n            detail=\\\"Flow data could not be copied for snapshot. The data may be corrupted.\\\",\\n        ) from exc\\n\\n    try:\\n        entry = await create_flow_version_entry(\\n            session,\\n            flow_id=flow.id,\\n            user_id=current_user.id,\\n            data=data,\\n            description=description,\\n        )\\n    except FlowVersionError as exc:\\n        raise _translate_version_error(exc) from exc\\n    return _version_to_read(entry)\\n\\n\\n@router.post(\\\"/{version_id}/activate\\\")\\nasync def activate_version(\\n    flow_id: UUID,\\n    version_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    *,\\n    save_draft: Annotated[bool, Query()] = True,\\n) -> FlowRead:\\n    flow = await _get_user_flow(session, flow_id, current_user.id)\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.WRITE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    # Verify version entry belongs to this flow\\n    try:\\n        target_entry = await get_flow_version_entry_or_raise(session, version_id, current_user.id, flow_id=flow_id)\\n    except FlowVersionNotFoundError as exc:\\n        raise HTTPException(status_code=404, detail=\\\"Version entry not found\\\") from exc\\n\\n    # Guard against activating a version with no data (check before auto-snapshot)\\n    if target_entry.data is None:\\n        raise HTTPException(status_code=400, detail=\\\"Cannot activate a version with no data\\\")\\n\\n    # Capture copies of both data dicts before the savepoint to avoid stale\\n    # reads if pruning inside create_flow_version_entry deletes old entries.\\n    try:\\n        current_data = copy.deepcopy(flow.data) if save_draft else None\\n        target_data = copy.deepcopy(target_entry.data)\\n    except Exception as exc:\\n        raise HTTPException(\\n            status_code=422,\\n            detail=\\\"Flow data could not be copied. The data may be corrupted.\\\",\\n        ) from exc\\n\\n    _validate_catalog_policy_for_write(\\n        target_data,\\n        snapshot=get_catalog_policy_service().snapshot,\\n    )\\n\\n    # Wrap auto-snapshot + flow overwrite in a single savepoint for atomicity.\\n    # If the flow update fails, the auto-snapshot is also rolled back.\\n    try:\\n        async with session.begin_nested():\\n            if save_draft and current_data is not None:\\n                await create_flow_version_entry(\\n                    session,\\n                    flow_id=flow.id,\\n                    user_id=current_user.id,\\n                    data=current_data,\\n                    description=f\\\"Auto-saved before activating v{target_entry.version_number}\\\",\\n                )\\n\\n            flow.data = target_data\\n            flow.updated_at = datetime.now(timezone.utc)\\n\\n            session.add(flow)\\n            await session.flush()\\n    except FlowVersionError as exc:\\n        raise _translate_version_error(exc) from exc\\n    except IntegrityError as exc:\\n        raise HTTPException(\\n            status_code=409,\\n            detail=\\\"Could not activate version \u2014 the flow was modified concurrently. Please try again.\\\",\\n        ) from exc\\n    except SQLAlchemyError as exc:\\n        raise HTTPException(\\n            status_code=500,\\n            detail=\\\"Database error while activating version. Please try again.\\\",\\n        ) from exc\\n\\n    await logger.adebug(\\\"Activated version %s (%s) for flow %s\\\", version_id, f\\\"v{target_entry.version_number}\\\", flow_id)\\n\\n    return FlowRead.model_validate(flow, from_attributes=True)\\n\\n\\n@router.delete(\\\"/{version_id}\\\", status_code=204)\\nasync def delete_version_entry(\\n    flow_id: UUID,\\n    version_id: UUID,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n) -> None:\\n    flow = await _get_user_flow(session, flow_id, current_user.id)\\n    await ensure_flow_permission(\\n        current_user,\\n        FlowAction.DELETE,\\n        flow_id=flow.id,\\n        flow_user_id=flow.user_id,\\n        workspace_id=flow.workspace_id,\\n        folder_id=flow.folder_id,\\n    )\\n\\n    # Verify entry belongs to this flow, then delete\\n    try:\\n        await get_flow_version_entry_or_raise(session, version_id, current_user.id, flow_id=flow_id)\\n        await delete_flow_version_entry(session, version_id, current_user.id)\\n    except FlowVersionError as exc:\\n        raise _translate_version_error(exc) from exc\\n    await logger.adebug(\\\"Deleted version entry %s for flow %s\\\", version_id, flow_id)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/flows.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a52a752a33298f24da59fd86f0f2aa9b7ffcf56f4f40743e9e744e9db086c62c\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport io\\nimport threading\\nimport zipfile\\nfrom collections.abc import Collection\\nfrom typing import Annotated\\nfrom uuid import UUID\\n\\nimport orjson\\nfrom fastapi import APIRouter, Depends, File, HTTPException, Request, UploadFile, status\\nfrom fastapi.encoders import jsonable_encoder\\nfrom fastapi_pagination import Page, Params\\nfrom fastapi_pagination.ext.sqlmodel import apaginate\\nfrom lfx.log.logger import logger\\nfrom lfx.services.cache.utils import CACHE_MISS\\nfrom lfx.services.catalog_policy import CatalogPolicySnapshot\\nfrom lfx.utils.flow_validation import (\\n    CatalogPolicyIdentityUnavailableError,\\n    CatalogPolicyValidationError,\\n    validate_catalog_policy_for_flow,\\n)\\nfrom pydantic import ValidationError\\nfrom sqlalchemy import case\\nfrom sqlalchemy.exc import IntegrityError\\nfrom sqlmodel import and_, col, select\\n\\nfrom langflow.api.utils import (\\n    CurrentActiveUser,\\n    DbSession,\\n    cascade_delete_flow,\\n    normalize_code_for_import,\\n    validate_is_component,\\n)\\nfrom langflow.api.utils.core import strip_secret_field_values\\nfrom langflow.api.utils.mcp.flow_secrets import (\\n    extract_and_strip_mcp_secrets,\\n    mcp_server_names,\\n    persist_and_strip_mcp_secrets,\\n    stage_mcp_secrets,\\n)\\nfrom langflow.api.utils.zip_utils import extract_flows_from_zip\\nfrom langflow.api.v1.authz_route_dependencies import (\\n    AuthorizedDeleteFlow,\\n    AuthorizedReadFlow,\\n    AuthorizedWriteFlow,\\n    RequireFlowCreate,\\n)\\nfrom langflow.api.v1.flows_helpers import (\\n    _build_flows_download_response,\\n    _canonicalize_flow_destination,\\n    _get_safe_flow_path,\\n    _new_flow,\\n    _patch_flow,\\n    _read_flow,\\n    _resolve_flow_destination,\\n    _save_flow_to_fs,\\n    _update_existing_flow,\\n    _validate_and_assign_folder,\\n    _verify_fs_path,\\n    destination_folder_owner_id,\\n)\\nfrom langflow.api.v1.mappers.deployments.sync import retry_flow_operation_on_deployment_guard\\nfrom langflow.api.v1.schemas import FlowListCreate\\nfrom langflow.api.v1.schemas.public_flows import PublicFlowRead\\nfrom langflow.initial_setup.constants import STARTER_FOLDER_NAME\\nfrom langflow.services.auth.utils import get_current_active_user, get_optional_user\\nfrom langflow.services.authorization import (\\n    FlowAction,\\n    ensure_flow_permission,\\n    filter_visible_resources,\\n    restrict_to_owned_or_visible_scope,\\n    visible_scope_prefilter,\\n)\\nfrom langflow.services.authorization.fetch import deny_to_404\\nfrom langflow.services.authorization.public_access import (\\n    PublicResourceAction,\\n    authorize_public_flow_access,\\n    public_flow_capabilities,\\n)\\nfrom langflow.services.authorization.utils import _resolve_authz_domain\\nfrom langflow.services.cache.service import ThreadingInMemoryCache\\nfrom langflow.services.database.lock_retry import (\\n    is_database_lock_error,\\n    run_with_lock_retry,\\n    sanitize_database_error,\\n)\\nfrom langflow.services.database.models.deployment.exceptions import (\\n    araise_if_deployment_guard_error_or_skip,\\n)\\nfrom langflow.services.database.models.flow.model import (\\n    Flow,\\n    FlowCreate,\\n    FlowHeader,\\n    FlowRead,\\n    FlowType,\\n    FlowUpdate,\\n)\\n\\n# TODO: Full-version import/export is planned as a follow-up feature. When implemented,\\n# re-add imports for create_flow_version_entry, get_flow_versions_with_provider_status, strip_version_data,\\n# and FlowVersionError from the flow_version modules.\\nfrom langflow.services.database.models.folder.constants import DEFAULT_FOLDER_NAME\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.user.model import User, UserRead\\nfrom langflow.services.deps import get_catalog_policy_service, get_settings_service, get_storage_service\\nfrom langflow.services.storage.service import StorageService\\nfrom langflow.utils.compression import compress_response\\nfrom langflow.utils.i18n import translate_flow_notes, translate_starter_flows\\n\\n# Re-export helpers so existing ``from langflow.api.v1.flows import ...`` still works.\\n__all__ = [\\n    \\\"_get_safe_flow_path\\\",\\n    \\\"_new_flow\\\",\\n    \\\"_read_flow\\\",\\n    \\\"_save_flow_to_fs\\\",\\n    \\\"_update_existing_flow\\\",\\n    \\\"_verify_fs_path\\\",\\n]\\n\\n_SQLITE_UNIQUE_MARKER = \\\"UNIQUE constraint failed: \\\"\\n_POSTGRES_UNIQUE_VIOLATION_SQLSTATE = \\\"23505\\\"\\n_SQLITE_FLOW_UNIQUE_COLUMNS = {\\n    (\\\"id\\\",): \\\"id\\\",\\n    (\\\"user_id\\\", \\\"name\\\"): \\\"name\\\",\\n    (\\\"user_id\\\", \\\"endpoint_name\\\"): \\\"endpoint_name\\\",\\n}\\n_POSTGRES_FLOW_UNIQUE_COLUMNS = {\\n    \\\"flow_pkey\\\": \\\"id\\\",\\n    \\\"pk_flow\\\": \\\"id\\\",\\n    \\\"uq_flow_id\\\": \\\"id\\\",\\n    \\\"unique_flow_name\\\": \\\"name\\\",\\n    \\\"unique_flow_endpoint_name\\\": \\\"endpoint_name\\\",\\n}\\n\\n\\ndef _postgres_unique_column(exc: BaseException) -> str | None:\\n    \\\"\\\"\\\"Return a safe flow column for a PostgreSQL unique violation.\\\"\\\"\\\"\\n    current: BaseException | None = exc\\n    constraint_name: str | None = None\\n    is_unique_violation = False\\n    seen: set[int] = set()\\n\\n    while current is not None and id(current) not in seen:\\n        seen.add(id(current))\\n        sqlstate = getattr(current, \\\"sqlstate\\\", None) or getattr(current, \\\"pgcode\\\", None)\\n        is_unique_violation = is_unique_violation or sqlstate == _POSTGRES_UNIQUE_VIOLATION_SQLSTATE\\n        diagnostic = getattr(current, \\\"diag\\\", None)\\n        candidate = getattr(diagnostic, \\\"constraint_name\\\", None) or getattr(current, \\\"constraint_name\\\", None)\\n        if candidate:\\n            constraint_name = str(candidate)\\n        current = getattr(current, \\\"orig\\\", None) or current.__cause__\\n\\n    if not is_unique_violation or constraint_name is None:\\n        return None\\n    return _POSTGRES_FLOW_UNIQUE_COLUMNS.get(constraint_name)\\n\\n\\nDB_OPERATION_FAILED = \\\"The database rejected the request.\\\"\\nFLOW_PERSIST_FAILED = \\\"Could not persist the flow.\\\"\\n\\n# SQLite and PostgreSQL report a violation differently: SQLite names the columns\\n# (\\\"UNIQUE constraint failed: flow.user_id, flow.name\\\") while PostgreSQL names the constraint\\n# ('... violates unique constraint \\\"unique_flow_name\\\"'). Match whichever marker is present so both\\n# backends produce the same client-facing detail. Every constraint below is named in the models.\\n_UNIQUE_VIOLATION_DETAILS: tuple[tuple[str, str], ...] = (\\n    (\\\"unique_flow_endpoint_name\\\", \\\"Endpoint name must be unique\\\"),\\n    (\\\"flow.endpoint_name\\\", \\\"Endpoint name must be unique\\\"),\\n    (\\\"unique_flow_name\\\", \\\"Name must be unique\\\"),\\n    (\\\"flow.name\\\", \\\"Name must be unique\\\"),\\n    (\\\"unique_folder_name\\\", \\\"Project name must be unique\\\"),\\n    (\\\"folder.name\\\", \\\"Project name must be unique\\\"),\\n    (\\\"flow_pkey\\\", \\\"A flow with this ID already exists\\\"),\\n    (\\\"flow.id\\\", \\\"A flow with this ID already exists\\\"),\\n    (\\\"folder_pkey\\\", \\\"A project with this ID already exists\\\"),\\n    (\\\"folder.id\\\", \\\"A project with this ID already exists\\\"),\\n)\\n_UNIQUE_VIOLATION_TEXT = (\\\"UNIQUE constraint failed\\\", \\\"duplicate key value violates unique constraint\\\")\\n_UNIQUE_VIOLATION_SQLSTATE = \\\"23505\\\"\\n\\n\\ndef _is_unique_violation(exc: Exception, msg: str) -> bool:\\n    \\\"\\\"\\\"Detect a unique violation on any backend.\\n\\n    Prefers the SQLSTATE on the driver exception (23505 on PostgreSQL, exposed as ``sqlstate`` by\\n    psycopg3 and ``pgcode`` by psycopg2) and falls back to the message text, which is all SQLite\\n    offers.\\n\\n    Only database errors are considered. SQLAlchemy hangs the driver exception off ``.orig``, so\\n    that attribute is what separates a real DBAPI failure from an unrelated exception whose text\\n    merely contains the SQLite marker \u2014 a flow name can carry that string, and text alone must not\\n    be enough to launder it into a 4xx conflict.\\n    \\\"\\\"\\\"\\n    if not hasattr(exc, \\\"orig\\\"):\\n        return False\\n    orig = exc.orig\\n    sqlstate = getattr(orig, \\\"sqlstate\\\", None) or getattr(orig, \\\"pgcode\\\", None)\\n    if sqlstate == _UNIQUE_VIOLATION_SQLSTATE:\\n        return True\\n    return any(marker in msg for marker in _UNIQUE_VIOLATION_TEXT)\\n\\n\\ndef _sqlite_unique_detail(msg: str, *, status_code: int) -> HTTPException:\\n    \\\"\\\"\\\"Map a SQLite ``UNIQUE constraint failed: <cols>`` message to a client-facing detail.\\n\\n    SQLite names columns rather than the constraint, so the column tuple is the only signal.\\n    On ``flow`` only the exact shapes in ``_SQLITE_FLOW_UNIQUE_COLUMNS`` are named; any other\\n    shape is a 500 rather than a guess. Other tables fall through to the qualified-name markers,\\n    which is how a project (``folder``) collision keeps its own wording.\\n    \\\"\\\"\\\"\\n    constraint = msg.split(_SQLITE_UNIQUE_MARKER, maxsplit=1)[1].splitlines()[0]\\n    tables: set[str] = set()\\n    columns: list[str] = []\\n    for qualified in constraint.split(\\\",\\\"):\\n        table, separator, candidate = qualified.strip().rpartition(\\\".\\\")\\n        if not separator:\\n            return HTTPException(status_code=500, detail=FLOW_PERSIST_FAILED)\\n        tables.add(table.rsplit(\\\".\\\", maxsplit=1)[-1])\\n        columns.append(candidate)\\n\\n    if tables == {\\\"flow\\\"}:\\n        column = _SQLITE_FLOW_UNIQUE_COLUMNS.get(tuple(columns))\\n        if column is None:\\n            return HTTPException(status_code=500, detail=FLOW_PERSIST_FAILED)\\n        return HTTPException(status_code=status_code, detail=f\\\"{column.capitalize().replace('_', ' ')} must be unique\\\")\\n\\n    for marker, detail in _UNIQUE_VIOLATION_DETAILS:\\n        if marker in constraint:\\n            return HTTPException(status_code=status_code, detail=detail)\\n    return HTTPException(status_code=500, detail=FLOW_PERSIST_FAILED)\\n\\n\\ndef _handle_unique_constraint_error(exc: Exception, *, status_code: int = 400) -> HTTPException:\\n    \\\"\\\"\\\"Map a unique-constraint violation to *status_code*; map anything else to a sanitized 500.\\n\\n    Callers either raise the result directly or read a 500 as \\\"not a conflict\\\" (see update_flow),\\n    so the 500 branch stays \u2014 but its detail is sanitized, because SQLAlchemy's ``str()`` embeds\\n    the failing statement and its bound parameters.\\n\\n    The three signals are tried strongest first. PostgreSQL's ``diag.constraint_name`` is\\n    authoritative and comes from the driver, so it wins over the message text, which can carry a\\n    user-supplied value that imitates a marker. SQLite offers no constraint name, so its message\\n    is parsed structurally. Only then does the marker table run, and an unrecognized violation is\\n    a 500 rather than a conflict invented from driver text.\\n    \\\"\\\"\\\"\\n    msg = str(exc)\\n    if not _is_unique_violation(exc, msg):\\n        return HTTPException(status_code=500, detail=sanitize_database_error(exc, DB_OPERATION_FAILED))\\n\\n    column = _postgres_unique_column(getattr(exc, \\\"orig\\\", None) or exc)\\n    if column is not None:\\n        return HTTPException(status_code=status_code, detail=f\\\"{column.capitalize().replace('_', ' ')} must be unique\\\")\\n\\n    if _SQLITE_UNIQUE_MARKER in msg:\\n        return _sqlite_unique_detail(msg, status_code=status_code)\\n\\n    for marker, detail in _UNIQUE_VIOLATION_DETAILS:\\n        if marker in msg:\\n            return HTTPException(status_code=status_code, detail=detail)\\n    return HTTPException(status_code=500, detail=FLOW_PERSIST_FAILED)\\n\\n\\ndef _validate_catalog_policy_for_write(\\n    flow_data: dict | None,\\n    *,\\n    snapshot: CatalogPolicySnapshot,\\n) -> None:\\n    \\\"\\\"\\\"Validate one effective flow graph and expose policy denials as client errors.\\\"\\\"\\\"\\n    try:\\n        validate_catalog_policy_for_flow(flow_data, snapshot=snapshot)\\n    except CatalogPolicyValidationError as exc:\\n        raise HTTPException(status_code=400, detail=str(exc)) from exc\\n    except CatalogPolicyIdentityUnavailableError as exc:\\n        raise HTTPException(status_code=503, detail=str(exc)) from exc\\n\\n\\n# build router\\nrouter = APIRouter(prefix=\\\"/flows\\\", tags=[\\\"Flows\\\"])\\n\\nFLOW_UPDATE_FAILED = \\\"Could not update the flow.\\\"\\nFLOW_UPDATE_BUSY = \\\"The database is busy. Please retry the request.\\\"\\nFLOW_CREATE_FAILED = \\\"Could not create the flow.\\\"\\nFLOW_CREATE_BUSY = \\\"The database is busy. Please retry the request.\\\"\\nFLOW_DELETE_FAILED = \\\"Could not delete the flow.\\\"\\nFLOW_DELETE_BUSY = \\\"The database is busy. Please retry the request.\\\"\\n\\n\\n@router.post(\\\"/\\\", response_model=FlowRead, status_code=201)\\nasync def create_flow(\\n    *,\\n    session: DbSession,\\n    flow: FlowCreate,\\n    current_user: CurrentActiveUser,\\n    _create: RequireFlowCreate,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    try:\\n        catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n        _validate_catalog_policy_for_write(flow.data, snapshot=catalog_policy_snapshot)\\n        await persist_and_strip_mcp_secrets(flow.data, current_user.id, session)\\n        # FastAPI builds the dependency's body model independently from the\\n        # handler's body model. Carry the exact destination that was authorized\\n        # into the row we persist so stale caller scope fields cannot retarget\\n        # the write after the guard has run.\\n        flow.workspace_id, flow.folder_id = _create\\n        stable_flow = flow.model_copy(deep=True)\\n        user_id = current_user.id\\n\\n        async def create_attempt(_attempt: int) -> FlowRead:\\n            # _new_flow mutates its input while normalizing ownership, name,\\n            # endpoint and destination. Rebuild it for every transaction so a\\n            # rollback never leaves the retry with partially normalized state.\\n            return await _new_flow(\\n                session=session,\\n                flow=stable_flow.model_copy(deep=True),\\n                user_id=user_id,\\n                storage_service=storage_service,\\n                widen_for_authz=True,\\n                propagate_unhandled_errors=True,\\n            )\\n\\n        return await run_with_lock_retry(\\n            create_attempt,\\n            session=session,\\n            description=\\\"flow creation\\\",\\n        )\\n    except HTTPException as exc:\\n        if exc.status_code != status.HTTP_500_INTERNAL_SERVER_ERROR:\\n            raise\\n        await logger.aerror(\\\"Flow creation failed\\\", error_type=type(exc).__name__)\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=FLOW_CREATE_FAILED) from exc\\n    except Exception as e:\\n        if is_database_lock_error(e):\\n            await logger.aerror(\\\"Flow creation remained locked after retries\\\", error_type=type(e).__name__)\\n            raise HTTPException(\\n                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n                detail=FLOW_CREATE_BUSY,\\n                headers={\\\"Retry-After\\\": \\\"1\\\"},\\n            ) from e\\n        await logger.aerror(\\\"Flow creation failed\\\", error_type=type(e).__name__)\\n        # Do not expose SQLAlchemy statements, bound parameters, database URLs\\n        # or user-provided flow identifiers through the API response.\\n        handled_error = _handle_unique_constraint_error(e)\\n        if handled_error.status_code != status.HTTP_500_INTERNAL_SERVER_ERROR:\\n            raise handled_error from e\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=FLOW_CREATE_FAILED) from e\\n\\n\\n@router.get(\\\"/\\\", response_model=list[FlowRead] | Page[FlowRead] | list[FlowHeader], status_code=200)\\nasync def read_flows(\\n    *,\\n    current_user: CurrentActiveUser,\\n    session: DbSession,\\n    remove_example_flows: bool = False,\\n    components_only: bool = False,\\n    get_all: bool = True,\\n    folder_id: UUID | None = None,\\n    flow_type: FlowType | None = None,\\n    params: Annotated[Params, Depends()],\\n    header_flows: bool = False,\\n):\\n    \\\"\\\"\\\"Retrieve a list of flows with optional pagination, filtering, and header-only mode.\\\"\\\"\\\"\\n    try:\\n        auth_settings = get_settings_service().auth_settings\\n\\n        default_folder = (await session.exec(select(Folder).where(Folder.name == DEFAULT_FOLDER_NAME))).first()\\n        default_folder_id = default_folder.id if default_folder else None\\n\\n        starter_folder = (\\n            await session.exec(select(Folder).where(Folder.name == STARTER_FOLDER_NAME, Folder.user_id.is_(None)))\\n        ).first()\\n        starter_folder_id = starter_folder.id if starter_folder else None\\n\\n        if not starter_folder and not default_folder:\\n            raise HTTPException(\\n                status_code=404,\\n                detail=\\\"Starter project and default project not found. Please create a project and add flows to it.\\\",\\n            )\\n\\n        if not folder_id:\\n            folder_id = default_folder_id\\n\\n        # Rows the caller owns outright. Under AUTO_LOGIN the legacy owner-scoped\\n        # query also surfaces null-owner flows; keep that in the fallback path\\n        # (``fallback_clause``). The SQL prefilter union, however, must NOT\\n        # blanket-include null-owner rows: the in-memory fallback routes them\\n        # through ``batch_enforce`` (``filter_visible_resources``'s owner_extractor\\n        # returns None, which never equals a real user id), so the prefilter keeps\\n        # them out of the owned half and a null-owner flow is visible only when the\\n        # plugin lists its id. AUTHZ_ENABLED and AUTO_LOGIN are independent flags,\\n        # so both can be set \u2014 this keeps the two paths consistent regardless.\\n        owned_clause = Flow.user_id == current_user.id\\n        fallback_clause = owned_clause\\n        if auth_settings.AUTO_LOGIN:\\n            fallback_clause = (Flow.user_id == None) | owned_clause  # noqa: E711\\n\\n        # DB-layer authz prefilter: a registered authorization plugin can return\\n        # the concrete set of flow ids the caller may read, letting us widen the\\n        # owner-scoped query to (owned \u2295 visible) in SQL and skip the per-row\\n        # in-memory filter below. OSS pass-through returns None \u2192 the query stays\\n        # owner-scoped and ``filter_visible_resources`` runs unchanged.\\n        visibility_scope = await visible_scope_prefilter(current_user, resource_type=\\\"flow\\\", act=FlowAction.READ)\\n        if visibility_scope is not None:\\n            canonical_workspace = case(\\n                (col(Flow.folder_id).is_not(None), Folder.workspace_id),\\n                else_=Flow.workspace_id,\\n            )\\n            stmt = restrict_to_owned_or_visible_scope(\\n                select(Flow).outerjoin(Folder, Folder.id == Flow.folder_id),\\n                id_column=Flow.id,\\n                owner_clause=owned_clause,\\n                workspace_expression=canonical_workspace,\\n                project_column=Flow.folder_id,\\n                visibility=visibility_scope,\\n            )\\n        else:\\n            stmt = select(Flow).where(fallback_clause)\\n\\n        if remove_example_flows:\\n            stmt = stmt.where(Flow.folder_id != starter_folder_id)\\n\\n        if components_only:\\n            stmt = stmt.where(Flow.is_component == True)  # noqa: E712\\n\\n        if flow_type is not None:\\n            stmt = stmt.where(Flow.flow_type == flow_type)\\n\\n        if get_all:\\n            flows = (await session.exec(stmt)).all()\\n            flows = validate_is_component(flows)\\n            if components_only:\\n                flows = [flow for flow in flows if flow.is_component]\\n            if remove_example_flows and starter_folder_id:\\n                flows = [flow for flow in flows if flow.folder_id != starter_folder_id]\\n            # When no DB prefilter is available (OSS pass-through), drop denied\\n            # rows in memory (per-flow domain_extractor). When the prefilter is\\n            # active the SQL union above is already authoritative, so skip the\\n            # per-row enforce to avoid an N+1.\\n            if visibility_scope is None:\\n                flows = await filter_visible_resources(\\n                    current_user,\\n                    resource_type=\\\"flow\\\",\\n                    candidates=list(flows),\\n                    domain_extractor=lambda flow: _resolve_authz_domain(flow.workspace_id, flow.folder_id),\\n                    owner_extractor=lambda flow: flow.user_id,\\n                    act=FlowAction.READ,\\n                )\\n            if header_flows:\\n                # Convert to FlowHeader objects and compress the response\\n                flow_headers = [FlowHeader.model_validate(flow, from_attributes=True) for flow in flows]\\n                return compress_response(flow_headers)\\n\\n            # Convert to FlowRead while session is still active to avoid detached instance errors\\n            flow_reads = [FlowRead.model_validate(flow, from_attributes=True) for flow in flows]\\n            return compress_response(flow_reads)\\n\\n        stmt = stmt.where(Flow.folder_id == folder_id)\\n\\n        import warnings\\n\\n        with warnings.catch_warnings():\\n            warnings.filterwarnings(\\n                \\\"ignore\\\", category=DeprecationWarning, module=r\\\"fastapi_pagination\\\\.ext\\\\.sqlalchemy\\\"\\n            )\\n            page = await apaginate(session, stmt, params=params)\\n\\n        # Same authz handling as get_all. With the SQL prefilter active the union\\n        # was applied before pagination, so ``page.total`` is accurate; the OSS\\n        # fallback narrows ``page.items`` in memory and ``page.total`` may\\n        # overcount denied rows (unchanged from before).\\n        if visibility_scope is None:\\n            page.items = await filter_visible_resources(\\n                current_user,\\n                resource_type=\\\"flow\\\",\\n                candidates=list(page.items),\\n                domain_extractor=lambda flow: _resolve_authz_domain(flow.workspace_id, flow.folder_id),\\n                owner_extractor=lambda flow: flow.user_id,\\n                act=FlowAction.READ,\\n            )\\n        return page  # noqa: TRY300 \u2014 final return inside try matches the existing style of this handler\\n\\n    except Exception as e:\\n        import logging as _logging\\n\\n        _logging.getLogger(__name__).exception(\\\"Error listing flows\\\")\\n        raise HTTPException(status_code=500, detail=\\\"An internal error occurred while listing flows.\\\") from e\\n\\n\\n@router.get(\\\"/{flow_id}\\\", response_model=FlowRead, status_code=200)\\nasync def read_flow(\\n    *,\\n    flow_id: UUID,  # noqa: ARG001\\n    flow: AuthorizedReadFlow,\\n):\\n    \\\"\\\"\\\"Read a flow.\\\"\\\"\\\"\\n    return FlowRead.model_validate(flow, from_attributes=True)\\n\\n\\n@router.get(\\\"/{flow_id}/note_translations\\\", status_code=200)\\nasync def get_note_translations(\\n    *,\\n    flow_id: UUID,  # noqa: ARG001\\n    flow: AuthorizedReadFlow,\\n    request: Request,\\n) -> dict[str, str]:\\n    \\\"\\\"\\\"Return translated note node descriptions for the current locale.\\n\\n    Returns a mapping of node_id \u2192 translated markdown text.  Only nodes\\n    with a matching translation key are included; nodes without translations\\n    are omitted so the caller can leave them unchanged.\\n\\n    A missing or inaccessible flow yields 404 (via ``AuthorizedReadFlow``),\\n    consistent with ``GET /flows/{id}``; the sole frontend caller (NoteNode)\\n    treats that as \\\"no translations\\\" and renders the original text.\\n    \\\"\\\"\\\"\\n    from langflow.utils.i18n import translate\\n\\n    if not flow.data:\\n        return {}\\n\\n    locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n    nodes = flow.data.get(\\\"nodes\\\", [])\\n    result: dict[str, str] = {}\\n    for node in nodes:\\n        if node.get(\\\"type\\\") == \\\"noteNode\\\":\\n            i18n_key = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"i18n_key\\\")\\n            if i18n_key:\\n                translated = translate(i18n_key, locale, \\\"\\\")\\n                if translated:\\n                    result[node.get(\\\"id\\\")] = translated\\n    return result\\n\\n\\n@router.get(\\\"/public_flow/{flow_id}\\\", response_model=PublicFlowRead, status_code=200)\\nasync def read_public_flow(\\n    *,\\n    session: DbSession,\\n    flow_id: UUID,\\n    request: Request,\\n):\\n    \\\"\\\"\\\"Read a public flow without requiring authorization (public means public).\\n\\n    Because this endpoint is unauthenticated, secret field values (every template\\n    field marked ``password``) are stripped before returning so a PUBLIC flow does\\n    not leak the owner's stored API keys / credentials to anonymous callers.\\n\\n    The response also carries the anonymous capability set. A canonical PUBLIC\\n    share admits flows whose ``access_type`` is still PRIVATE and bounds them at\\n    its own permission level, so a direct-link client that re-derives access from\\n    the legacy flag disagrees with this decision in both directions.\\n    \\\"\\\"\\\"\\n    flow = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n    if flow is None:\\n        raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n    await authorize_public_flow_access(\\n        flow=flow,\\n        action=PublicResourceAction.READ,\\n        request_host=request.url.hostname,\\n        session=session,\\n    )\\n    capabilities = await public_flow_capabilities(\\n        flow=flow,\\n        request_host=request.url.hostname,\\n        session=session,\\n    )\\n    flow_read = PublicFlowRead.model_validate(flow, from_attributes=True, update={\\\"public_access\\\": capabilities})\\n    flow_read.data = strip_secret_field_values(flow_read.data)\\n    return flow_read\\n\\n\\n@router.patch(\\\"/{flow_id}\\\", response_model=FlowRead, status_code=200)\\nasync def update_flow(\\n    *,\\n    session: DbSession,\\n    flow_id: UUID,\\n    db_flow: AuthorizedWriteFlow,\\n    flow: FlowUpdate,\\n    current_user: CurrentActiveUser,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Update a flow.\\\"\\\"\\\"\\n    actor = UserRead.model_validate(current_user, from_attributes=True)\\n    try:\\n        catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n        # Destination check: resolve the actual owner-folder/workspace tuple\\n        # before authorizing a move. ``_patch_flow`` applies payload values via\\n        # ``model_dump(exclude_unset=True, exclude_none=True)``, so None means\\n        # \\\"no change\\\" and falls back to the existing scope.\\n        requested_folder_id = flow.folder_id\\n        target_workspace_id, target_folder_id = await _resolve_flow_destination(\\n            session,\\n            db_flow.user_id,\\n            requested_folder_id,\\n            fallback_folder_id=db_flow.folder_id,\\n            authorized_existing_folder_id=db_flow.folder_id,\\n        )\\n        flow.workspace_id = target_workspace_id\\n        if requested_folder_id is not None:\\n            flow.folder_id = target_folder_id\\n        if target_workspace_id != db_flow.workspace_id or target_folder_id != db_flow.folder_id:\\n            try:\\n                await ensure_flow_permission(\\n                    actor,\\n                    FlowAction.WRITE,\\n                    flow_id=flow_id,\\n                    flow_user_id=db_flow.user_id,\\n                    workspace_id=target_workspace_id,\\n                    folder_id=target_folder_id,\\n                )\\n            except HTTPException as exc:\\n                raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n\\n        # Explicit folder_id=None is ignored here because _patch_flow builds\\n        # update_data with exclude_none=True, so null folder_id is a no-op.\\n        folder_id_will_change = target_folder_id != db_flow.folder_id\\n        flow_owner_ids = {flow_id: db_flow.user_id}\\n\\n        # Extract once, outside the retry loop. The in-place rewrite of flow.data survives a\\n        # rollback while the staged rows do not, so re-extracting on attempt 2 would find\\n        # only the reference it wrote itself and stage nothing. actor.id rather than\\n        # current_user.id: the rollback expires the ORM User.\\n        carried_secrets, secret_variables = extract_and_strip_mcp_secrets(flow.data)\\n\\n        async def operation() -> FlowRead:\\n            # Re-load inside each attempt so retry after nested rollback never uses an expired ORM instance.\\n            db_flow_for_attempt = await _read_flow(\\n                session=session,\\n                flow_id=flow_id,\\n                user_id=actor.id,\\n                for_update=True,\\n            )\\n            if not db_flow_for_attempt:\\n                raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n            # TOCTOU: a concurrent PATCH could have moved this flow to a\\n            # different workspace/folder between the destination check above\\n            # and this retry attempt. Re-authorize against the freshly\\n            # reloaded source AND destination so the writer cannot ride a\\n            # stale check across a race.\\n            try:\\n                await ensure_flow_permission(\\n                    actor,\\n                    FlowAction.WRITE,\\n                    flow_id=flow_id,\\n                    flow_user_id=db_flow_for_attempt.user_id,\\n                    workspace_id=db_flow_for_attempt.workspace_id,\\n                    folder_id=db_flow_for_attempt.folder_id,\\n                )\\n            except HTTPException as exc:\\n                raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n            attempt_target_workspace_id, attempt_target_folder_id = await _resolve_flow_destination(\\n                session,\\n                db_flow_for_attempt.user_id,\\n                flow.folder_id,\\n                fallback_folder_id=db_flow_for_attempt.folder_id,\\n                authorized_existing_folder_id=db_flow_for_attempt.folder_id,\\n            )\\n            if (\\n                attempt_target_workspace_id != db_flow_for_attempt.workspace_id\\n                or attempt_target_folder_id != db_flow_for_attempt.folder_id\\n            ):\\n                try:\\n                    await ensure_flow_permission(\\n                        actor,\\n                        FlowAction.WRITE,\\n                        flow_id=flow_id,\\n                        flow_user_id=db_flow_for_attempt.user_id,\\n                        workspace_id=attempt_target_workspace_id,\\n                        folder_id=attempt_target_folder_id,\\n                    )\\n                except HTTPException as exc:\\n                    raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n            effective_flow_data = flow.data if flow.data is not None else db_flow_for_attempt.data\\n            _validate_catalog_policy_for_write(effective_flow_data, snapshot=catalog_policy_snapshot)\\n            # The only write path where a literal is the user editing a key rather than a\\n            # file arriving. Scoped to servers this flow already referenced, so saving a\\n            # freshly imported flow cannot adopt its credential either.\\n            await stage_mcp_secrets(\\n                carried_secrets,\\n                secret_variables,\\n                actor.id,\\n                session,\\n                rotatable_servers=mcp_server_names(db_flow_for_attempt.data),\\n            )\\n            return await _patch_flow(\\n                session=session,\\n                db_flow=db_flow_for_attempt,\\n                flow=flow,\\n                user_id=actor.id,\\n                storage_service=storage_service,\\n            )\\n\\n        async def update_attempt(_attempt: int) -> FlowRead:\\n            if folder_id_will_change:\\n                return await retry_flow_operation_on_deployment_guard(\\n                    db=session,\\n                    flow_owner_ids=flow_owner_ids,\\n                    operation=operation,\\n                )\\n            return await operation()\\n\\n        return await run_with_lock_retry(\\n            update_attempt,\\n            session=session,\\n            description=f\\\"update_flow {flow_id}\\\",\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=update_flow flow_id={flow_id}\\\",\\n        )\\n        if is_database_lock_error(e):\\n            await logger.awarning(\\\"op=update_flow flow_id=%s exhausted lock retries\\\", flow_id)\\n            raise HTTPException(\\n                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n                detail=FLOW_UPDATE_BUSY,\\n                headers={\\\"Retry-After\\\": \\\"1\\\"},\\n            ) from e\\n        handled_error = _handle_unique_constraint_error(e)\\n        if handled_error.status_code != status.HTTP_500_INTERNAL_SERVER_ERROR:\\n            raise handled_error from e\\n        await logger.aerror(\\\"op=update_flow flow_id=%s failed with %s\\\", flow_id, type(e).__name__)\\n        raise HTTPException(\\n            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,\\n            detail=FLOW_UPDATE_FAILED,\\n        ) from e\\n\\n\\n@router.put(\\\"/{flow_id}\\\", response_model=FlowRead)\\nasync def upsert_flow(\\n    *,\\n    session: DbSession,\\n    flow_id: UUID,\\n    flow: FlowCreate,\\n    current_user: CurrentActiveUser,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Create or update a flow with a specific ID (upsert).\\n\\n    Returns 201 for creation, 200 for update.  Returns 404 if owned by another user.\\n    \\\"\\\"\\\"\\n    from fastapi.responses import JSONResponse\\n\\n    # Read once, outside the retry loop: a rollback between attempts expires the ORM User\\n    # and a later attribute read would lazy-load outside the greenlet.\\n    writer_id = current_user.id\\n    # Extract once: a rollback between retry attempts discards the staged rows but not the\\n    # in-place rewrite, so a second extraction would find only its own reference.\\n    carried_secrets, secret_variables = extract_and_strip_mcp_secrets(flow.data)\\n\\n    try:\\n        catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n        # Check if flow exists (without user filter to distinguish ownership vs CREATE)\\n        existing_flow = (await session.exec(select(Flow).where(Flow.id == flow_id))).first()\\n\\n        if existing_flow is not None:\\n            # Block non-owner upsert when cross-user fetch is off (UUID privacy).\\n            from langflow.services.deps import get_authorization_service\\n\\n            authz = get_authorization_service()\\n            can_widen = await authz.supports_cross_user_fetch() and await authz.is_enabled()\\n            if not can_widen and existing_flow.user_id != current_user.id:\\n                raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n\\n            try:\\n                await ensure_flow_permission(\\n                    current_user,\\n                    FlowAction.WRITE,\\n                    flow_id=flow_id,\\n                    flow_user_id=existing_flow.user_id,\\n                    workspace_id=existing_flow.workspace_id,\\n                    folder_id=existing_flow.folder_id,\\n                )\\n            except HTTPException as exc:\\n                raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n\\n            # Destination check (see update_flow above): resolve the actual\\n            # owner-folder/workspace tuple and authorize WRITE there.\\n            # ``_update_existing_flow`` applies payload values via\\n            # ``model_dump(exclude_unset=True, exclude_none=True)``, so None\\n            # means \\\"keep existing\\\" and a non-None differing value means \\\"move\\\".\\n            requested_folder_id = flow.folder_id\\n            target_workspace_id, target_folder_id = await _resolve_flow_destination(\\n                session,\\n                existing_flow.user_id,\\n                requested_folder_id,\\n                fallback_folder_id=existing_flow.folder_id,\\n                reject_invalid=True,\\n                authorized_existing_folder_id=existing_flow.folder_id,\\n            )\\n            flow.workspace_id = target_workspace_id\\n            if requested_folder_id is not None:\\n                flow.folder_id = target_folder_id\\n            if target_workspace_id != existing_flow.workspace_id or target_folder_id != existing_flow.folder_id:\\n                try:\\n                    await ensure_flow_permission(\\n                        current_user,\\n                        FlowAction.WRITE,\\n                        flow_id=flow_id,\\n                        flow_user_id=existing_flow.user_id,\\n                        workspace_id=target_workspace_id,\\n                        folder_id=target_folder_id,\\n                    )\\n                except HTTPException as exc:\\n                    raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n\\n            # Sync deployment state before folder changes\\n            # Explicit folder_id=None is ignored here because _update_existing_flow\\n            # also uses exclude_none=True for update_data.\\n            folder_id_will_change = target_folder_id != existing_flow.folder_id\\n\\n            async def update_operation() -> FlowRead:\\n                # Re-load inside each attempt so retry after nested rollback never uses an expired ORM instance.\\n                existing_flow_for_attempt = await _read_flow(\\n                    session=session,\\n                    flow_id=flow_id,\\n                    user_id=current_user.id,\\n                    for_update=True,\\n                )\\n                if existing_flow_for_attempt is None:\\n                    raise HTTPException(status_code=404, detail=\\\"Flow not found\\\")\\n                # Re-authorize the freshly loaded source and resolved\\n                # destination on every attempt. A concurrent move between the\\n                # outer check and this write must not let a shared editor carry\\n                # stale workspace permission into a different project.\\n                try:\\n                    await ensure_flow_permission(\\n                        current_user,\\n                        FlowAction.WRITE,\\n                        flow_id=flow_id,\\n                        flow_user_id=existing_flow_for_attempt.user_id,\\n                        workspace_id=existing_flow_for_attempt.workspace_id,\\n                        folder_id=existing_flow_for_attempt.folder_id,\\n                    )\\n                except HTTPException as exc:\\n                    raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n\\n                attempt_target_workspace_id, attempt_target_folder_id = await _resolve_flow_destination(\\n                    session,\\n                    existing_flow_for_attempt.user_id,\\n                    requested_folder_id,\\n                    fallback_folder_id=existing_flow_for_attempt.folder_id,\\n                    reject_invalid=requested_folder_id is not None,\\n                    authorized_existing_folder_id=existing_flow_for_attempt.folder_id,\\n                )\\n                flow.workspace_id = attempt_target_workspace_id\\n                if requested_folder_id is not None:\\n                    flow.folder_id = attempt_target_folder_id\\n                if (\\n                    attempt_target_workspace_id != existing_flow_for_attempt.workspace_id\\n                    or attempt_target_folder_id != existing_flow_for_attempt.folder_id\\n                ):\\n                    try:\\n                        await ensure_flow_permission(\\n                            current_user,\\n                            FlowAction.WRITE,\\n                            flow_id=flow_id,\\n                            flow_user_id=existing_flow_for_attempt.user_id,\\n                            workspace_id=attempt_target_workspace_id,\\n                            folder_id=attempt_target_folder_id,\\n                        )\\n                    except HTTPException as exc:\\n                        raise deny_to_404(exc, detail=\\\"Flow not found\\\") from exc\\n                effective_flow_data = flow.data if flow.data is not None else existing_flow_for_attempt.data\\n                _validate_catalog_policy_for_write(effective_flow_data, snapshot=catalog_policy_snapshot)\\n                await stage_mcp_secrets(carried_secrets, secret_variables, writer_id, session)\\n                return await _update_existing_flow(\\n                    session=session,\\n                    existing_flow=existing_flow_for_attempt,\\n                    flow=flow,\\n                    current_user=current_user,\\n                    storage_service=storage_service,\\n                )\\n\\n            if folder_id_will_change:\\n                flow_read = await retry_flow_operation_on_deployment_guard(\\n                    db=session,\\n                    flow_owner_ids={existing_flow.id: existing_flow.user_id},\\n                    operation=update_operation,\\n                )\\n            else:\\n                flow_read = await update_operation()\\n            status_code = 200\\n        else:\\n            # CREATE path - flow doesn't exist\\n            await _canonicalize_flow_destination(session, flow, current_user.id, reject_invalid=True)\\n            await ensure_flow_permission(\\n                current_user,\\n                FlowAction.CREATE,\\n                workspace_id=flow.workspace_id,\\n                folder_id=flow.folder_id,\\n                folder_user_id=await destination_folder_owner_id(session, flow.folder_id),\\n            )\\n            _validate_catalog_policy_for_write(flow.data, snapshot=catalog_policy_snapshot)\\n            await stage_mcp_secrets(carried_secrets, secret_variables, writer_id, session)\\n            flow_read = await _new_flow(\\n                session=session,\\n                flow=flow,\\n                user_id=current_user.id,\\n                storage_service=storage_service,\\n                flow_id=flow_id,\\n                fail_on_endpoint_conflict=True,\\n                validate_folder=True,\\n            )\\n            status_code = 201\\n\\n        return JSONResponse(status_code=status_code, content=jsonable_encoder(flow_read))\\n\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        await araise_if_deployment_guard_error_or_skip(\\n            e,\\n            log_message=f\\\"op=upsert_flow flow_id={flow_id}\\\",\\n        )\\n        raise _handle_unique_constraint_error(e, status_code=409) from e\\n\\n\\n@router.delete(\\\"/{flow_id}\\\", status_code=200)\\nasync def delete_flow(\\n    *,\\n    session: DbSession,\\n    flow_id: UUID,\\n    flow: AuthorizedDeleteFlow,\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Delete a flow.\\\"\\\"\\\"\\n    actor = UserRead.model_validate(current_user, from_attributes=True)\\n    target_flow_id = flow_id\\n    flow_owner_ids: dict[UUID, UUID] = {target_flow_id: flow.user_id}\\n\\n    async def _delete_attempt(_attempt: int) -> None:\\n        async def _delete_operation() -> None:\\n            flow_owner_ids.clear()\\n            retry_target = await _read_flow(session, target_flow_id, actor.id)\\n            if retry_target is None:\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Flow not found\\\")\\n            await ensure_flow_permission(\\n                actor,\\n                FlowAction.DELETE,\\n                flow_id=retry_target.id,\\n                flow_user_id=retry_target.user_id,\\n                workspace_id=retry_target.workspace_id,\\n                folder_id=retry_target.folder_id,\\n            )\\n            flow_owner_ids[retry_target.id] = retry_target.user_id\\n            if not await cascade_delete_flow(session, target_flow_id):\\n                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\\\"Flow not found\\\")\\n\\n        await retry_flow_operation_on_deployment_guard(\\n            db=session,\\n            flow_owner_ids=flow_owner_ids,\\n            operation=_delete_operation,\\n        )\\n\\n    try:\\n        await run_with_lock_retry(_delete_attempt, session=session, description=f\\\"delete_flow {target_flow_id}\\\")\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await araise_if_deployment_guard_error_or_skip(\\n            exc,\\n            log_message=f\\\"op=delete_flow flow_id={target_flow_id}\\\",\\n        )\\n        if is_database_lock_error(exc):\\n            await logger.awarning(\\\"op=delete_flow flow_id=%s exhausted lock retries\\\", target_flow_id)\\n            raise HTTPException(\\n                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n                detail=FLOW_DELETE_BUSY,\\n                headers={\\\"Retry-After\\\": \\\"1\\\"},\\n            ) from exc\\n        await logger.aerror(\\\"op=delete_flow failed with %s\\\", type(exc).__name__)\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=FLOW_DELETE_FAILED) from exc\\n    return {\\\"message\\\": \\\"Flow deleted successfully\\\"}\\n\\n\\n@router.post(\\\"/batch/\\\", response_model=list[FlowRead], status_code=201)\\nasync def create_flows(\\n    *,\\n    session: DbSession,\\n    flow_list: FlowListCreate,\\n    current_user: CurrentActiveUser,\\n):\\n    \\\"\\\"\\\"Create multiple new flows.\\\"\\\"\\\"\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n    # Validate the complete request before adding or flushing any rows. This\\n    # keeps a denial in a later item from partially applying an earlier item.\\n    for flow in flow_list.flows:\\n        _validate_catalog_policy_for_write(flow.data, snapshot=catalog_policy_snapshot)\\n        await persist_and_strip_mcp_secrets(flow.data, current_user.id, session)\\n\\n    # Resolve and authorize every flow's canonical project/workspace instead of\\n    # trusting caller-supplied denormalized scope fields.\\n    for flow in flow_list.flows:\\n        await _canonicalize_flow_destination(session, flow, current_user.id)\\n        await ensure_flow_permission(\\n            current_user,\\n            FlowAction.CREATE,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n            folder_user_id=await destination_folder_owner_id(session, flow.folder_id),\\n        )\\n    # Guard against duplicate IDs up-front so callers get a clean 422 instead\\n    # of an unhandled DB IntegrityError.  Use upload_file() for upsert semantics.\\n    requested_ids = [f.id for f in flow_list.flows if f.id is not None]\\n    if requested_ids:\\n        existing_ids = (await session.exec(select(Flow.id).where(col(Flow.id).in_(requested_ids)))).all()\\n        if existing_ids:\\n            conflict = \\\", \\\".join(str(i) for i in existing_ids)\\n            msg = (\\n                f\\\"Flow(s) with the following IDs already exist: {conflict}. \\\"\\n                \\\"Use the update endpoint or upload_file() for upsert semantics.\\\"\\n            )\\n            raise HTTPException(status_code=422, detail=msg)\\n\\n    db_flows = []\\n    for flow in flow_list.flows:\\n        flow.user_id = current_user.id\\n        # Exclude id from model_validate (same reasoning as _new_flow) and apply separately.\\n        db_flow = Flow.model_validate(flow.model_dump(exclude={\\\"id\\\"}))\\n        if flow.id is not None:\\n            db_flow.id = flow.id\\n        await _validate_and_assign_folder(session, db_flow, current_user.id)\\n        session.add(db_flow)\\n        db_flows.append(db_flow)\\n\\n    # Unlike create_flow/upsert_flow, this endpoint does not route through\\n    # _new_flow, so a (user_id, name)/(user_id, endpoint_name) collision reaches\\n    # the flush unhandled. Left un-rolled-back on SQLite, the failed INSERT pins\\n    # the write lock and the next writer busy-waits busy_timeout (30s) before its\\n    # own \\\"database is locked\\\"; the raw error would also leak the SQL statement\\n    # and bound parameters. Roll back to release the lock immediately, then map\\n    # to a clean 409.\\n    try:\\n        await session.flush()\\n    except IntegrityError as exc:\\n        await session.rollback()\\n        raise _handle_unique_constraint_error(exc, status_code=409) from exc\\n    for db_flow in db_flows:\\n        await session.refresh(db_flow)\\n\\n    return [FlowRead.model_validate(db_flow, from_attributes=True) for db_flow in db_flows]\\n\\n\\n@router.post(\\\"/upload/\\\", response_model=list[FlowRead], status_code=201)\\nasync def upload_file(\\n    *,\\n    session: DbSession,\\n    file: Annotated[UploadFile | None, File()] = None,\\n    current_user: CurrentActiveUser,\\n    folder_id: UUID | None = None,\\n    storage_service: Annotated[StorageService, Depends(get_storage_service)],\\n):\\n    \\\"\\\"\\\"Upload flows from a JSON or ZIP file (upsert semantics for flows with stable IDs).\\\"\\\"\\\"\\n    # Authorization is enforced per-flow below, after parsing \u2014 the per-flow\\n    # check uses the actual workspace_id/folder_id each uploaded flow targets.\\n    # A coarse pre-parse check here would over-reject (it would authorize the\\n    # caller against ``domain=\\\"*\\\", obj=\\\"flow:*\\\"`` regardless of where the\\n    # uploaded flows actually land).\\n    if file is None:\\n        raise HTTPException(status_code=400, detail=\\\"No file provided\\\")\\n\\n    contents = await file.read()\\n\\n    if not contents:\\n        raise HTTPException(status_code=400, detail=\\\"The uploaded file is empty\\\")\\n\\n    if zipfile.is_zipfile(io.BytesIO(contents)):\\n        try:\\n            flows_data = await extract_flows_from_zip(contents)\\n        except ValueError as e:\\n            raise HTTPException(status_code=400, detail=str(e)) from e\\n        if not flows_data:\\n            raise HTTPException(status_code=400, detail=\\\"No valid flow JSON files found in the ZIP\\\")\\n        data = {\\\"flows\\\": flows_data}\\n    else:\\n        try:\\n            data = orjson.loads(contents)\\n        except orjson.JSONDecodeError as e:\\n            raise HTTPException(status_code=400, detail=f\\\"Invalid JSON file: {e}\\\") from e\\n\\n    # Normalise code fields: if exported with code-as-lines format, rejoin to\\n    # strings before creating the Pydantic models so the DB always stores strings.\\n    if not isinstance(data, dict):\\n        raise HTTPException(\\n            status_code=422,\\n            detail=\\\"Invalid JSON: expected an object with 'flows' or a single flow object\\\",\\n        )\\n    try:\\n        if \\\"flows\\\" in data:\\n            if not isinstance(data[\\\"flows\\\"], list):\\n                raise HTTPException(\\n                    status_code=422,\\n                    detail=\\\"Invalid JSON: 'flows' must be a list of flow objects\\\",\\n                )\\n            non_dict = [i for i, f in enumerate(data[\\\"flows\\\"]) if not isinstance(f, dict)]\\n            if non_dict:\\n                raise HTTPException(\\n                    status_code=422,\\n                    detail=f\\\"Invalid JSON: flows[{non_dict[0]}] is not an object\\\",\\n                )\\n            data = {**data, \\\"flows\\\": [normalize_code_for_import(f) for f in data[\\\"flows\\\"]]}\\n            flow_list = FlowListCreate(**data)\\n        else:\\n            flow_list = FlowListCreate(flows=[FlowCreate(**normalize_code_for_import(data))])\\n    except HTTPException:\\n        raise\\n    except ValidationError as e:\\n        raise HTTPException(status_code=422, detail=str(e)) from e\\n\\n    # TODO: Full-version import is planned as a follow-up feature.\\n    # When implemented, extract raw flow dicts here to read embedded \\\"version\\\"\\n    # arrays and create FlowVersion entries for each imported flow.\\n\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n\\n    requested_id_list = [flow.id for flow in flow_list.flows if flow.id is not None]\\n    requested_ids = set(requested_id_list)\\n    if len(requested_ids) != len(requested_id_list):\\n        raise HTTPException(status_code=422, detail=\\\"Invalid upload: duplicate flow IDs are not allowed\\\")\\n\\n    # Lock only rows this request can update. Missing IDs remain classified as\\n    # creates for the whole request; if one appears concurrently, the planned\\n    # insert conflicts instead of silently becoming an unvalidated update.\\n    owned_existing_flows_by_id: dict[UUID, Flow] = {}\\n    foreign_existing_ids: set[UUID] = set()\\n    if requested_ids:\\n        owned_existing_flows = (\\n            await session.exec(\\n                select(Flow).where(col(Flow.id).in_(requested_ids), Flow.user_id == current_user.id).with_for_update()\\n            )\\n        ).all()\\n        owned_existing_flows_by_id = {existing_flow.id: existing_flow for existing_flow in owned_existing_flows}\\n        remaining_ids = requested_ids - owned_existing_flows_by_id.keys()\\n        if remaining_ids:\\n            other_existing_flows = (await session.exec(select(Flow).where(col(Flow.id).in_(remaining_ids)))).all()\\n            foreign_existing_ids = {\\n                existing_flow.id for existing_flow in other_existing_flows if existing_flow.user_id != current_user.id\\n            }\\n\\n    # Per-flow CREATE check on the effective canonical destination. For owned\\n    # upserts with no destination in the payload, preserve the existing project;\\n    # new or stale destinations fall back to the user's default project.\\n    for flow in flow_list.flows:\\n        fallback_folder_id = None\\n        existing_flow = owned_existing_flows_by_id.get(flow.id) if flow.id is not None else None\\n        if folder_id is not None:\\n            flow.folder_id = folder_id\\n        elif flow.folder_id is None and existing_flow is not None and existing_flow.user_id == current_user.id:\\n            fallback_folder_id = existing_flow.folder_id\\n        await _canonicalize_flow_destination(\\n            session,\\n            flow,\\n            current_user.id,\\n            fallback_folder_id=fallback_folder_id,\\n            authorized_existing_folder_id=existing_flow.folder_id if existing_flow is not None else None,\\n        )\\n        await ensure_flow_permission(\\n            current_user,\\n            FlowAction.CREATE,\\n            workspace_id=flow.workspace_id,\\n            folder_id=flow.folder_id,\\n            folder_user_id=await destination_folder_owner_id(session, flow.folder_id),\\n        )\\n\\n        # Upload upserts ignore omitted/null data. Validate the stored graph in\\n        # that case so a metadata-only write cannot bypass a newly blocked\\n        # component. Rows owned by another user are copied as new flows and do\\n        # not inherit that user's stored graph.\\n        effective_flow_data = flow.data\\n        if effective_flow_data is None and existing_flow is not None and existing_flow.user_id == current_user.id:\\n            effective_flow_data = existing_flow.data\\n        _validate_catalog_policy_for_write(effective_flow_data, snapshot=catalog_policy_snapshot)\\n        await persist_and_strip_mcp_secrets(flow.data, current_user.id, session)\\n\\n    try:\\n        flow_reads: list[FlowRead] = []\\n        for flow in flow_list.flows:\\n            flow.user_id = current_user.id\\n            stable_id = flow.id\\n            existing_flow = owned_existing_flows_by_id.get(stable_id) if stable_id is not None else None\\n            if existing_flow is not None:\\n                flow_read = await _update_existing_flow(\\n                    session=session,\\n                    existing_flow=existing_flow,\\n                    flow=flow,\\n                    current_user=current_user,\\n                    storage_service=storage_service,\\n                )\\n            elif stable_id is not None and stable_id in foreign_existing_ids:\\n                flow.id = None\\n                flow_read = await _new_flow(\\n                    session=session,\\n                    flow=flow,\\n                    user_id=current_user.id,\\n                    storage_service=storage_service,\\n                )\\n            else:\\n                flow_read = await _new_flow(\\n                    session=session,\\n                    flow=flow,\\n                    user_id=current_user.id,\\n                    storage_service=storage_service,\\n                    flow_id=stable_id,\\n                )\\n            flow_reads.append(flow_read)\\n    except HTTPException:\\n        raise\\n    except Exception as e:\\n        raise _handle_unique_constraint_error(e) from e\\n    else:\\n        return flow_reads\\n\\n\\n@router.delete(\\\"/\\\")\\nasync def delete_multiple_flows(\\n    flow_ids: list[UUID],\\n    user: CurrentActiveUser,\\n    db: DbSession,\\n):\\n    \\\"\\\"\\\"Delete multiple flows by their IDs.\\\"\\\"\\\"\\n    actor = UserRead.model_validate(user, from_attributes=True)\\n    try:\\n        authorized_flow_owner_ids: dict[UUID, UUID] = {}\\n\\n        async def _delete_operation() -> int:\\n            authorized_flow_owner_ids.clear()\\n            if not flow_ids:\\n                return 0\\n            # Widen fetch when cross-user DELETE is supported; else owner-scoped.\\n            from langflow.services.deps import get_authorization_service\\n\\n            authz = get_authorization_service()\\n            base_stmt = select(Flow).where(col(Flow.id).in_(flow_ids))\\n            if await authz.supports_cross_user_fetch() and await authz.is_enabled():\\n                stmt = base_stmt\\n            else:\\n                stmt = base_stmt.where(Flow.user_id == actor.id)\\n            flows_to_delete = (await db.exec(stmt)).all()\\n            for flow in flows_to_delete:\\n                # Propagate plugin deny (403) so bulk delete fails audibly.\\n                await ensure_flow_permission(\\n                    actor,\\n                    FlowAction.DELETE,\\n                    flow_id=flow.id,\\n                    flow_user_id=flow.user_id,\\n                    workspace_id=flow.workspace_id,\\n                    folder_id=flow.folder_id,\\n                )\\n            authorized_flow_owner_ids.update((flow.id, flow.user_id) for flow in flows_to_delete)\\n            deleted = 0\\n            for flow in flows_to_delete:\\n                if await cascade_delete_flow(db, flow.id):\\n                    deleted += 1\\n            await db.flush()\\n            return deleted\\n\\n        async def _delete_attempt(_attempt: int) -> int:\\n            return await retry_flow_operation_on_deployment_guard(\\n                db=db,\\n                flow_owner_ids=authorized_flow_owner_ids,\\n                operation=_delete_operation,\\n            )\\n\\n        deleted_count = await run_with_lock_retry(\\n            _delete_attempt,\\n            session=db,\\n            description=f\\\"delete_multiple_flows count={len(flow_ids)}\\\",\\n        )\\n    except HTTPException:\\n        raise\\n    except Exception as exc:\\n        await araise_if_deployment_guard_error_or_skip(\\n            exc,\\n            log_message=f\\\"op=delete_multiple_flows flow_ids_count={len(flow_ids)}\\\",\\n        )\\n        if is_database_lock_error(exc):\\n            await logger.awarning(\\\"op=delete_multiple_flows flow_ids_count=%s exhausted lock retries\\\", len(flow_ids))\\n            raise HTTPException(\\n                status_code=status.HTTP_503_SERVICE_UNAVAILABLE,\\n                detail=FLOW_DELETE_BUSY,\\n                headers={\\\"Retry-After\\\": \\\"1\\\"},\\n            ) from exc\\n        await logger.aerror(\\n            \\\"op=delete_multiple_flows flow_ids_count=%s failed with %s\\\", len(flow_ids), type(exc).__name__\\n        )\\n        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail=FLOW_DELETE_FAILED) from exc\\n\\n    return {\\\"deleted\\\": deleted_count}\\n\\n\\n@router.post(\\\"/download/\\\", status_code=200)\\nasync def download_multiple_file(\\n    flow_ids: list[UUID],\\n    user: CurrentActiveUser,\\n    db: DbSession,\\n):\\n    \\\"\\\"\\\"Download all flows as a zip file.\\\"\\\"\\\"\\n    # TODO: Full-version download (include_version parameter) is planned as a follow-up feature.\\n    # When implemented, add an include_version: bool = False parameter and embed version\\n    # entries in each flow dict using get_flow_versions_with_provider_status and strip_version_data.\\n    # Widen fetch when cross-user READ is supported; else owner-scoped.\\n    from langflow.services.deps import get_authorization_service\\n\\n    authz = get_authorization_service()\\n    base_stmt = select(Flow).where(col(Flow.id).in_(flow_ids))  # type: ignore[attr-defined]\\n    if await authz.supports_cross_user_fetch() and await authz.is_enabled():\\n        stmt = base_stmt\\n    else:\\n        stmt = base_stmt.where(and_(Flow.user_id == user.id))\\n    flows = (await db.exec(stmt)).all()\\n\\n    if not flows:\\n        raise HTTPException(status_code=404, detail=\\\"No flows found.\\\")\\n\\n    for flow in flows:\\n        # Plugin deny \u2192 404 (UUID privacy).\\n        try:\\n            await ensure_flow_permission(\\n                user,\\n                FlowAction.READ,\\n                flow_id=flow.id,\\n                flow_user_id=flow.user_id,\\n                workspace_id=flow.workspace_id,\\n                folder_id=flow.folder_id,\\n            )\\n        except HTTPException as exc:\\n            raise deny_to_404(exc, detail=\\\"No flows found.\\\") from exc\\n\\n    return _build_flows_download_response(flows)\\n\\n\\n# 5 minutes\\n_STARTER_FLOWS_TTL_SECONDS: float = 300.0\\n_starter_flows_cache: ThreadingInMemoryCache[threading.RLock] = ThreadingInMemoryCache(\\n    max_size=1,\\n    expiration_time=int(_STARTER_FLOWS_TTL_SECONDS),\\n)\\n_starter_flows_translated_cache: ThreadingInMemoryCache[threading.RLock] = ThreadingInMemoryCache(\\n    max_size=16,  # Why: 16 > 7 current supported locales, leaves headroom for future additions\\n    expiration_time=int(_STARTER_FLOWS_TTL_SECONDS),\\n)\\n_starter_flows_lock = asyncio.Lock()\\n\\n\\ndef _filter_basic_examples_by_catalog_policy(\\n    flows: list[FlowRead],\\n    *,\\n    blocked_template_keys: Collection[str],\\n) -> list[FlowRead]:\\n    \\\"\\\"\\\"Return a request-local view without exact blocked template keys.\\\"\\\"\\\"\\n    return [flow for flow in flows if flow.name_key not in blocked_template_keys]\\n\\n\\n@router.get(\\\"/basic_examples/\\\", response_model=list[FlowRead], status_code=200)\\nasync def read_basic_examples(\\n    *,\\n    session: DbSession,\\n    request: Request,\\n    user: Annotated[User | None, Depends(get_optional_user)],\\n    include_blocked: bool = False,\\n):\\n    \\\"\\\"\\\"Retrieve a list of basic example flows.\\\"\\\"\\\"\\n    if include_blocked and (user is None or not user.is_superuser):\\n        raise HTTPException(\\n            status_code=403,\\n            detail=\\\"Only superusers can include blocked catalog templates.\\\",\\n        )\\n\\n    catalog_policy_snapshot = get_catalog_policy_service().snapshot\\n    locale = getattr(request.state, \\\"locale\\\", \\\"en\\\")\\n    translated_cache_key = f\\\"starter_flows_{locale}\\\"\\n\\n    # Fast path: translated result already cached for this locale\\n    cached_translated = _starter_flows_translated_cache.get(translated_cache_key)\\n    if cached_translated is not CACHE_MISS:\\n        visible_flows = (\\n            cached_translated\\n            if include_blocked\\n            else _filter_basic_examples_by_catalog_policy(\\n                cached_translated,\\n                blocked_template_keys=catalog_policy_snapshot.blocked_template_keys,\\n            )\\n        )\\n        return compress_response(visible_flows)\\n\\n    async with _starter_flows_lock:\\n        # Double-check inside lock to prevent thundering herd\\n        cached_translated = _starter_flows_translated_cache.get(translated_cache_key)\\n        if cached_translated is not CACHE_MISS:\\n            visible_flows = (\\n                cached_translated\\n                if include_blocked\\n                else _filter_basic_examples_by_catalog_policy(\\n                    cached_translated,\\n                    blocked_template_keys=catalog_policy_snapshot.blocked_template_keys,\\n                )\\n            )\\n            return compress_response(visible_flows)\\n\\n        # Ensure raw DB data is cached\\n        cached_flow_reads = _starter_flows_cache.get(\\\"starter_flows\\\")\\n        if cached_flow_reads is CACHE_MISS:\\n            try:\\n                starter_folder = (\\n                    await session.exec(\\n                        select(Folder).where(Folder.name == STARTER_FOLDER_NAME, Folder.user_id.is_(None))\\n                    )\\n                ).first()\\n\\n                if not starter_folder:\\n                    return compress_response([])\\n\\n                all_starter_folder_flows = (\\n                    await session.exec(select(Flow).where(Flow.folder_id == starter_folder.id))\\n                ).all()\\n\\n                cached_flow_reads = [\\n                    FlowRead.model_validate(flow, from_attributes=True) for flow in all_starter_folder_flows\\n                ]\\n                _starter_flows_cache.set(\\\"starter_flows\\\", cached_flow_reads)\\n\\n            except Exception as e:\\n                import logging as _logging\\n\\n                _logging.getLogger(__name__).exception(\\\"Error loading basic examples\\\")\\n                raise HTTPException(status_code=500, detail=\\\"An internal error occurred while loading examples.\\\") from e\\n\\n        # Translate once per locale and cache the result\\n        # Why: cached uncompressed so the same result can be re-compressed per\\n        # response \u2014 keeps locale-switching working without storing per-locale\\n        # compressed blobs.\\n        translated = translate_starter_flows(cached_flow_reads, locale)\\n        result = []\\n        for flow in translated:\\n            flow_copy = flow.model_copy()\\n            if flow_copy.data and isinstance(flow_copy.data, dict):\\n                nodes = flow_copy.data.get(\\\"nodes\\\", [])\\n                translated_nodes = translate_flow_notes(nodes, locale)\\n                flow_copy.data = {**flow_copy.data, \\\"nodes\\\": translated_nodes}\\n            result.append(flow_copy)\\n\\n        _starter_flows_translated_cache.set(translated_cache_key, result)\\n\\n    visible_flows = (\\n        result\\n        if include_blocked\\n        else _filter_basic_examples_by_catalog_policy(\\n            result,\\n            blocked_template_keys=catalog_policy_snapshot.blocked_template_keys,\\n        )\\n    )\\n    return compress_response(visible_flows)\\n\\n\\n@router.post(\\\"/expand/\\\", status_code=200, dependencies=[Depends(get_current_active_user)], include_in_schema=False)\\nasync def expand_compact_flow_endpoint(\\n    compact_data: dict,\\n):\\n    \\\"\\\"\\\"Expand a compact flow format (minimal nodes/edges) to the full flow format.\\\"\\\"\\\"\\n    from lfx.interface.components import component_cache, get_and_cache_all_types_dict\\n\\n    from langflow.processing.expand_flow import expand_compact_flow\\n\\n    # Ensure component cache is loaded\\n    if component_cache.all_types_dict is None:\\n        settings_service = get_settings_service()\\n        await get_and_cache_all_types_dict(settings_service)\\n\\n    if component_cache.all_types_dict is None:\\n        raise HTTPException(status_code=500, detail=\\\"Component cache not initialized\\\")\\n\\n    try:\\n        return expand_compact_flow(compact_data, component_cache.all_types_dict)\\n    except ValueError as e:\\n        raise HTTPException(status_code=400, detail=str(e)) from e\\n    except Exception as e:\\n        raise HTTPException(status_code=500, detail=str(e)) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/base/langflow/api/v1/flows_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a1c202a3f3f67ef852c8ed8ca37be79b40642aab22548cf4a721fa6b4aed565\",\"content\":\"\\\"\\\"\\\"Helper functions for flow CRUD and filesystem operations.\\n\\nExtracted from flows.py to keep the route-handler module concise.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport io\\nimport os\\nimport re\\nimport zipfile\\nfrom datetime import datetime, timezone\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nimport aiofiles\\nfrom anyio import Path\\nfrom fastapi import HTTPException\\nfrom fastapi.responses import StreamingResponse\\nfrom lfx.log import logger\\nfrom pydantic import ValidationError\\nfrom sqlmodel import select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\nfrom langflow.api.utils import (\\n    build_content_disposition,\\n    normalize_flow_for_export,\\n    remove_api_keys,\\n    strip_flow_secrets,\\n)\\nfrom langflow.services.authorization.fetch import authorized_or_owner_scoped\\nfrom langflow.services.database.models.base import orjson_dumps\\nfrom langflow.services.database.models.deployment.orm_guards import ensure_flow_move_allowed\\nfrom langflow.services.database.models.flow.guards import (\\n    LockedFlowError,\\n    ensure_flow_update_allowed,\\n    lock_flow_for_update,\\n)\\nfrom langflow.services.database.models.flow.model import (\\n    Flow,\\n    FlowCreate,\\n    FlowRead,\\n    FlowUpdate,\\n)\\nfrom langflow.services.database.models.flow.utils import get_webhook_component_in_flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.database.models.folder.utils import get_default_folder_id\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.services.storage.service import StorageService\\n\\nif TYPE_CHECKING:\\n    from langflow.services.database.models.user.model import User\\n\\n\\ndef _get_safe_flow_path(fs_path: str, user_id: UUID, storage_service: StorageService) -> Path:\\n    \\\"\\\"\\\"Get a safe filesystem path for flow storage, restricted to user's flows directory.\\n\\n    Allows both absolute and relative paths, but ensures they're within the user's flows directory.\\n\\n    Uses ``os.path.realpath`` + ``startswith`` for containment \u2014 the sanitiser pattern\\n    recognised by CodeQL's ``py/path-injection`` analysis. ``realpath`` canonicalises\\n    the path and follows symlinks, so the returned path is safe to pass to filesystem\\n    operations.\\n    \\\"\\\"\\\"\\n    if not fs_path:\\n        raise HTTPException(status_code=400, detail=\\\"fs_path cannot be empty\\\")\\n\\n    # Normalize path separators first (before security checks to prevent backslash bypass)\\n    normalized_path = fs_path.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n\\n    # Reject directory traversal and null bytes (check normalized path)\\n    if \\\"..\\\" in normalized_path:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=\\\"Invalid fs_path: directory traversal (..) is not allowed\\\",\\n        )\\n    if \\\"\\\\x00\\\" in normalized_path:\\n        raise HTTPException(\\n            status_code=400,\\n            detail=\\\"Invalid fs_path: null bytes are not allowed\\\",\\n        )\\n\\n    # Build and canonicalise the safe base directory path.\\n    base_dir = storage_service.data_dir / \\\"flows\\\" / str(user_id)\\n    try:\\n        base_dir_resolved = os.path.realpath(str(base_dir))\\n    except (OSError, ValueError) as e:\\n        raise HTTPException(status_code=400, detail=f\\\"Invalid base directory: {e}\\\") from e\\n\\n    # Determine if path is absolute (Unix or Windows style)\\n    is_absolute = normalized_path.startswith(\\\"/\\\") or (len(normalized_path) > 1 and normalized_path[1] == \\\":\\\")\\n\\n    if is_absolute:\\n        candidate = normalized_path\\n    else:\\n        relative_part = normalized_path.lstrip(\\\"/\\\")\\n        # os.path.join is deliberate here (PTH118) to match CodeQL's sanitiser model.\\n        candidate = os.path.join(base_dir_resolved, relative_part) if relative_part else base_dir_resolved  # noqa: PTH118\\n\\n    try:\\n        resolved_str = os.path.realpath(candidate)\\n    except (OSError, ValueError) as e:\\n        raise HTTPException(status_code=400, detail=f\\\"Invalid path: {e}\\\") from e\\n\\n    # SECURITY: containment check using os.path.realpath + startswith (CodeQL-recognised).\\n    if resolved_str != base_dir_resolved and not resolved_str.startswith(base_dir_resolved + os.sep):\\n        if is_absolute:\\n            raise HTTPException(\\n                status_code=400,\\n                detail=\\\"Absolute path must be within your flows directory\\\",\\n            )\\n        raise HTTPException(\\n            status_code=400,\\n            detail=\\\"Invalid path: resolves outside allowed directory\\\",\\n        )\\n\\n    # Return the canonicalised path \u2014 safe for subsequent filesystem operations.\\n    return Path(resolved_str)\\n\\n\\n# Fields that may be updated via setattr on a Flow ORM instance.\\n# Any key not in this set is silently dropped to prevent callers from\\n# overwriting internal fields (e.g. ``id``, ``user_id``).\\n_UPDATABLE_FLOW_FIELDS: frozenset[str] = frozenset(\\n    {\\n        \\\"name\\\",\\n        \\\"description\\\",\\n        \\\"data\\\",\\n        \\\"is_component\\\",\\n        \\\"endpoint_name\\\",\\n        \\\"tags\\\",\\n        \\\"folder_id\\\",\\n        # ``workspace_id`` is part of the FlowUpdate / FlowCreate contract and\\n        # the PATCH/PUT routes re-authorize WRITE at the destination scope when\\n        # the payload changes it (see flows.py). Omitting it here would silently\\n        # accept the payload, pass the authorization check, and then drop the\\n        # write \u2014 leaving the flow in its old workspace despite the API saying\\n        # the move succeeded.\\n        \\\"workspace_id\\\",\\n        \\\"icon\\\",\\n        \\\"icon_bg_color\\\",\\n        \\\"gradient\\\",\\n        \\\"locked\\\",\\n        \\\"mcp_enabled\\\",\\n        \\\"flow_type\\\",\\n        \\\"a2a_enabled\\\",\\n        \\\"a2a_card_overrides\\\",\\n        \\\"action_name\\\",\\n        \\\"action_description\\\",\\n        \\\"access_type\\\",\\n        \\\"fs_path\\\",\\n    }\\n)\\n\\n\\ndef _apply_update_data(target: Flow, update_data: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Apply *update_data* to the ORM *target*, restricted to the allowlist.\\\"\\\"\\\"\\n    for key, value in update_data.items():\\n        if key in _UPDATABLE_FLOW_FIELDS:\\n            setattr(target, key, value)\\n\\n\\ndef _endpoint_name_was_explicitly_cleared(flow: FlowCreate | FlowUpdate) -> bool:\\n    \\\"\\\"\\\"Return whether the request explicitly asked to clear the endpoint name.\\\"\\\"\\\"\\n    return \\\"endpoint_name\\\" in flow.model_fields_set and flow.endpoint_name in (None, \\\"\\\")\\n\\n\\ndef _ensure_api_flow_update_allowed(db_flow: Flow, update_data: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Translate the domain lock guard into the API's 423 response.\\\"\\\"\\\"\\n    try:\\n        ensure_flow_update_allowed(db_flow, update_data)\\n    except LockedFlowError as exc:\\n        raise HTTPException(status_code=423, detail=str(exc)) from exc\\n\\n\\nasync def _verify_fs_path(path: str | None, user_id: UUID, storage_service: StorageService) -> None:\\n    \\\"\\\"\\\"Verify and prepare the filesystem path for flow storage.\\\"\\\"\\\"\\n    if path is not None:\\n        # Empty strings should be rejected (None is allowed, empty string is not)\\n        if path == \\\"\\\":\\n            raise HTTPException(status_code=400, detail=\\\"fs_path cannot be empty\\\")\\n        safe_path = _get_safe_flow_path(path, user_id, storage_service)\\n        await safe_path.parent.mkdir(parents=True, exist_ok=True)\\n        if not await safe_path.exists():\\n            await safe_path.touch()\\n\\n\\nasync def _save_flow_to_fs(flow: Flow, user_id: UUID, storage_service: StorageService) -> None:\\n    \\\"\\\"\\\"Save flow data to the filesystem at the validated path.\\\"\\\"\\\"\\n    if not flow.fs_path:\\n        return\\n\\n    try:\\n        safe_path = _get_safe_flow_path(flow.fs_path, user_id, storage_service)\\n        await safe_path.parent.mkdir(parents=True, exist_ok=True)\\n        async with aiofiles.open(str(safe_path), \\\"w\\\") as f:\\n            await f.write(flow.model_dump_json())\\n    except HTTPException:\\n        raise\\n    except OSError as e:\\n        await logger.aexception(\\\"Failed to write flow %s to path %s\\\", flow.name, flow.fs_path)\\n        raise HTTPException(status_code=500, detail=f\\\"Failed to write flow to filesystem: {e}\\\") from e\\n\\n\\nasync def _deduplicate_flow_name(session: AsyncSession, name: str, user_id: UUID) -> str:\\n    \\\"\\\"\\\"Return a unique flow name for *user_id*, appending ``(N)`` if needed.\\\"\\\"\\\"\\n    if not (await session.exec(select(Flow).where(Flow.name == name).where(Flow.user_id == user_id))).first():\\n        return name\\n\\n    flows = (\\n        await session.exec(\\n            select(Flow).where(Flow.name.like(f\\\"{name} (%\\\")).where(Flow.user_id == user_id)  # type: ignore[attr-defined]\\n        )\\n    ).all()\\n\\n    # Extract copy-number suffixes: \\\"MyFlow (2)\\\" \u2192 2\\n    extract_number = re.compile(rf\\\"^{re.escape(name)} \\\\((\\\\d+)\\\\)$\\\")\\n    numbers = [int(m.group(1)) for f in flows if (m := extract_number.search(f.name))]\\n\\n    return f\\\"{name} ({max(numbers) + 1})\\\" if numbers else f\\\"{name} (1)\\\"\\n\\n\\nasync def _deduplicate_endpoint_name(\\n    session: AsyncSession,\\n    endpoint_name: str,\\n    user_id: UUID,\\n    *,\\n    fail_on_conflict: bool = False,\\n) -> str:\\n    \\\"\\\"\\\"Return a unique endpoint name for *user_id*, appending ``-N`` if needed.\\n\\n    Raises :class:`HTTPException` 409 when *fail_on_conflict* is ``True`` and\\n    the name already exists.\\n    \\\"\\\"\\\"\\n    existing = (\\n        await session.exec(select(Flow).where(Flow.endpoint_name == endpoint_name).where(Flow.user_id == user_id))\\n    ).first()\\n    if not existing:\\n        return endpoint_name\\n\\n    if fail_on_conflict:\\n        raise HTTPException(status_code=409, detail=\\\"Endpoint name must be unique\\\")\\n\\n    flows = (\\n        await session.exec(\\n            select(Flow)\\n            .where(Flow.endpoint_name.like(f\\\"{endpoint_name}-%\\\"))  # type: ignore[union-attr]\\n            .where(Flow.user_id == user_id)\\n        )\\n    ).all()\\n\\n    numbers: list[int] = []\\n    for f in flows:\\n        try:\\n            numbers.append(int(f.endpoint_name.split(\\\"-\\\")[-1]))\\n        except ValueError:\\n            continue\\n\\n    next_num = (max(numbers) + 1) if numbers else 1\\n    return f\\\"{endpoint_name}-{next_num}\\\"\\n\\n\\nasync def _validate_and_assign_folder(\\n    session: AsyncSession,\\n    db_flow: Flow,\\n    user_id: UUID,\\n    *,\\n    widen_for_authz: bool = False,\\n    authorized_existing_folder_id: UUID | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Ensure *db_flow* has a valid permission-guarded destination project.\\n\\n    The OSS path falls back to the user's default project when the current\\n    ``folder_id`` is missing or not owned. Cross-user authorization plugins may\\n    preserve a foreign-owned project that the route already authorized.\\n    \\\"\\\"\\\"\\n    old_folder_id = db_flow.folder_id\\n    # no_autoflush prevents the guard query (ensure_flow_move_allowed)\\n    # from flushing the in-progress folder_id mutation before the guard\\n    # has validated it.\\n    with session.no_autoflush:\\n        await _canonicalize_flow_destination(\\n            session,\\n            db_flow,\\n            user_id,\\n            reject_invalid=db_flow.folder_id is not None,\\n            widen_for_authz=widen_for_authz,\\n            authorized_existing_folder_id=authorized_existing_folder_id,\\n        )\\n        await ensure_flow_move_allowed(\\n            session,\\n            flow_id=db_flow.id,\\n            old_folder_id=old_folder_id,\\n            new_folder_id=db_flow.folder_id,\\n        )\\n\\n\\nasync def _get_flow_destination_folder(\\n    session: AsyncSession,\\n    user_id: UUID,\\n    folder_id: UUID,\\n    *,\\n    widen_for_authz: bool = False,\\n    authorized_existing_folder_id: UUID | None = None,\\n) -> Folder | None:\\n    \\\"\\\"\\\"Load a non-system project using authorization-aware owner scoping.\\\"\\\"\\\"\\n    if folder_id == authorized_existing_folder_id:\\n        # The exact current folder came from an already-authorized flow row.\\n        # Preserve it for in-place edits without widening a requested move.\\n        folder = (await session.exec(select(Folder).where(Folder.id == folder_id))).first()\\n    elif widen_for_authz:\\n        folder = await authorized_or_owner_scoped(\\n            session,\\n            Folder,\\n            id_column=Folder.id,\\n            resource_id=folder_id,\\n            owner_column=Folder.user_id,\\n            owner_id=user_id,\\n        )\\n    else:\\n        folder = (await session.exec(select(Folder).where(Folder.id == folder_id, Folder.user_id == user_id))).first()\\n    # Ownerless folders are system-managed and are never valid write targets.\\n    return folder if folder is not None and folder.user_id is not None else None\\n\\n\\nasync def _resolve_flow_destination(\\n    session: AsyncSession,\\n    user_id: UUID,\\n    requested_folder_id: UUID | None,\\n    *,\\n    fallback_folder_id: UUID | None = None,\\n    reject_invalid: bool = False,\\n    widen_for_authz: bool = False,\\n    authorized_existing_folder_id: UUID | None = None,\\n) -> tuple[UUID | None, UUID]:\\n    \\\"\\\"\\\"Resolve the folder/workspace tuple that a flow write will actually use.\\n\\n    Folder membership is canonical. When ``widen_for_authz`` is set, an enabled\\n    authorization plugin that supports cross-user fetch may resolve a project\\n    owned by another user so the caller's permission check can decide access.\\n    The default path remains owner-scoped. A missing or stale caller folder keeps\\n    the established API behavior of falling back to the user's default folder,\\n    but callers must authorize this resolved tuple before writing.\\n    \\\"\\\"\\\"\\n    folder_id = requested_folder_id if requested_folder_id is not None else fallback_folder_id\\n    folder = None\\n    if folder_id is not None:\\n        folder = await _get_flow_destination_folder(\\n            session,\\n            user_id,\\n            folder_id,\\n            widen_for_authz=widen_for_authz,\\n            authorized_existing_folder_id=authorized_existing_folder_id,\\n        )\\n        if folder is None and requested_folder_id is not None and reject_invalid:\\n            raise HTTPException(status_code=400, detail=\\\"Folder not found\\\")\\n    if folder is None:\\n        default_folder_id = await get_default_folder_id(session, user_id)\\n        folder = (\\n            await session.exec(select(Folder).where(Folder.id == default_folder_id, Folder.user_id == user_id))\\n        ).first()\\n    if folder is None:\\n        raise HTTPException(status_code=400, detail=\\\"Folder not found\\\")\\n    return folder.workspace_id, folder.id\\n\\n\\nasync def destination_folder_owner_id(session: AsyncSession, folder_id: UUID | None) -> UUID | None:\\n    \\\"\\\"\\\"Return who owns the project a flow is about to be created in.\\n\\n    A flow being created has no owner yet, so the destination project is the\\n    only ownership the CREATE check can consult. Read it from the stored row\\n    after canonicalization \u2014 a caller-supplied folder_id may have been\\n    redirected to the caller's default project, and the payload can never be\\n    trusted to assert who owns a project.\\n    \\\"\\\"\\\"\\n    if folder_id is None:\\n        return None\\n    folder = await session.get(Folder, folder_id)\\n    return getattr(folder, \\\"user_id\\\", None)\\n\\n\\nasync def _canonicalize_flow_destination(\\n    session: AsyncSession,\\n    flow: Flow | FlowCreate | FlowUpdate,\\n    user_id: UUID,\\n    *,\\n    fallback_folder_id: UUID | None = None,\\n    reject_invalid: bool = False,\\n    widen_for_authz: bool = False,\\n    authorized_existing_folder_id: UUID | None = None,\\n) -> tuple[UUID | None, UUID]:\\n    \\\"\\\"\\\"Apply the canonical destination tuple to a flow payload or row.\\\"\\\"\\\"\\n    workspace_id, folder_id = await _resolve_flow_destination(\\n        session,\\n        user_id,\\n        flow.folder_id,\\n        fallback_folder_id=fallback_folder_id,\\n        reject_invalid=reject_invalid,\\n        widen_for_authz=widen_for_authz,\\n        authorized_existing_folder_id=authorized_existing_folder_id,\\n    )\\n    flow.folder_id = folder_id\\n    flow.workspace_id = workspace_id\\n    return workspace_id, folder_id\\n\\n\\nasync def _new_flow(\\n    *,\\n    session: AsyncSession,\\n    flow: FlowCreate,\\n    user_id: UUID,\\n    storage_service: StorageService,\\n    flow_id: UUID | None = None,\\n    fail_on_endpoint_conflict: bool = False,\\n    validate_folder: bool = False,\\n    widen_for_authz: bool = False,\\n    propagate_unhandled_errors: bool = False,\\n):\\n    \\\"\\\"\\\"Create or upsert a flow.\\n\\n    Args:\\n        session: Database session.\\n        flow: Flow creation data.\\n        user_id: Owner of the new flow.\\n        storage_service: Service for filesystem operations.\\n        flow_id: Allows PUT upsert to create flows with a specific ID for syncing between instances.\\n        fail_on_endpoint_conflict: PUT should fail predictably on conflicts rather than silently renaming.\\n        validate_folder: Validates folder_id under the active authorization fetch mode for external upserts.\\n        widen_for_authz: Preserve a cross-user destination that the route already authorized.\\n        propagate_unhandled_errors: Let the caller own retry and sanitization of unexpected failures.\\n    \\\"\\\"\\\"\\n    try:\\n        await _verify_fs_path(flow.fs_path, user_id, storage_service)\\n\\n        if validate_folder and flow.folder_id is not None:\\n            folder = await _get_flow_destination_folder(\\n                session,\\n                user_id,\\n                flow.folder_id,\\n                widen_for_authz=widen_for_authz,\\n            )\\n            if not folder:\\n                raise HTTPException(status_code=400, detail=\\\"Folder not found\\\")\\n\\n        # Set user_id (ignore any user_id from body for security)\\n        flow.user_id = user_id\\n        flow.name = await _deduplicate_flow_name(session, flow.name, user_id)\\n\\n        if flow.endpoint_name:\\n            flow.endpoint_name = await _deduplicate_endpoint_name(\\n          ";
